function polyselfFormWithDiet() {
    const form = polyselfForm();
    if (!form) return null;
    const name = String(form.name || '').toLowerCase();
    const overlay = POLYSELF_DIET_OVERLAY.get(name);
    if (!overlay) return form;
    const result = { ...overlay, ...form };
    if (!Object.prototype.hasOwnProperty.call(result, 'carnivorous')
        && Object.prototype.hasOwnProperty.call(form, 'carnivore'))
        result.carnivorous = form.carnivore;
    return result;
}

function polyselfNoHands() {
    return !!polyselfForm()?.nohands;
}

function adjustedMonsterResumeIndexForRemoval(mon, resumeIndex) {
    if (!resumeIndex || !mon || !game.level?.monsters) return resumeIndex;
    const reverseIndex = [...game.level.monsters].reverse().indexOf(mon);
    if (reverseIndex >= 0 && reverseIndex < resumeIndex)
        return resumeIndex - 1;
    return resumeIndex;
}

function monsterHasOlfaction(data = {}) {
    const name = String(data.name || '').toLowerCase();
    const mlet = data.mlet ?? data.glyph ?? '';
    if (name.endsWith(' golem')) return false;
    if (['e', 'j', 'P', 'b', 'v', 'E', 'F', 'y'].includes(mlet)) return false;
    if (['eye', 'jelly', 'pudding', 'blob', 'vortex', 'elemental', 'fungus', 'light'].includes(mlet)) return false;
    if (/sphere$/.test(name)) return false;
    return true;
}

function scareNearbyOlfactoryMonstersWithGarlic() {
    const form = polyselfForm();
    if (form?.undead) return;
    const ux = game.u?.ux ?? 0;
    const uy = game.u?.uy ?? 0;
    for (const mon of game.level?.monsters || []) {
        const dx = (mon.mx ?? 0) - ux;
        const dy = (mon.my ?? 0) - uy;
        if (dx * dx + dy * dy >= 7 || !monsterHasOlfaction(mon.data)) continue;
        mon.mflee = 1;
        mon.mfleetim = 0;
        clearMonsterTrack(mon);
    }
}

function isWandItem(item) {
    return item?.cls === 'wand' || item?.glyph === '/' || item?.wandIndex != null
        || item?.kind === 'wand of sleep' || item?.kind === 'sleep';
}
const WISHING_WAND_INDEX = 4;
const WAND_WREST_CHANCE = 121;

function isWishingWand(item) {
    const wand = String(item?.wand || '').toLowerCase();
    const kind = String(item?.kind || '').toLowerCase();
    const actualKind = String(item?.actualKind || '').toLowerCase();
    return item?.wandIndex === WISHING_WAND_INDEX
        || wand === 'wishing'
        || kind === 'wishing'
        || kind === 'wand of wishing'
        || actualKind === 'wishing'
        || actualKind === 'wand of wishing';
}

function wandCharges(item, fallback = 0) {
    return item?.spe ?? item?.charges ?? fallback;
}

function setWandCharges(item, charges) {
    item.spe = charges;
    item.charges = charges;
}

function refreshWandLine(item) {
    if (/\(\d+:-?\d+\)/.test(String(item.line || ''))) item.chargeKnown = true;
    item.line = normalInventoryLine({ ...item, line: '' });
}

function setKnownWandLine(item, wand) {
    item.cls = 'wand';
    item.glyph = '/';
    item.wand = wand;
    item.kind = wand;
    item.wandIndex = WAND_NAME_TO_INDEX.get(wand);
    item.known = true;
    refreshWandLine(item);
}

function zappableWand(item, { fallbackCharges = 0 } = {}) {
    const charges = wandCharges(item, fallbackCharges);
    if (charges < 0) return { zapped: false, dust: true };
    if (charges === 0) {
        if (rn2(WAND_WREST_CHANCE)) return { zapped: false };
        setWandCharges(item, -1);
        return { zapped: true, wrested: true };
    }
    setWandCharges(item, charges - 1);
    return { zapped: true };
}

function spendZapWandCharge(item, messages) {
    const charges = wandCharges(item, 8);
    checkUnpaidUsage(item, messages, { chargeCount: charges });
    return zappableWand(item, { fallbackCharges: 8 });
}

function spendEngraveWandCharge(item, messages) {
    const chargeUse = zappableWand(item);
    if (!chargeUse.zapped) return chargeUse;
    checkUnpaidUsage(item, messages, { chargeCount: wandCharges(item) });
    refreshWandLine(item);
    return chargeUse;
}

function spendChargedToolUse(item, messages) {
    const charges = chargedUsageChargeCount(item);
    if (charges <= 0) return false;
    checkUnpaidUsage(item, messages, { chargeCount: charges });
    item.spe = Math.max(0, charges - 1);
    if ('charges' in item) item.charges = item.spe;
    updateChargedItemLine(item);
    return true;
}

function heroHasSlipperyFingers() {
    return !!(game.u?._glibTimeout || game.u?.glib || (game.u?._statusSuffix || '').includes('Slippery'));
}

function heroIsFumbling() {
    return !!(game.u?.fumbling || game.u?._fumblingTimeout || (game.u?._statusSuffix || '').includes('Fumbling')
        || (game.inventory || []).some(item => isWornArmorItem(item)
            && String(item.kind || item.actualKind || '').toLowerCase() === 'fumble boots'));
}

function heroPassesWalls() {
    const forms = [polyselfForm(), game.u?.youmonst?.data, game.u?.data].filter(Boolean);
    const hasPassWallFlag = target => !!(target?.passWalls || target?.passesWalls
        || target?.passes_walls || target?.wallwalk);
    return !!(hasPassWallFlag(game.u) || forms.some(form => {
        const name = String(form.name || '').toLowerCase().trim().replace(/\s+/g, ' ');
        return hasPassWallFlag(form) || name === 'xorn' || name === 'earth elemental';
    }));
}

function heroFormData() {
    return polyselfForm() || game.u?.youmonst?.data || game.u?.data || {};
}

function heroIsHuge() {
    const form = heroFormData();
    if (form.huge || form.msize === 'huge' || form.size === 'huge') return true;
    return heroProjectileMonsterSizeValue({ data: form, msize: form.msize, size: form.size }) >= 4;
}

function heroIsBigMonster() {
    const form = heroFormData();
    if (form.big || form.bigmonst || form.large || form.giant) return true;
    return heroProjectileMonsterSizeValue({ data: form, msize: form.msize, size: form.size }) >= 3;
}

const HERO_RIDING_ROLE_SKILLS = new Map([
    ['Archaeologist', P_BASIC],
    ['Archeologist', P_BASIC],
    ['Barbarian', P_BASIC],
    ['Knight', P_EXPERT],
    ['Rogue', P_BASIC],
    ['Ranger', P_BASIC],
    ['Samurai', P_SKILLED],
    ['Tourist', P_BASIC],
    ['Valkyrie', P_SKILLED],
    ['Wizard', P_BASIC],
]);

function heroRidingSkillLevel() {
    return heroExplicitWeaponSkillLevel(P_RIDING, 'riding')
        ?? HERO_RIDING_ROLE_SKILLS.get(heroRoleName())
        ?? P_UNSKILLED;
}

function heroCanReachFloorForUntrap(checkPit = false) {
    if (game.u?.uswallow) return false;
    if ((game.u?.levitating || game.u?.levitation || game.u?.Levitation)
        && !(Is_airlevel(game.u?.uz) || Is_waterlevel(game.u?.uz)))
        return false;
    if (game.u?.usteed && heroRidingSkillLevel() < P_BASIC) return false;
    if (game.u?.uundetected && heroFormData().ceilingHider) return false;
    if (game.u?.flying || game.u?.Flying || heroIsHuge()) return true;
    if (checkPit) {
        const trap = (game.level?.traps || []).find(candidate =>
            candidate.tx === game.u?.ux && candidate.ty === game.u?.uy);
        if (trap && (trap.ttyp === PIT || trap.ttyp === SPIKED_PIT)) return false;
    }
    return true;
}

function fingersOrGloves() {
    return wornGlovesItem() ? 'gloves' : 'fingers';
}

function wornRingItem(item) {
    return !!item && (item.cls === 'ring' || item.glyph === '=' || item.otyp === RING_CLASS)
        && (item.worn || /\(on (?:left|right) hand\)/.test(String(item.line || '')));
}

function wornArmorInSlot(slot) {
    return (game.inventory || []).find(item => isWornArmorItem(item) && armorSlot(item) === slot) || null;
}

function greaseInaccessibleBlockers(item) {
    if (!item) return [];
    if (isWornArmorItem(item)) {
        const slot = armorSlot(item);
        if (slot === 'body') {
            const cloak = wornArmorInSlot('cloak');
            return cloak && cloak !== item ? [cloak] : [];
        }
        if (slot === 'shirt') {
            return [wornArmorInSlot('cloak'), wornArmorInSlot('body')]
                .filter(blocker => blocker && blocker !== item);
        }
    }
    if (wornRingItem(item)) {
        const gloves = wornGlovesItem();
        return gloves ? [gloves] : [];
    }
    return [];
}

function ownedEquipmentName(item) {
    return `your ${inventoryItemName(item).replace(/^(?:an?|the) /i, '')}`;
}

function ownedEquipmentListName(items) {
    const names = items.map(item => inventoryItemName(item).replace(/^(?:an?|the) /i, ''));
    return `your ${names.join(' and ')}`;
}

function canGreaseObject(item) {
    return !!item && item.cls !== 'coin' && item.letter !== '$'
        && !greaseInaccessibleBlockers(item).length;
}

function canSelectGreaseObject(item) {
    return !!item && item.cls !== 'coin' && item.letter !== '$';
}

function isSqueakyBoardGreaseTool(item) {
    return !!item && item.cls === 'tool' && toolChargeKind(item) === 'can of grease';
}

function isKnownSqueakyBoardOil(item) {
    if (!isPotionOfOil(item)) return false;
    const kind = objectKindKey(item).replace(/^potion of /, '');
    return item.known === true || kind === 'oil'
        || (game._discoveries || []).some(entry =>
            entry.section === 'Potions' && entry.name === 'potion of oil' && entry.known !== false);
}

function isSqueakyBoardSuggestedUntrapTool(item) {
    return isSqueakyBoardGreaseTool(item) || isKnownSqueakyBoardOil(item);
}

function isSqueakyBoardUntrapTool(item) {
    return isSqueakyBoardSuggestedUntrapTool(item) || isPotionObject(item);
}

function isBadSqueakyBoardUntrapTool(item) {
    if (!item || item.cursed) return true;
    if (isPotionOfOil(item)) return !!(item.lamplit || item.burning);
    if (isSqueakyBoardGreaseTool(item)) return (item.spe ?? 0) <= 0;
    return true;
}

function useSqueakyBoardUntrapTool(item, messages) {
    if (isSqueakyBoardGreaseTool(item))
        return spendChargedToolUse(item, messages);
    if (isPotionOfOil(item)) {
        useUpInventoryItem(item, 1);
        identifyPotionOfOil(item);
        return true;
    }
    return false;
}

function squeakyBoardUntrapChance(trap) {
    let chance = 3;
    if (heroIsConfused() || heroIsHallucinating()) chance++;
    if (game.u?.blind || game.u?.Blind) chance++;
    if (heroIsStunned()) chance += 2;
    if (heroIsFumbling()) chance *= 2;
    if (trap?.madeby_u) chance--;
    return Math.max(1, chance);
}

const UNTRAP_WEB_BLADE_NAME_RE = /\b(?:athame|broadsword|crysknife|dagger|katana|knife|long sword|runesword|saber|sabre|scalpel|scimitar|short sword|stiletto|tsurugi|two-handed sword|wakizashi|worm tooth)\b/;

function untrapWebWeaponIsBlade(item) {
    if (!item) return false;
    const weaponClass = item.cls === 'weapon' || item.oclass === 'weapon' || item.glyph === ')';
    return weaponClass && UNTRAP_WEB_BLADE_NAME_RE.test(forceWeaponName(item).toLowerCase());
}

function untrapWebBladeWeapon() {
    const primary = wieldedItem();
    if (untrapWebWeaponIsBlade(primary)) return primary;
    const secondary = forceFightSecondaryWeapon(primary);
    return game._twoweapon && untrapWebWeaponIsBlade(secondary) ? secondary : null;
}

function untrapWebArtifactSpec(item) {
    if (!item) return null;
    const key = String(item.artifact || item.oartifact || artifactObjectName(item) || '')
        .toLowerCase()
        .replace(/^the\s+/, '');
    if (key === 'sting' && item === wieldedItem()) return { name: 'Sting', verb: 'cuts' };
    if (key === 'fire brand') return { name: 'Fire Brand', verb: 'burns' };
    return null;
}

function untrapWebMonsterAt(trap) {
    return (game.level?.monsters || []).find(mon =>
        !mon.dead && mon.mx === trap?.tx && mon.my === trap?.ty) || null;
}

function untrapTrapFailureChance(trap) {
    let chance = 3;
    if (heroIsConfused() || heroIsHallucinating()) chance++;
    if (game.u?.blind || game.u?.Blind) chance++;
    if (heroIsStunned()) chance += 2;
    if (heroIsFumbling()) chance *= 2;
    if (trap?.madeby_u) chance--;
    const role = heroRoleName();
    if (role === 'Ranger' && trap?.ttyp === BEAR_TRAP && chance <= 3) return 0;
    if (role === 'Rogue') {
        if (rn2(2 * MAXULEV) < (game.u?.ulevel || 1)) chance--;
        if (game.u?.uhave?.questart && chance > 1) chance--;
    } else if (role === 'Ranger' && chance > 1) {
        chance--;
    }
    return Math.max(1, chance);
}

function untrapBearTrapFailureChance(trap) {
    return untrapTrapFailureChance(trap);
}

function untrapWebChance(trap) {
    let chance = 3;
    const weapon = untrapWebBladeWeapon();
    if (weapon && !untrapWebMonsterAt(trap)) {
        if (untrapWebArtifactSpec(weapon)) chance = 1;
    } else if (!heroWebmakerForm()) {
        chance = 7;
    }
    if (heroIsConfused() || heroIsHallucinating()) chance++;
    if (game.u?.blind || game.u?.Blind) chance++;
    if (heroIsStunned()) chance += 2;
    if (heroIsFumbling()) chance *= 2;
    if (trap?.madeby_u) chance--;
    const role = heroRoleName();
    if (role === 'Rogue') {
        if (rn2(2 * MAXULEV) < (game.u?.ulevel || 1)) chance--;
        if (game.u?.uhave?.questart && chance > 1) chance--;
    } else if (role === 'Ranger' && chance > 1) {
        chance--;
    }
    return Math.max(1, chance);
}

function untrapWebWhich(trap) {
    return trap?.madeby_u ? 'your' : 'the';
}

function untrapWebSuccessMessage(trap, weapon) {
    const which = untrapWebWhich(trap);
    const artifact = untrapWebArtifactSpec(weapon);
    if (artifact) return `${artifact.name} ${artifact.verb} through ${which} web!`;
    if (weapon) return `You cut through ${which} web.`;
    return `You succeed in removing ${which} web.`;
}

function untrapWebDifficultMessage(trap, underHero) {
    const which = trap?.madeby_u ? 'Your' : underHero ? 'This' : 'That';
    return `${which} web is difficult to remove.`;
}

function untrapBearTrapWhich(trap) {
    return trap?.madeby_u ? 'your' : 'the';
}

function untrapBearTrapDifficultMessage(trap, underHero) {
    const which = trap?.madeby_u ? 'Your' : underHero ? 'This' : 'That';
    return `${which} bear trap is difficult to disarm.`;
}

function untrapLandMineWhich(trap) {
    return trap?.madeby_u ? 'your' : 'the';
}

function untrapLandMineDifficultMessage(trap, underHero) {
    const which = trap?.madeby_u ? 'Your' : underHero ? 'This' : 'That';
    return `${which} land mine is difficult to disarm.`;
}

function untrapShootingTrapName(trap) {
    return trap?.ttyp === ARROW_TRAP ? 'arrow trap' : 'dart trap';
}

function untrapShootingTrapDifficultMessage(trap, underHero) {
    const which = trap?.madeby_u ? 'Your' : underHero ? 'This' : 'That';
    return `${which} ${untrapShootingTrapName(trap)} is difficult to disarm.`;
}

function untrapTrapReachName(trap) {
    if (trap?.ttyp === BEAR_TRAP) return 'bear trap';
    if (trap?.ttyp === LANDMINE) return 'land mine';
    if (trap?.ttyp === ARROW_TRAP) return 'arrow trap';
    if (trap?.ttyp === DART_TRAP) return 'dart trap';
    return 'web';
}

function untrapBoxObjectsAt(x, y) {
    return (game.level?.objects || []).filter(obj =>
        isForceableBoxObject(obj) && obj.ox === x && obj.oy === y);
}

function untrapContainerCountPhrase(count) {
    return count === 1 ? 'is a container' : 'are containers';
}

function untrapHoldingTrapPromptName(trap) {
    if (trap?.ttyp === BEAR_TRAP)
        return trap?.madeby_u ? 'your bear trap' : 'a bear trap';
    if (trap?.ttyp === LANDMINE)
        return trap?.madeby_u ? 'your land mine' : 'a land mine';
    if (trap?.ttyp === ARROW_TRAP)
        return trap?.madeby_u ? 'your arrow trap' : 'an arrow trap';
    if (trap?.ttyp === DART_TRAP)
        return trap?.madeby_u ? 'your dart trap' : 'a dart trap';
    return trap?.madeby_u ? 'your web' : 'a web';
}

function untrapHoldingTrapActionName(trap) {
    if (trap?.ttyp === BEAR_TRAP) return 'Disarm the bear trap';
    if (trap?.ttyp === LANDMINE) return 'Disarm the land mine';
    if (trap?.ttyp === ARROW_TRAP) return 'Disarm the arrow trap';
    if (trap?.ttyp === DART_TRAP) return 'Disarm the dart trap';
    return 'Remove the web';
}

function untrapHoldingTrapContainerPrompt(trap, count) {
    return `There ${untrapContainerCountPhrase(count)} and ${untrapHoldingTrapPromptName(trap)} here.  ${untrapHoldingTrapActionName(trap)}? [ynq] (q)`;
}

// C ref: src/pager.c:doidtrap() — the '^'/#showtrap command.
// C ref: include/defsym.h trap explanations via trap.c:trapname(ttyp, FALSE).
function showtrapTrapName(ttyp) {
    switch (ttyp) {
    case ARROW_TRAP: return 'arrow trap';
    case DART_TRAP: return 'dart trap';
    case ROCKTRAP: return 'falling rock trap';
    case SQKY_BOARD: return 'squeaky board';
    case BEAR_TRAP: return 'bear trap';
    case LANDMINE: return 'land mine';
    case ROLLING_BOULDER_TRAP: return 'rolling boulder trap';
    case SLP_GAS_TRAP: return 'sleeping gas trap';
    case RUST_TRAP: return 'rust trap';
    case FIRE_TRAP: return 'fire trap';
    case PIT: return 'pit';
    case SPIKED_PIT: return 'spiked pit';
    case HOLE: return 'hole';
    case TRAPDOOR: return 'trap door';
    case TELEP_TRAP: return 'teleportation trap';
    case LEVEL_TELEP: return 'level teleporter';
    case MAGIC_PORTAL: return 'magic portal';
    case WEB: return 'web';
    case STATUE_TRAP: return 'statue trap';
    case MAGIC_TRAP: return 'magic trap';
    case ANTI_MAGIC: return 'anti-magic field';
    case POLY_TRAP: return 'polymorph trap';
    case VIBRATING_SQUARE: return 'vibrating square';
    default: return 'trap';
    }
}

// C ref: src/pager.c:doidtrap() — "That is a <trap>[ set/dug/woven by you]."
function showtrapTrapMessage(trap) {
    const name = showtrapTrapName(trap.ttyp);
    const howMade = !trap.madeby_u ? ''
        : trap.ttyp === WEB ? ' woven'
            : (trap.ttyp === HOLE || trap.ttyp === PIT) ? ' dug'
                : ' set';
    return `That is ${indefiniteArticle(name)} ${name}${howMade}${trap.madeby_u ? ' by you' : ''}.`;
}

// C ref: src/detect.c:trapped_chest_at() — known-trapped box on the map.
function showtrapTrappedChestAt(x, y) {
    return (game.level?.objects || []).find(obj =>
        obj.ox === x && obj.oy === y && obj.otrapped && obj.tknown
        && (obj.otyp === CHEST || obj.otyp === LARGE_BOX
            || obj.kind === 'chest' || obj.kind === 'large box'));
}

// C ref: src/version.c:doversion() — the 'V'/#versionshort one-line banner.
const VERSION_SHORT_LINE = 'MacOS NetHack Version 5.0.0 - last build May  2 2026 12:00:00.';

// C ref: src/cmd.c:do_repeat() — the ^A/#repeat command; replays the last
// stored repeatable command (movement, search, or rest) without prompting.
async function repeatLastCommand() {
    const key = game._repeat_last_key;
    if (!key || game._in_doagain) {
        await setMessage('There is no command available to repeat.');
        return;
    }
    game._in_doagain = 1;
    await rhack(key);
    game._in_doagain = 0;
}

function untrapFloorReachMessage(trap, dir, boxes = []) {
    const here = !dir.dx && !dir.dy;
    const parts = [];
    if (trap) parts.push(untrapHoldingTrapPromptName(trap));
    if (boxes.length) parts.push(boxes.length === 1 ? 'a container' : 'containers');
    const plural = (trap && boxes.length > 0) || boxes.length > 1;
    return `There ${plural ? 'are' : 'is'} ${parts.join(' and ')} ${here ? 'here' : 'there'} but you can't reach ${plural ? 'them' : 'it'}${game.u?.usteed ? ' while mounted' : ''}.`;
}

async function blockUntrapFloorReach(trap, dir, boxes = []) {
    if (heroCanReachFloorForUntrap(false)) return false;
    await setMessage(untrapFloorReachMessage(trap, dir, boxes));
    return true;
}

function untrapMayDig(loc) {
    return !(IS_STWALL(loc?.typ) || IS_TREE(loc?.typ)) || !(loc?.wall_info & W_NONDIGGABLE);
}

function untrapMayPasswall(loc) {
    return !IS_STWALL(loc?.typ) || !(loc?.wall_info & W_NONPASSWALL);
}

function untrapHeroBadRock(x, y) {
    const boulder = (game.level?.objects || []).some(obj =>
        !obj.hidden && !obj.transientProjectile && obj.otyp === BOULDER
        && obj.ox === x && obj.oy === y);
    if (In_sokoban(game.u?.uz) && boulder) return true;
    const loc = game.level?.at?.(x, y);
    if (!loc || !IS_OBSTRUCTED(loc.typ)) return false;
    const form = heroFormData();
    const tunnels = !!(form.tunnel || form.tunnels || form.dwarf);
    const needPick = !!(form.needPick || form.need_pick);
    return (!tunnels || needPick || !untrapMayDig(loc))
        && !(heroPassesWalls() && untrapMayPasswall(loc));
}

function heroTooLargeForTightDiagonal() {
    const form = heroFormData();
    if (!heroIsBigMonster()) return false;
    const name = String(form.name || '').toLowerCase();
    return !(form.amorphous || form.whirly || form.unsolid || form.noncorporeal
        || form.slithy || name === 'fog cloud');
}

function heroTightDiagonalCarriedWeight() {
    const throwsRocks = !!(game.u?.throwsRocks || heroFormData().throwsRocks);
    let weight = Math.max(0, Math.trunc(((game._goldCount || 0) + 50) / 100));
    for (const item of game.inventory || []) {
        if (isGoldObject(item)) continue;
        if (throwsRocks && item?.otyp === BOULDER) continue;
        weight += globObjectWeight(item);
    }
    return weight;
}

async function blockUntrapTightDiagonalReach(trap, dir) {
    if (!dir.dx || !dir.dy) return false;
    if (!(untrapHeroBadRock(game.u?.ux, trap.ty) && untrapHeroBadRock(trap.tx, game.u?.uy)))
        return false;
    if (heroTightDiagonalCarriedWeight() <= WT_TOOMUCH_DIAGONAL && !heroTooLargeForTightDiagonal())
        return false;
    await setMessage(`You are unable to reach the ${untrapTrapReachName(trap)}!`);
    return true;
}

function untrapBoxObjectName(box) {
    const name = forceBoxSimpleName(box);
    return box?.lknown && (box.locked || box.olocked) ? `locked ${name}` : name;
}

function untrapBoxArticleName(box) {
    const name = untrapBoxObjectName(box);
    return `${/^[aeiou]/i.test(name) ? 'an' : 'a'} ${name}`;
}

function untrapBoxPrompt(box) {
    if (box?.tknown && box?.dknown)
        return `Disarm this ${untrapBoxObjectName(box)}? [ynq] (q)`;
    return `There is ${untrapBoxArticleName(box)} here.  Check it for traps? [ynq] (q)`;
}

function heroHasMasterKeyOfThievery() {
    const expected = questArtifactNameKey('The Master Key of Thievery');
    const rogue = heroRoleName() === 'Rogue';
    return (game.inventory || []).some(item => {
        if (item?.otyp != null && item.otyp !== SKELETON_KEY) return false;
        const isMasterKey = [
            item?.artifact,
            item?.oartifact,
            item?.name,
            item?.actualKind,
            item?.kind,
        ].some(name => questArtifactNameKey(name) === expected);
        if (!isMasterKey) return false;
        return rogue ? !item?.cursed : !!item?.blessed;
    });
}

function untrapForce() {
    return heroHasMasterKeyOfThievery();
}

async function beginUntrapBoxPrompt(boxes, { trapSkipped = false, force = false, x = null, y = null } = {}) {
    const targets = boxes.filter(Boolean);
    if (!targets.length) return false;
    game._untrap_box_state = { boxes: targets, index: 0, trapSkipped, force, x, y };
    game._command_mode = 'untrapBoxConfirm';
    await setMessage(untrapBoxPrompt(targets[0]));
    return true;
}

function untrapBoxDetectionSucceeds(box, confused, force = false) {
    if (box?.otrapped) {
        if (force) return true;
        const denom = Math.max(1, MAXULEV + 1 - (game.u?.ulevel || 1));
        if (!confused && rn2(denom) < 10) return true;
    }
    if (box?.tknown) return true;
    return !force && confused && !rn2(3);
}

function untrapBoxDisarmChance() {
    let chance = (game.u?.acurr?.a?.[A_DEX] ?? 10) + (game.u?.ulevel || 1);
    if (heroRoleName() === 'Rogue') chance *= 2;
    return chance;
}

function chestTrapLuckMessage(roll) {
    if (roll >= 11) return 'explosive charge is a dud';
    if (roll >= 9) return 'electric charge is grounded';
    if (roll >= 7) return 'flame fizzles out';
    if (roll >= 4) return 'poisoned needle misses';
    return 'gas cloud blows away';
}

function chestTrapPayloadRoll(luck) {
    return rn2(20) ? (luck >= 13 ? 0 : rn2(13 - luck)) : rn2(26);
}

const CHEST_TRAP_OBJECT_COLORS = [
    'black', 'red', 'green', 'brown', 'blue', 'magenta', 'cyan', 'gray',
    'colorless', 'orange', 'bright green', 'yellow', 'bright blue',
    'bright magenta', 'bright cyan', 'white',
];
const CHEST_TRAP_BLIND_GAS = ['humid', 'odorless', 'pungent', 'chilling', 'acrid', 'biting'];
const CHEST_TRAP_HALLUCINATED_COLORS = [
    'ultraviolet', 'infrared', 'bluish-orange', 'reddish-green', 'dark white',
    'light black', 'sky blue-pink', 'pinkish-cyan', 'indigo-chartreuse',
    'salty', 'sweet', 'sour', 'bitter', 'umami',
    'striped', 'spiral', 'swirly', 'plaid', 'checkered', 'argyle', 'paisley',
    'blotchy', 'guernsey-spotted', 'polka-dotted', 'square', 'round',
    'triangular', 'cabernet', 'sangria', 'fuchsia', 'wisteria', 'lemon-lime',
    'strawberry-banana', 'peppermint', 'romantic', 'incandescent',
    'octarine', 'excitingly dull', 'mauve', 'electric',
    'neon', 'fluorescent', 'phosphorescent', 'translucent', 'opaque',
    'psychedelic', 'iridescent', 'rainbow-colored', 'polychromatic',
    'colorless', 'colorless green',
    'dancing', 'singing', 'loving', 'loudy', 'noisy', 'clattery', 'silent',
    'apocyan', 'infra-pink', 'opalescent', 'violant', 'tuneless',
    'viridian', 'aureolin', 'cinnabar', 'purpurin', 'gamboge', 'madder',
    'bistre', 'ecru', 'fulvous', 'tekhelet', 'selective yellow',
];

function heroHasHallucinationResistance() {
    if (game.u?.hallucinationResistance || game.u?.hallucination_resistance) return true;
    if ((game.inventory || []).some(item => item.wielded && item.artifact === 'Grayswandir')) return true;
    return (game.inventory || []).some(item =>
        isActiveInventoryExtrinsicItem(item) && dragonArmorKindHasProperty(objectKindKey(item), 'hallucination'));
}

function heroHasActiveHallucination() {
    return heroIsHallucinating() && !heroHasHallucinationResistance();
}

function chestTrapGasName() {
    if (heroIsBlind()) return CHEST_TRAP_BLIND_GAS[rn2(CHEST_TRAP_BLIND_GAS.length)];
    const colorIndex = rn2(CHEST_TRAP_OBJECT_COLORS.length);
    if (heroHasActiveHallucination())
        return CHEST_TRAP_HALLUCINATED_COLORS[rn2_on_display_rng(CHEST_TRAP_HALLUCINATED_COLORS.length)];
    return CHEST_TRAP_OBJECT_COLORS[colorIndex];
}

function chestTrapGasStaggerMessage() {
    if (heroIsStunned()) return '';
    if (heroHasActiveHallucination()) return 'What a groovy feeling!';
    const suffix = heroHasHallucinationResistance()
        ? ''
        : heroIsBlind() ? ' and get dizzy' : ' and your vision blurs';
    return `You stagger${suffix}...`;
}

function chestTrapObjectName(box) {
    return forceBoxSimpleName(box);
}

function applyChestTrapElectricPayload(messages) {
    const origDamage = d(4, 4);
    let baseDamage = origDamage;
    messages.push('You are jolted by a surge of electricity!');
    if (heroHasShockResistance()) {
        messages.push("You don't seem to be affected.");
        baseDamage = 0;
    }

    const electricInventory = electricDamageInventory(origDamage);
    messages.push(...electricInventory.messages);

    const hpBefore = game.u?.uhp || 0;
    const damage = (game.u?.uinvulnerable ? 0 : baseDamage) + electricInventory.damage;
    if (damage && game.u) game.u.uhp = Math.max(0, hpBefore - damage);
    if ((game.u?.uhp || 0) > 0) return {};

    game._death_cause = electricInventory.damage >= hpBefore && electricInventory.deathCause
        ? electricInventory.deathCause
        : 'killed by an electric shock';
    if (consumeLifeSavingAmulet()) {
        if (game.u) game.u.uhp = 0;
        messages.push(`You die...  But wait...  Your medallion ${game.u?.blind ? 'feels warm' : 'begins to glow'}!`);
        return { lifeSaving: true, more: true };
    }
    messages.push('You die...');
    return { fatal: true, more: true };
}

function heroHasFireResistance() {
    if (game.u?.fireResistance) return true;
    return (game.inventory || []).some(item => activeInventoryResistanceKind(item) === 'fire');
}

function chestTrapBoxCarried(box) {
    return !!box && (box.where === OBJ_INVENT || (game.inventory || []).includes(box));
}

function chestTrapBoxInPool(box) {
    if (!box) return false;
    if (chestTrapBoxCarried(box)) return heroIsUnderwater();
    const loc = game.level?.at?.(box.ox ?? game.u?.ux ?? 0, box.oy ?? game.u?.uy ?? 0);
    return !!loc && (IS_POOL(loc.typ) || loc.typ === WATER || loc.typ === MOAT);
}

function heroPolyselfFireHpState() {
    if (!game.u?._polyself_form) return null;
    if (game.u.mh != null || game.u.mhmax != null)
        return { hpKey: 'mh', maxKey: 'mhmax' };
    return { hpKey: 'uhp', maxKey: 'uhpmax' };
}

function polyselfFireGolemMaxDamage(form, maxHp) {
    const name = String(form?.name || '').toLowerCase();
    if (name === 'paper golem') return maxHp;
    if (name === 'straw golem') return Math.trunc(maxHp / 2);
    if (name === 'wood golem') return Math.trunc(maxHp / 4);
    if (name === 'leather golem') return Math.trunc(maxHp / 8);
    return 0;
}

function applyPolyselfFireMaxHpLoss(origDamage) {
    const state = heroPolyselfFireHpState();
    if (!state || !game.u) return null;
    const form = game.u._polyself_form || {};
    let damage = origDamage;
    const maxHp = Math.max(1, Math.trunc(Number(game.u[state.maxKey] ?? game.u[state.hpKey] ?? 1)));
    const golemDamage = polyselfFireGolemMaxDamage(form, maxHp);
    if (golemDamage > damage) damage = golemDamage;
    const level = Math.max(0, Math.trunc(Number(form.mlevel ?? form.level ?? form.hpLevel ?? 0)));
    if (maxHp > level) {
        const loss = rn2(Math.min(maxHp, damage + 1));
        game.u[state.maxKey] = Math.max(1, maxHp - loss);
    } else {
        game.u[state.maxKey] = maxHp;
    }
    game.u[state.hpKey] = Math.min(game.u[state.hpKey] ?? game.u[state.maxKey], game.u[state.maxKey]);
    return damage;
}

function applyChestTrapFireDamage(messages, damage, deathCause) {
    if (!damage || game.u?.uinvulnerable) return {};
    const polyselfHp = heroPolyselfFireHpState();
    if (polyselfHp && game.u) {
        game.u[polyselfHp.hpKey] = Math.max(0, (game.u[polyselfHp.hpKey] || 0) - damage);
        if ((game.u[polyselfHp.hpKey] || 0) > 0) return {};
        if (heroHasUnchanging()) {
            game._death_cause = 'killed while stuck in creature form';
            messages.push('You die...');
            return { lifeSaving: false, fatal: true, more: true };
        }
        const result = rehumanizeAfterPolyselfDeath();
        appendRehumanizeDeathResultMessages(messages, result, { allowLifeSaving: true });
        return {
            genocideDeathArmed: !!messages.genocideDeathArmed,
            lifeSaving: !!messages.lifeSaving,
            fatal: !!messages.fatal,
            more: !!messages.more,
        };
    }
    if (game.u) game.u.uhp = Math.max(0, (game.u.uhp || 0) - damage);
    if ((game.u?.uhp || 0) > 0) return {};
    return heroDartTrapFatalResult(messages, deathCause);
}

function applyChestTrapFirePayload(box, messages) {
    const origDamage = d(2, 4);
    if (chestTrapBoxInPool(box)) {
        messages.push(`A cascade of steamy bubbles erupts from the ${chestTrapObjectName(box)}!`);
        if (heroHasFireResistance()) {
            messages.push('You are uninjured.');
            return {};
        }
        return applyChestTrapFireDamage(messages, rnd(3), 'killed by boiling water');
    }

    messages.push(`A tower of flame bursts from the ${chestTrapObjectName(box)}!`);
    let damage;
    if (heroHasFireResistance()) {
        damage = rn2(2);
        if (!damage) messages.push('You are uninjured.');
    } else if (game.u?._polyself_form) {
        damage = applyPolyselfFireMaxHpLoss(origDamage);
    } else {
        damage = d(2, 4);
        if (game.u) {
            const hpMin = 1;
            const oldMax = game.u.uhpmax || hpMin;
            const loss = rn2(Math.min(oldMax, damage + 1));
            game.u.uhpmax = Math.max(hpMin, oldMax - loss);
            game.u.uhp = Math.min(game.u.uhp || hpMin, game.u.uhpmax);
        }
    }

    const directResult = applyChestTrapFireDamage(messages, damage, 'killed by a tower of flame');
    if (directResult.genocideDeathArmed || directResult.fatal) return directResult;
    if (directResult.lifeSaving) restoreLifeSavedHeroForContinuation();

    burnAwayHeroSlime(messages);
    const fireInventory = fireDamageInventory(origDamage, false, false, { allowLifeSaving: true });
    messages.push(...fireInventory.messages);
    if (fireInventory.lifeSaving || fireInventory.fatal) {
        game._death_cause = fireInventory.deathCause || 'killed by a tower of flame';
        return {
            lifeSaving: fireInventory.fatal ? !!fireInventory.lifeSaving : !!directResult.lifeSaving || !!fireInventory.lifeSaving,
            fatal: !!fireInventory.fatal,
            more: true,
        };
    }

    const inventoryDamageResult = applyChestTrapFireDamage(messages, fireInventory.damage, fireInventory.deathCause || 'killed by a tower of flame');
    if (directResult.lifeSaving && !inventoryDamageResult.lifeSaving && !inventoryDamageResult.fatal && game.u) {
        game._life_saving_post_continue_hp = game.u.uhp;
    }
    return {
        ...inventoryDamageResult,
        lifeSaving: inventoryDamageResult.fatal ? !!inventoryDamageResult.lifeSaving : !!directResult.lifeSaving || !!inventoryDamageResult.lifeSaving,
        more: !!directResult.more || !!inventoryDamageResult.more,
    };
}

function chestTrapExplosionObjectsAt(box) {
    const x = box?.ox ?? game.u?.ux ?? 0;
    const y = box?.oy ?? game.u?.uy ?? 0;
    return (game.level?.objects || []).filter(obj => obj.ox === x && obj.oy === y);
}

function chestTrapExplosionAddShopCharges(charges, source, obj, shkp, options = {}) {
    const itemCharges = lostShopMerchandiseChargesForObject(source, obj, shkp, new Set(), options);
    for (const [owner, value] of itemCharges)
        addLostShopMerchandiseCharge(charges, owner, value);
}

function chestTrapExplosionShopContext(box, floorObjects) {
    const x = box?.ox ?? game.u?.ux ?? 0;
    const y = box?.oy ?? game.u?.uy ?? 0;
    const shkp = shopkeeperForCostlySpot(x, y);
    if (!shopkeeperInHisShop(shkp)) return null;
    const source = { ox: x, oy: y };
    const charges = new Map();
    chestTrapExplosionAddShopCharges(charges, source, box, shkp);
    for (const obj of floorObjects) {
        chestTrapExplosionAddShopCharges(charges, source, obj, shkp, obj === box ? { includeContents: false } : {});
    }
    return { shkp, charges };
}

function chestTrapExplosionShopMessage(context) {
    if (!context?.charges?.size) return '';
    const insider = heroInShopOwnedBy(context.shkp);
    let charged = 0;
    for (const [shkp, value] of context.charges)
        charged += chargeShopkeeperForLostMerchandise(shkp, value, {
            peaceful: insider && shopkeeperPeacefulForDebt(context.shkp),
        });
    if (!(charged > 0)) return '';
    if (insider) return `You owe ${charged} ${shopCurrency(charged)} for objects destroyed.`;
    if (shopkeeperPeacefulForDebt(context.shkp)) {
        context.shkp.angry = true;
        context.shkp.hostile = true;
        context.shkp.mpeaceful = 0;
        context.shkp.following = 1;
    }
    return `You caused ${charged} ${shopCurrency(charged)} worth of damage!`;
}

function chestTrapExplosionObjectResistsDeletion(obj) {
    if (drainItemAlwaysResists(obj)) return true;
    rn2(100);
    return false;
}

function wakeNearbyMonstersFromChestTrapExplosion(messages = null) {
    const distance = Math.max(0, Math.trunc(Number(game.u?.ulevel || 1))) * 20;
    wakeNearbyMonstersAt(game.u?.ux || 0, game.u?.uy || 0, distance, messages);
}

function deleteChestTrapExplosionObjects(box, floorObjects) {
    const doomed = new Set();
    clearLiquidFlowContainerContents(box);
    for (const obj of floorObjects) {
        if (chestTrapExplosionObjectResistsDeletion(obj)) continue;
        doomed.add(obj);
        clearLiquidFlowContainerContents(obj);
    }
    game.level.objects = (game.level?.objects || []).filter(obj => !doomed.has(obj));
    for (const obj of doomed) newsym(obj.ox, obj.oy);
    return doomed.has(box);
}

function applyChestTrapExplosionPayload(box, messages) {
    messages.push(`The ${chestTrapObjectName(box)} explodes!`);
    const floorObjects = chestTrapExplosionObjectsAt(box);
    const shopContext = chestTrapExplosionShopContext(box, floorObjects);
    const boxDestroyed = deleteChestTrapExplosionObjects(box, floorObjects);
    wakeNearbyMonstersFromChestTrapExplosion(messages);

    const damage = maybeHalfPhysicalDamage(d(6, 6));
    const damageResult = applyChestTrapFireDamage(messages, damage, `killed by an exploding ${chestTrapObjectName(box)}`);
    if (damageResult.fatal) return { ...damageResult, boxDestroyed };
    exerciseAttribute(A_STR, false);
    const shopMessage = chestTrapExplosionShopMessage(shopContext);
    if (shopMessage) messages.push(shopMessage);
    return { ...damageResult, boxDestroyed };
}

function chestTrapPoisonTell(attr) {
    if (attr === A_STR) return (game.u?.acurr?.a?.[A_STR] === STR19(25))
        ? 'You feel innately weaker!'
        : 'You feel weaker!';
    if (attr === A_CON) return (game.u?.acurr?.a?.[A_CON] === 25)
        ? 'You feel sick inside!'
        : 'You feel very sick!';
    return '';
}

function applyChestTrapPoisonAttributeLoss(messages, attr, loss) {
    if (!adjustHeroAttribute(attr, -loss)) return;
    const message = chestTrapPoisonTell(attr);
    if (message) messages.push(message);
}

function applyChestTrapPoison(messages, {
    reason,
    attr,
    fatal,
    deathCause,
}) {
    const cloud = reason === 'gas cloud';
    if (!/poison/i.test(reason)) messages.push(`The ${reason} was poisoned!`);
    if (heroHasPoisonResistance()) {
        messages.push("The poison doesn't seem to affect you.");
        return {};
    }

    const roll = fatal ? rn2(fatal) : 1;
    if (roll === 0 && attr !== A_CHA) {
        const loss = 6 + d(4, 6);
        if ((game.u?.uhp || 0) <= loss) {
            messages.push('The poison was deadly...');
            return heroDartTrapFatalResult(messages, deathCause);
        }
        if (game.u) {
            game.u.uhpmax = Math.max(3, (game.u.uhpmax || game.u.uhp || 1) - Math.trunc(loss / 2));
            game.u.uhp = Math.max(0, (game.u.uhp || 0) - loss);
        }
        applyChestTrapPoisonAttributeLoss(messages, A_CON, attr === A_CON ? 3 : 1);
        if (attr !== A_CON) applyChestTrapPoisonAttributeLoss(messages, attr, 3);
        if ((game.u?.uhp || 0) <= 0)
            return heroDartTrapFatalResult(messages, deathCause);
        return {};
    }

    if (roll > 5) {
        let loss = rn1(10, 6);
        if (cloud && heroHasWetWornTowel()) loss = Math.trunc((loss + 1) / 2);
        if (game.u) game.u.uhp = Math.max(0, (game.u.uhp || 0) - loss);
        if ((game.u?.uhp || 0) <= 0)
            return heroDartTrapFatalResult(messages, deathCause);
        return {};
    }

    applyChestTrapPoisonAttributeLoss(messages, attr, fatal ? d(2, 2) : 1);
    return {};
}

function applyChestTrapNeedlePayload(messages, bodyPart = 'finger') {
    messages.push(`You feel a needle prick your ${bodyPart}.`);
    const result = applyChestTrapPoison(messages, {
        reason: 'needle',
        attr: A_CON,
        fatal: 10,
        deathCause: 'killed by a poisoned needle',
    });
    if (!result.fatal) exerciseAttribute(A_CON, false);
    return result;
}

function heroOkWithChestTrapPoisonGas() {
    const form = polyselfForm() || {};
    const magicalBreathing = (game.inventory || []).some(item =>
        isWornInventoryItem(item) && objectKindKey(item) === 'amulet of magical breathing');
    return !!(game.u?.uinvulnerable || game.u?.underwater || game.u?.uunderwater
        || magicalBreathing || form.breathless || form.nonliving);
}

function applyChestTrapNoxiousGasPayload(box, messages) {
    messages.push(`A cloud of noxious gas billows from the ${chestTrapObjectName(box)}.`);
    let result = {};
    if (rn2(3)) {
        result = applyChestTrapPoison(messages, {
            reason: 'gas cloud',
            attr: A_STR,
            fatal: 15,
            deathCause: 'killed by a cloud of poison gas',
        });
    } else {
        const wasInside = heroInsideGasCloud();
        const region = createGasCloud(box?.ox ?? game.u?.ux ?? 0, box?.oy ?? game.u?.uy ?? 0, 1, 8);
        if (region) region.heroFault = true;
        const enveloped = !wasInside && !heroOkWithChestTrapPoisonGas()
            && region?.coords?.some(coord => coord.x === (game.u?.ux ?? -1) && coord.y === (game.u?.uy ?? -1));
        if (enveloped) messages.push('You are enveloped in a cloud of noxious gas!');
    }
    if (!result.fatal) exerciseAttribute(A_CON, false);
    return result;
}

export function applyChestTrapPayload(box, { disarm = true, needleBodyPart = 'finger' } = {}) {
    const messages = [disarm ? 'You set it off!' : 'You trigger a trap!'];
    let result = {};
    if (box) {
        box.tknown = false;
        box.otrapped = false;
    }
    const luck = Math.trunc(Number(game.u?.uluck || 0) + Number(game.u?.moreluck || 0));
    if (luck > -13 && rn2(13 + luck) > 7) {
        messages.push(`But luckily the ${chestTrapLuckMessage(rn2(13))}!`);
        if (box) box.tknown = true;
        return trapMessage(...messages);
    }

    const payload = chestTrapPayloadRoll(luck);
    if (payload <= 2) {
        messages.push(`A cloud of ${chestTrapGasName()} gas billows from the ${chestTrapObjectName(box)}.`);
        const staggerMessage = chestTrapGasStaggerMessage();
        if (staggerMessage) messages.push(staggerMessage);
        addHeroStun(rn1(7, 16));
        addHeroHallucination(rn1(5, 16));
    } else if (payload >= 3 && payload <= 5) {
        if (heroHasFreeAction()) {
            messages.push('You momentarily stiffen.');
        } else {
            messages.push('Suddenly you are frozen in place!');
            const duration = d(5, 6);
            game._helpless_time = Math.max(game._helpless_time || 0, duration);
            game._wake_message = 'You can move again.';
            game._multi_reason = 'frozen by a trap';
            exerciseAttribute(A_DEX, false);
        }
    } else if (payload >= 6 && payload <= 8) {
        result = applyChestTrapElectricPayload(messages);
    } else if (payload >= 9 && payload <= 12) {
        result = applyChestTrapFirePayload(box, messages);
    } else if (payload >= 13 && payload <= 16) {
        result = applyChestTrapNeedlePayload(messages, needleBodyPart);
    } else if (payload >= 17 && payload <= 20) {
        result = applyChestTrapNoxiousGasPayload(box, messages);
    } else if (payload >= 21 && payload <= 25) {
        result = applyChestTrapExplosionPayload(box, messages);
    }
    if (box && !result.fatal && !result.boxDestroyed) box.tknown = true;
    const message = trapMessage(...messages);
    return result.fatal || result.lifeSaving || result.more
        ? { message, ...result }
        : message;
}

function disarmUntrapBox(box, confused, force = false) {
    if (box?.otrapped) {
        const difficulty = 75 + Math.trunc(level_difficulty() / 2);
        if (!force && (confused || heroIsFumbling() || rnd(difficulty) > untrapBoxDisarmChance())) {
            const result = applyChestTrapPayload(box);
            if (!(result && typeof result === 'object' && result.fatal))
                exerciseAttribute(A_DEX, true);
            return result;
        }
        box.otrapped = false;
        box.tknown = true;
        exerciseAttribute(A_DEX, true);
        if (game.u) game.u.uexp = (game.u.uexp || 0) + 8;
        return 'You disarm it!';
    }
    if (box) box.tknown = false;
    return `That ${untrapBoxObjectName(box)} was not trapped.`;
}

function untrapDoorDetectionSucceeds(loc, confused, force = false) {
    if (loc?.doormask & D_TRAPPED) {
        if (force) return true;
        const denom = Math.max(1, MAXULEV - (game.u?.ulevel || 1) + 11);
        if (!confused && rn2(denom) < 10) return true;
    }
    return !force && confused && !rn2(3);
}

function untrapDoorDisarmChance() {
    const level = game.u?.ulevel || 1;
    return 15 + (heroRoleName() === 'Rogue' ? level * 3 : level);
}

function disarmUntrapDoor(loc, x, y, confused, force = false) {
    if (loc?.doormask & D_TRAPPED) {
        exerciseAttribute(A_DEX, true);
        const difficulty = 75 + Math.trunc(level_difficulty() / 2);
        if (!force && (confused || heroIsFumbling() || rnd(difficulty) > untrapDoorDisarmChance())) {
            const explosion = applyBoobyTrapExplosion({ item: 'door', bodypart: true });
            if (explosion.fatal) {
                return {
                    ...explosion,
                    message: trapMessage('You set it off!', explosion.message),
                };
            }
            loc.doormask = D_NODOOR;
            loc.flags = D_NODOOR;
            newsym(x, y);
            addShopTerrainDamage(x, y, 0);
            return {
                ...explosion,
                message: trapMessage('You set it off!', explosion.message),
            };
        }
        loc.doormask &= ~D_TRAPPED;
        loc.flags = loc.doormask;
        if (game.u) game.u.uexp = (game.u.uexp || 0) + 8;
        return 'You disarm it!';
    }
    return 'This door was not trapped.';
}

async function checkUntrapDoor(loc, x, y, {
    force = false,
    confused = heroIsConfused() || heroIsHallucinating(),
    prefix = '',
} = {}) {
    if (!loc || loc.typ !== DOOR) return false;
    const doorMessage = message => prefix ? trapMessage(prefix, message) : message;
    switch (loc.doormask) {
        case D_NODOOR:
            await setMessage(doorMessage(`You ${game.u?.blind ? 'feel' : 'see'} no door there.`));
            return true;
        case D_ISOPEN:
            await setMessage(doorMessage('This door is safely open.'));
            return true;
        case D_BROKEN:
            await setMessage(doorMessage('This door is broken.'));
            return true;
        default:
            break;
    }

    if (untrapDoorDetectionSucceeds(loc, confused, force)) {
        exerciseAttribute(A_WIS, true);
        await setMessage(doorMessage('You find a trap on the door!  Disarm it? [ynq] (q)'));
        game._untrap_door_state = { loc, x, y, confused, force };
        game._command_mode = 'untrapDoorDisarmConfirm';
        return true;
    }
    await setMessage(doorMessage('You find no traps on the door.'));
    game.context.move = 1;
    return true;
}

async function checkUntrapBox(box, { force = false, confused = heroIsConfused() || heroIsHallucinating() } = {}) {
    if (untrapBoxDetectionSucceeds(box, confused, force)) {
        const knownTrap = box?.tknown && box?.dknown;
        if (box) {
            box.tknown = true;
            if (!heroIsHallucinating()) {
                box.dknown = true;
                recordObservedObjectDiscovery(box);
            }
        }
        if (!confused) exerciseAttribute(A_WIS, true);
        await setMessage(knownTrap
            ? `There's a trap on the ${untrapBoxObjectName(box)}.  Disarm it? [ynq] (q)`
            : `You find a trap on the ${untrapBoxObjectName(box)}!  Disarm it? [ynq] (q)`);
        game._untrap_box_disarm_state = { box, confused, force };
        game._command_mode = 'untrapBoxDisarmConfirm';
        return;
    }
    await setMessage(`You find no traps on the ${untrapBoxObjectName(box)}.`);
    game.context.move = 1;
}

async function declineCurrentUntrapBox() {
    const state = game._untrap_box_state;
    if (!state) {
        game._command_mode = null;
        return;
    }
    state.index = (state.index || 0) + 1;
    const next = state.boxes[state.index];
    if (next) {
        await setMessage(untrapBoxPrompt(next));
        return;
    }
    game._untrap_box_state = null;
    game._command_mode = null;
    const loc = Number.isInteger(state.x) && Number.isInteger(state.y)
        ? game.level?.at?.(state.x, state.y)
        : null;
    const noMoreBoxes = 'There are no other chests or boxes here.';
    if (loc?.typ === DOOR && await checkUntrapDoor(loc, state.x, state.y, {
        force: !!state.force,
        prefix: noMoreBoxes,
    }))
        return;
    await setMessage(state.trapSkipped
        ? noMoreBoxes
        : `${noMoreBoxes}  You know of no traps there.`, !state.trapSkipped);
}

function forceHeroIntoWebTrapMessage(trap) {
    if (trap) trap.tseen = true;
    const webName = webTrapName(trap);
    const destroyVerb = heroWebDestructionVerb();
    if (destroyVerb) {
        deleteTrap(trap);
        return `You ${destroyVerb} ${webName}!`;
    }
    if (heroFlowsThroughWeb()) return `You flow through ${webName}.`;
    if (heroWebmakerForm())
        return trap?.madeby_u ? 'You take a walk on your web.' : 'There is a spider web here.';
    const messages = [`You are caught by ${webName}!`];
    const tim = webTrapTimeFromStrength();
    setHeroWebTrapTime(tim);
    if (tim <= 0) {
        deleteTrap(trap);
        messages.push(`You tear through ${webTrapTearName(trap)}!`);
    }
    return trapMessage(...messages);
}

function applyHeroWebTrapNoMessage(trap) {
    if (trap) trap.tseen = true;
    if (heroWebDestructionVerb()) {
        deleteTrap(trap);
        return;
    }
    if (heroFlowsThroughWeb() || heroWebmakerForm()) return;
    const tim = webTrapTimeFromStrength();
    setHeroWebTrapTime(tim);
    if (tim <= 0) deleteTrap(trap);
}

async function spreadWebToHeroFromUntrap() {
    if (heroWebmakerForm() || rn2(3)) return '';
    const x = game.u?.ux || 0;
    const y = game.u?.uy || 0;
    let heroTrap = (game.level?.traps || []).find(trap => trap.tx === x && trap.ty === y) || null;
    if (heroTrap && heroTrap.ttyp !== WEB) return '';
    if (!heroTrap) heroTrap = await maketrap(x, y, WEB);
    if (!heroTrap) return '';
    applyHeroWebTrapNoMessage(heroTrap);
    return "The web sticks to you.  You're caught too!";
}

async function moveHeroIntoFailedUntrapWeb(trap, dir) {
    if (dir.dx || dir.dy) {
        const oldx = game.u?.ux || 0;
        const oldy = game.u?.uy || 0;
        if (game.u) {
            game.u.ux0 = oldx;
            game.u.uy0 = oldy;
            game.u.ux = trap.tx;
            game.u.uy = trap.ty;
            game.u.umoved = true;
            if (game.u.usteed) {
                game.u.usteed.mx = trap.tx;
                game.u.usteed.my = trap.ty;
            }
        }
        newsym(oldx, oldy);
        newsym(trap.tx, trap.ty);
        vision_recalc(1);
    }
    return forceHeroIntoWebTrapMessage(trap);
}

async function handleUntrapWebTrap(trap, dir) {
    const underHero = !dir.dx && !dir.dy;
    const trapName = 'web';
    if ((game.u?.utrap || 0) > 0) {
        await setMessage(`You cannot deal with the ${trapName} while trapped${underHero ? ' in it' : ''}!`);
        game.context.move = 1;
        return true;
    }
    const boulder = (game.level?.objects || []).find(obj =>
        !obj.hidden && !obj.transientProjectile && obj.otyp === BOULDER
        && obj.ox === trap.tx && obj.oy === trap.ty);
    if (boulder && !underHero && !heroPassesWalls()) {
        await setMessage('There is a boulder in your way.');
        return true;
    }
    const monster = untrapWebMonsterAt(trap);
    if (monster && !monster.mtrapped) {
        await setMessage(`${earthquakeMonsterName(monster)} is in the way.`);
        return true;
    }
    if (await blockUntrapTightDiagonalReach(trap, dir)) return true;
    if (!heroCanReachFloorForUntrap(underHero)) {
        if (game.u?.usteed && heroRidingSkillLevel() < P_BASIC)
            await setMessage("You aren't skilled enough to reach from a steed.");
        else
            await setMessage(`You are unable to reach the ${trapName}!`);
        return true;
    }

    const failed = rn2(untrapWebChance(trap));
    if (failed) {
        if (rnl(5)) {
            const messages = ['Whoops...'];
            if (monster) {
                const spread = await spreadWebToHeroFromUntrap();
                if (spread) messages.push(spread);
                if (monster.mtrapped) messages.push(`${earthquakeMonsterName(monster)} remains entangled.`);
            } else {
                messages.push(await moveHeroIntoFailedUntrapWeb(trap, dir));
            }
            await setMessage(trapMessage(...messages), messages.length > 1);
        } else {
            await setMessage(untrapWebDifficultMessage(trap, underHero));
        }
        game.context.move = 1;
        return true;
    }

    if (monster) {
        monster.mtrapped = 0;
        const messages = [
            `You extract ${earthquakeMonsterName(monster, { capital: false })} from ${untrapWebWhich(trap)} web.`,
            ...rewardUntrapHoldingMonster(trap, monster),
        ];
        await setMessage(trapMessage(...messages), messages.length > 1);
        game.context.move = 1;
        return true;
    }

    const weapon = untrapWebBladeWeapon();
    const message = untrapWebSuccessMessage(trap, weapon);
    deleteTrap(trap);
    await setMessage(message);
    game.context.move = 1;
    return true;
}

