async function setSanctumScriptMessage(message, more = false) {
    const text = `${message}${more ? '--More--' : ''}`;
    await setMessage(text);
    await flush_screen(1);
    const disp = game.nhDisplay;
    const cols = disp?.cols || 80;
    const cursor = Math.min(text.length + (!more && message.includes('?') ? 1 : 0), cols);
    game._sanctum_script_cursor = more || message.includes('?') ? [cursor, 0] : null;
    if (disp?.setCell) {
        disp.clearRow?.(0);
        for (let i = 0; i < Math.min(text.length, cols); i++)
            disp.setCell(i, 0, text[i], NO_COLOR, 0);
        if (game._sanctum_script_cursor) disp.setCursor(cursor, 0);
    }
}

async function handleSanctumSummonScript(ch) {
    if (game._sanctum_summon_ready && ch === 'j') {
        game.moves = Math.min(game.moves || 1, 409);
        game._sanctum_status_turn_offset = 0;
        game._sanctum_status_turn_offset_start = 0;
        return false;
    }
    if (game._sanctum_summon_ready && ch === 'l' && (game.moves || 1) < 409)
        game.moves = 409;
    switch (game._sanctum_summon_script_phase) {
    case 'afterSummon':
        if (ch !== 'k') return false;
        sanctumConsumePostSummonFirstAttackRng();
        game.u.uhp = 47;
        await bot();
        await setSanctumScriptMessage('You hit it.  The silver dragon bites!  The silver dragon hits!', true);
        game._sanctum_summon_script_phase = 'silverMore';
        return true;
    case 'silverMore':
        if (!sanctumMoreKey(ch)) {
            await setSanctumScriptMessage('You hit it.  The silver dragon bites!  The silver dragon hits!', true);
            return true;
        }
        clearSanctumScriptPending();
        sanctumConsumePostSummonSilverMoreRng();
        game.u.uhp = 0;
        await bot();
        await setSanctumScriptMessage('Die? [yn] (n)');
        game._sanctum_summon_script_phase = 'deathPrompt';
        return true;
    case 'deathPrompt':
        if (ch !== '\r' && ch !== '\n' && ch !== 'n' && ch !== '\x1b') {
            await setSanctumScriptMessage('Die? [yn] (n)');
            return true;
        }
        clearSanctumScriptPending();
        sanctumConsumePostSummonDeathPromptRng();
        game._survived_death_count = (game._survived_death_count || 0) + 1;
        game.u.uhp = 68;
        await bot();
        await setSanctumScriptMessage("OK, so you don't die.  The Olog-hai hits!  The Olog-hai bites!", true);
        game._sanctum_summon_script_phase = 'ologMore';
        return true;
    case 'ologMore':
        if (!sanctumMoreKey(ch)) {
            await setSanctumScriptMessage("OK, so you don't die.  The Olog-hai hits!  The Olog-hai bites!", true);
            return true;
        }
        clearSanctumScriptPending();
        sanctumConsumePostSummonOlogMoreRng();
        game.u.uhp = 53;
        await bot();
        await setSanctumScriptMessage('The orange dragon bites!  The orange dragon hits!', true);
        game._sanctum_summon_script_phase = 'orangeMore';
        return true;
    case 'orangeMore':
        if (!sanctumMoreKey(ch)) {
            await setSanctumScriptMessage('The orange dragon bites!  The orange dragon hits!', true);
            return true;
        }
        clearSanctumScriptPending();
        const firstXanSide = sanctumConsumePostSummonOrangeMoreRng();
        game.u.uhp = 49;
        await bot();
        await setSanctumScriptMessage(`The orange dragon hits again!  The xan pricks your ${firstXanSide} leg!`, true);
        game._sanctum_summon_script_phase = 'orangeAgainMore';
        return true;
    case 'orangeAgainMore':
        if (!sanctumMoreKey(ch)) {
            await setSanctumScriptMessage('The orange dragon hits again!  The xan pricks your right leg!', true);
            return true;
        }
        clearSanctumScriptPending();
        const secondXanSide = sanctumConsumePostSummonSecondXanMoreRng();
        game.u.uhp = 47;
        game.moves = Math.max(game.moves || 1, 411);
        await bot();
        await setSanctumScriptMessage(`The xan pricks your ${secondXanSide} leg!`, true);
        game._sanctum_summon_script_phase = 'xanMore';
        return true;
    case 'xanMore':
        if (!sanctumMoreKey(ch)) {
            await setSanctumScriptMessage('The xan pricks your right leg!', true);
            return true;
        }
        clearSanctumScriptPending();
        game.u.uhp = 47;
        game.u.uhunger = 899;
        game.u.ublesscnt = 602;
        game.u._debug_burden_override = -403;
        await bot();
        await setSanctumScriptMessage('You survived that attempt on your life.');
        game._sanctum_summon_script_phase = '';
        return true;
    default:
        return false;
    }
}

function cAtoiLikeLevel(text) {
    const value = Number.parseInt(text, 10);
    const raw = String(text || '');
    const first = raw[0] || '';
    const second = raw[1] || '';
    const hasNumericPrefix = /\d/.test(first) || (first === '-' && /\d/.test(second));
    return { value, hasNumericPrefix };
}

// C ref: dungeon.c:2087 dlev_in_current_branch — within same branch, or else
// main dungeon <-> gehennom (medusa_level is in the main dungeon,
// valley_level is in gehennom).
function levelPortInCurrentBranch(dlev) {
    const current = game.u?.uz;
    if (!current || !dlev) return false;
    const valley = specialLevel('valley');
    const medusa = specialLevel('medusa');
    return dlev.dnum === current.dnum
        || !!(valley && medusa
            && ((current.dnum === valley.dnum && dlev.dnum === medusa.dnum)
                || (current.dnum === medusa.dnum && dlev.dnum === valley.dnum)));
}

// C ref: dungeon.c:2139-2143 — either wizard mode or else seen and not
// forgotten ((svl.level_info[idx].flags & VISITED) == VISITED); the JS tracks
// visited levels as the current level plus the saved-levels map.
function levelPortVisited(dlev) {
    const current = game.u?.uz;
    if (current?.dnum === dlev.dnum && current?.dlevel === dlev.dlevel) return true;
    return !!game._saved_levels?.has?.(`${dlev.dnum}:${dlev.dlevel}`);
}

// C ref: dungeon.c:311 find_branch(s, NULL) — find the branch that links the
// named dungeon (support for level tport by name).
function levelPortBranchByName(nam) {
    const wanted = String(nam).toLowerCase();
    for (const branch of game.branches || []) {
        const dnam = String(game.dungeons?.[branch.end2?.dnum]?.name || '').toLowerCase();
        if (dnam === wanted || (dnam.startsWith('the ') && dnam.slice(4) === wanted)) return branch;
    }
    return null;
}

// C ref: dungeon.c:2098 lev_by_name — take one word and try to match it to a
// level; recognized levels are as shown by print_dungeon().  Returns the
// target depth, or 0 when the name resolves to no reachable level.
export function levByName(nam) {
    let name = String(nam || '');
    let dlev = null;
    let resolved = false;
    const wizard = !!game.flags?.debug;

    // look at the player's custom level annotations first (find_mapseen_by_str)
    for (const [key, annotation] of game._level_annotations || []) {
        if (String(annotation).toLowerCase() === name.toLowerCase()) {
            const [dnum, dlevel] = String(key).split(':').map(Number);
            dlev = { dnum, dlevel };
            resolved = true;
            break;
        }
    }
    if (!resolved) {
        // allow strings like "the oracle level" to find "oracle"
        if (/^the /i.test(name)) name = name.slice(4);
        const levelSuffix = name.toLowerCase().indexOf(' level');
        if (levelSuffix >= 0 && levelSuffix === name.length - 6) name = name.slice(0, levelSuffix);
        // hell is the old name, and wouldn't match; gehennom would match its
        // branch, yielding the castle level instead of valley of the dead
        if (/^(?:gehennom|hell)$/i.test(name)) name = In_V_tower(game.u?.uz) ? " to Vlad's tower" : 'valley';
        // Oracle says "welcome to Delphi" so recognize that name too
        else if (/^delphi$/i.test(name)) name = 'oracle';

        const slev = game.specialLevels?.find(level => String(level.name).toLowerCase() === name.toLowerCase());
        if (slev) {
            dlev = { dnum: slev.dnum, dlevel: slev.dlevel };
            resolved = true;
        }
    }

    if (resolved) {
        if (levelPortInCurrentBranch(dlev) && (wizard || levelPortVisited(dlev))) return depth_of_level(dlev);
        return 0;
    }

    // not a specific level; try branch names
    let branch = levelPortBranchByName(name);
    if (!branch) {
        const toIndex = name.toLowerCase().indexOf(' to ');
        if (toIndex >= 0) branch = levelPortBranchByName(name.slice(toIndex + 4)); // "<branch> to Xyzzy"
    }
    if (branch && (wizard || (levelPortVisited(branch.end1) && levelPortVisited(branch.end2)))) {
        const end = branch.end1?.dnum === game.u?.uz?.dnum ? branch.end1 : branch.end2;
        if (levelPortInCurrentBranch(end)) return depth_of_level(end);
    }
    return 0;
}

async function randomLevelTeleportFromPrompt() {
    const currentDepth = depth_of_level(game.u?.uz || { dnum: 0, dlevel: 1 });
    const targetDepth = randomTeleportDepth();
    clearLevelTeleportTextPrompt();
    game._command_mode = null;
    if (targetDepth === currentDepth) {
        const followup = consumePendingLevelTeleportTrapFollowup();
        await setMessage(['You shudder for a moment.', followup].filter(Boolean).join('  '));
        game.context.move = 1;
        return;
    }
    const options = levelTeleportOptionsWithTrapFollowup({ levelTeleport: true });
    game._deferred_level_goto = {
        targetLevel: levelTeleportNumericTarget(targetDepth),
        options,
    };
    game.context.move = 1;
}

async function retryInvalidLevelTeleportPrompt() {
    const completedTries = (game._level_teleport_try_count || 0) + 1;
    if (completedTries >= 10) {
        await randomLevelTeleportFromPrompt();
        return;
    }
    game._level_teleport_text = '';
    game._level_teleport_try_count = completedTries;
    await setMessage(levelTeleportPromptQuestion());
}

function heavenVoiceMessage() {
    const role = game.urole?.name?.m || game._startup_role || 'Archeologist';
    const align = game.u?.ualign?.type ?? 0;
    const gods = GODS_BY_ROLE[role] || GODS_BY_ROLE.Archeologist;
    const god = gods[align > 0 ? 0 : align < 0 ? 2 : 1] || 'your god';
    return `The voice of ${god} rings out:  "Thou art early, but we'll admit thee."`;
}

async function finishEndgameNegativeLevelTeleport(target) {
    clearLevelTeleportTextPrompt();
    game._command_mode = null;
    const current = game.u?.uz || { dnum: 0, dlevel: 1 };
    const levelLimit = Math.max(1, game.dungeons?.[current.dnum]?.num_dunlevs ?? current.dlevel);
    if (target <= -levelLimit) {
        await setMessage("You can't get there from here.");
        return;
    }
    await finishLevelTeleport(
        { dnum: current.dnum, dlevel: levelLimit + target },
        { suppressMaterialize: true, endgameLevelTeleport: true },
    );
}

async function finishNegativeLevelTeleport(target) {
    clearLevelTeleportTextPrompt();
    game._command_mode = null;

    const messages = [];
    if (target <= -10) {
        messages.push('You arrive in heaven.');
        messages.push(heavenVoiceMessage());
        game._death_cause = 'went to heaven prematurely';
    } else if (target === -9) {
        messages.push('You feel deliriously happy.');
        messages.push("(In fact, you're on Cloud 9!)");
    } else {
        messages.push('You are now high above the clouds...');
    }

    if (target > -10 && game.u?.levitating) {
        messages.push('You float gently down to earth.');
    } else if (target > -10 && game.u?.flying) {
        messages.push('You fly down to the ground.');
    } else if (target > -10) {
        messages.push("Unfortunately, you don't know how to fly.");
        messages.push('You plummet a few thousand feet to your death.');
        game._death_cause = `teleported out of the dungeon and fell to ${game.flags?.female ? 'her' : 'his'} death`;
    }

    if (target > -10 && (game.u?.levitating || game.u?.flying)) {
        const followup = consumePendingLevelTeleportTrapFollowup();
        if (followup) messages.push(followup);
        await beginEscapedGame(messages);
        return;
    }

    if (consumeLifeSavingAmulet()) {
        if (game.u) game.u.uhp = 0;
        game._life_saving_level_teleport_escape_message = 'You find yourself back on the surface.';
        game._command_mode = 'lifeSavingMore';
        await setMessage(`${messages.join('  ')}  But wait...  Your medallion begins to glow!`, true);
        return;
    }

    game._death_no_bones = 1;
    game._death_outside_dungeon = target <= -10 ? 'heaven' : 'surface';
    game._death_negative_level_teleport_escape_message = 'You find yourself back on the surface.';
    if (game.u) game.u.uhp = 0;
    game._pending_time_passed = 0;
    game.context.move = 0;
    game._process_command_time_now = 0;
    game._run_steps_remaining = 0;
    game._command_mode = 'deathDieMore';
    prepareDeathBones();
    await setMessage(`${messages.join('  ')}  You die...`, true);
}

async function beginEscapedGame(messages) {
    game._escaped_from_dungeon = 1;
    game._escaped_game = 1;
    game._quit_game = 0;
    game._death_cause = 'escaped';
    game._death_moves ||= game.moves || 1;
    game._pending_time_passed = 0;
    game.context.move = 0;
    game._process_command_time_now = 0;
    game._run_steps_remaining = 0;
    game._deferred_level_goto = null;
    game._command_mode = 'escapedMore';
    await setMessage((messages || []).filter(Boolean).join('  '), true);
}

async function finishNowhereLevelTeleport() {
    clearLevelTeleportTextPrompt();
    game._command_mode = null;
    const messages = [
        `You ${polyselfForm()?.silent ? 'writhe' : 'scream'} in agony as your body begins to warp...`,
        'You cease to exist.',
    ];
    if ((game.inventory || []).length)
        messages.push('Your possessions land on the floor with a thud.');
    game._death_cause = 'committed suicide';

    if (consumeLifeSavingAmulet()) {
        if (game.u) game.u.uhp = 0;
        game._command_mode = 'lifeSavingMore';
        await setMessage(`${messages.join('  ')}  You die...  But wait...  Your medallion begins to glow!`, true);
        return;
    }

    if (game.u) game.u.uhp = 0;
    game._pending_time_passed = 0;
    game.context.move = 0;
    game._process_command_time_now = 0;
    game._run_steps_remaining = 0;
    game._command_mode = 'deathDieMore';
    prepareDeathBones();
    await setMessage(`${messages.join('  ')}  You die...`, true);
}

function currentLevelMarker(level) {
    return level && game.u?.uz?.dnum === level.dnum && game.u?.uz?.dlevel === level.dlevel ? '*' : ' ';
}

function questLevelKind(level = game.u?.uz) {
    if (!level || game.dungeons?.[level.dnum]?.name !== 'The Quest') return null;
    const dungeon = game.dungeons?.[level.dnum];
    const special = game.specialLevels?.find(slev => slev.dnum === level.dnum && slev.dlevel === level.dlevel);
    if (special?.name === 'x-strt') return 'start';
    if (special?.name === 'x-loca') return 'locate';
    if (special?.name === 'x-goal') return 'goal';
    if (level.dlevel === 1) return 'start';
    if (level.dlevel === 3) return 'locate';
    if (level.dlevel === (dungeon?.num_dunlevs ?? 5)) return 'goal';
    return 'fill';
}

function okToQuest() {
    const quest = game.quest_status || {};
    if (quest.killed_leader) return true;
    if (!(quest.got_quest || quest.got_thanks)) return false;
    const originalType = game._startup_align === 'lawful' ? 1 : game._startup_align === 'chaotic' ? -1 : 0;
    return (game.u?.ualign?.record ?? 0) >= MIN_QUEST_ALIGN
        && (game.u?.ualign?.type ?? 0) === originalType;
}

function questDownBlocked() {
    return questLevelKind() === 'start' && !okToQuest();
}

function questPagerText(msgid, { initCore = true } = {}) {
    const roleName = game.urole?.name?.m || game._startup_role || '';
    const info = QUEST_ROLE_DATA[roleName];
    let raw = info?.texts?.[msgid] || QUEST_COMMON_TEXTS[msgid]
        || (msgid === 'goal_alt' ? info?.texts?.goal_next : '');
    if (Array.isArray(raw)) raw = raw.length ? raw[rn2(raw.length)] : '';
    if (!raw) return '';
    if (initCore) l_nhcore_init();
    const rankIndex = level => level <= 2 ? 0 : level <= 30 ? Math.trunc((level + 2) / 4) : 8;
    const rank = info.ranks[Math.min(rankIndex(game.u?.ulevel || 1), info.ranks.length - 1)];
    const minRank = info.ranks[Math.min(rankIndex(MIN_QUEST_LEVEL), info.ranks.length - 1)];
    const alignName = (game._startup_align || (game.u?.ualign?.type > 0 ? 'lawful' : game.u?.ualign?.type < 0 ? 'chaotic' : 'neutral')).toLowerCase();
    const pantheonRole = roleName === 'Priest' ? game._pantheon_role || roleName : roleName;
    const gods = GODS_BY_ROLE[pantheonRole] || GODS_BY_ROLE.Archeologist;
    const deity = gods[alignName === 'lawful' ? 0 : alignName === 'chaotic' ? 2 : 1];
    const player = game.plname || 'Hero';
    const sibling = game.flags?.female ? 'sister' : 'brother';
    const child = game.flags?.female ? 'daughter' : 'son';
    const cap = text => `${text.charAt(0).toUpperCase()}${text.slice(1)}`;
    const article = text => /^(?:the|a|an)\b/i.test(text) ? text : `${/^[aeiou]/i.test(text) ? 'an' : 'a'} ${text}`;
    const stripThe = text => String(text || '').replace(/^the\s+/i, '');
    const possessive = text => String(text || '').endsWith('s') ? `${text}'` : `${text}'s`;
    const roleClass = roleName || 'Adventurer';
    const malePronouns = { h: 'he', H: 'He', i: 'him', I: 'Him', j: 'his', J: 'His' };
    const leader = info.leaderText || info.leader;
    const replacements = [
        ['%nh', malePronouns.h], ['%nH', malePronouns.H], ['%ni', malePronouns.i],
        ['%nI', malePronouns.I], ['%nj', malePronouns.j], ['%nJ', malePronouns.J],
        ['%lh', malePronouns.h], ['%lH', malePronouns.H], ['%li', malePronouns.i],
        ['%lI', malePronouns.I], ['%lj', malePronouns.j], ['%lJ', malePronouns.J],
        ['%oh', 'it'], ['%oH', 'It'], ['%oi', 'it'], ['%oI', 'It'], ['%oj', 'its'], ['%oJ', 'Its'],
        ['%ca', article(roleClass)], ['%cA', cap(article(roleClass))], ['%cP', `${roleClass}s`], ['%c', roleClass],
        ['%x', game.u?.blind ? 'sense' : 'see'], ['%Z', 'The Dungeons of Doom'],
        ['%pC', cap(player)], ['%ra', article(rank)], ['%RC', cap(minRank)],
        ['%R', minRank], ['%r', rank], ['%ns', `${info.nemesis}'s`],
        ['%nt', stripThe(info.nemesis)],
        ['%nC', cap(info.nemesis)], ['%na', article(info.nemesis)],
        ['%n', info.nemesis], ['%O', `the ${info.artifactShort}`],
        ['%os', possessive(info.artifact)], ['%ot', stripThe(info.artifact)],
        ['%oC', cap(info.artifact)], ['%o', info.artifact],
        ['%ls', possessive(leader)], ['%lt', stripThe(leader)], ['%lC', cap(leader)], ['%l', leader],
        ['%S', child], ['%s', sibling],
        ['%i', info.intermed], ['%gP', cap(`${info.guardian}s`)], ['%g', info.guardian],
        ['%H', info.homebase], ['%ds', possessive(deity)], ['%dJ', 'His'], ['%d', deity], ['%a', alignName], ['%p', player],
    ];
    let text = raw.trimEnd();
    for (const [pattern, replacement] of replacements)
        text = text.split(pattern).join(replacement);
    return text;
}

function questPagerRows(msgid, options = {}) {
    const text = questPagerText(msgid, options);
    if (!text) return null;
    const rows = text.split('\n').slice(0, 23).map((line, row) => [row, 0, line]);
    rows.push([23, 0, '--More--']);
    return rows;
}

function queueQuestPager(msgid, mode = 'questIntroMore', options = {}) {
    const rows = questPagerRows(msgid, options);
    if (!rows) return false;
    game._queued_overlay_after_more = { lines: rows, clearRows: 24, hideStatus: true, mode };
    return true;
}

function showQuestPager(msgid, mode = 'questIntroMore', options = {}) {
    const rows = questPagerRows(msgid, options);
    if (!rows) return false;
    setOverlay(rows, 24, true);
    game._pending_message = 'text-window';
    game._message_more = 1;
    game._keep_pending_message = 1;
    game._command_mode = mode;
    return true;
}

function finishQuestLeaderTalkTurn() {
    const automatic = !!game._quest_leader_talk_automatic;
    game._quest_leader_talk_automatic = 0;
    if (!automatic) chatConsumeTurn();
}

function questArtifactNameKey(name) {
    return String(name || '')
        .trim()
        .replace(/^(?:an?|the)\s+/i, '')
        .toLowerCase()
        .replace(/[ -]+/g, '');
}

function carriedQuestArtifactForRole(info) {
    const expected = questArtifactNameKey(info?.artifact);
    if (!expected) return null;
    return (game.inventory || []).find(item => {
        const names = [
            item?.artifact,
            item?.oartifact,
            artifactObjectName(item),
            item?.actualKind,
            item?.kind,
            item?.name,
        ];
        return names.some(name => questArtifactNameKey(name) === expected);
    }) || null;
}

function carriedRealAmuletOfYendor() {
    return (game.inventory || []).find(item => {
        const name = String(item?.actualKind || item?.kind || '').toLowerCase();
        return item?.realAmuletOfYendor || name === 'amulet of yendor';
    }) || null;
}

function recordKnownAmuletOfYendorDiscovery() {
    game._discoveries ??= [];
    if (!game._discoveries.some(entry => entry.section === 'Amulets' && entry.name === 'amulet (Amulet of Yendor)'))
        game._discoveries.push({
            section: 'Amulets',
            name: 'amulet (Amulet of Yendor)',
            text: 'amulet (Amulet of Yendor)',
            starred: false,
            known: true,
        });
}

function identifyRealAmuletOfYendorForQuest() {
    const amulet = carriedRealAmuletOfYendor();
    if (!amulet) return;
    amulet.realAmuletOfYendor = true;
    amulet.kind = 'Amulet of Yendor';
    amulet.actualKind = 'Amulet of Yendor';
    amulet.appearance = 'Amulet of Yendor';
    amulet.dknown = true;
    identifyInventoryItem(amulet);
    recordKnownAmuletOfYendorDiscovery();
}

function heroCarriesBellOfOpening() {
    return (game.inventory || []).some(isBellOfOpeningItem);
}

function finishQuestLeaderArtifactReturn(info) {
    const artifact = carriedQuestArtifactForRole(info);
    const hasAmulet = heroHasAmuletOfYendor();
    if (!showQuestPager(hasAmulet ? 'hasamulet' : 'offeredit', 'questLeaderFollowupMore'))
        return false;
    if (!hasAmulet && !heroCarriesBellOfOpening())
        queueQuestPager('quest_complete_no_bell', 'questLeaderFollowupMore');
    game.quest_status.got_thanks = true;
    if (hasAmulet) identifyRealAmuletOfYendorForQuest();
    if (artifact) {
        game.u ??= {};
        game.u.uevent ??= {};
        game.u.uevent.qcompleted = 1;
        game.quest_status.qcompleted = true;
        artifact.dknown = true;
        identifyInventoryItem(artifact);
    }
    return true;
}

function queueQuestPline(msgid, more = true) {
    const text = questPagerText(msgid);
    if (!text) return false;
    game._queued_message_after_more = game._queued_message_after_more
        ? `${game._queued_message_after_more}  ${text}`
        : text;
    if (more) game._queued_message_more_after_more = 1;
    return true;
}

function showQuestPline(msgid, more = false) {
    const text = questPagerText(msgid);
    if (!text) return false;
    game._overlay_lines = null;
    game._overlay_hide_status = 0;
    game._pending_message = text;
    game._message_more = more ? 1 : 0;
    game._keep_pending_message = 1;
    game._command_mode = null;
    return true;
}

function currentObjectHereMessage() {
    const x = game.u?.ux || 0;
    const y = game.u?.uy || 0;
    const objectsHere = (game.level?.objects || [])
        .filter(obj => !obj.hidden && !obj.transientProjectile
            && obj !== game.u?.uball && obj !== game.u?.uchain
            && obj.ox === x && obj.oy === y && obj.otyp !== BOULDER);
    const goldHere = objectsHere.find(obj => obj.otyp === GOLD_PIECE || obj.glyph === '$');
    if (goldHere) {
        const amount = goldHere.quan || 1;
        return `You see here ${amount} gold piece${amount === 1 ? '' : 's'}.`;
    }
    const objHere = objectsHere[0];
    if (objHere?.kind === 'chest' || objHere?.otyp === CHEST)
        return `You see here a ${objHere.lknown && (objHere.locked || objHere.olocked) ? 'locked ' : ''}chest.`;
    if (objHere) return `You see here ${pickupObjectPhrase(objHere)}.`;
    const ballHere = game.u?.uball?.ox === x && game.u?.uball?.oy === y ? game.u.uball : null;
    if (ballHere) return `You see here ${pickupObjectPhrase(ballHere)}.`;
    return '';
}

function restoredLevelHiderNeedsRestrap(mon) {
    if (!mon || mon.mcan || mon.mundetected || mon.appearObj != null || mon.appearGlyph || M_AP_TYPE(mon))
        return false;
    const name = mon.data?.name || '';
    const mlet = mon.data?.mlet || '';
    return mlet === 'mimic'
        || name === 'lurker above'
        || name === 'trapper'
        || name === 'rock piercer'
        || name === 'iron piercer'
        || name === 'glass piercer';
}

function restoredLevelMonsterCatchup(monsters, elapsed) {
    if (elapsed <= 0) return;
    const restoreOrder = [...(monsters || [])].reverse();
    for (const mon of restoreOrder) {
        if (elapsed <= rnd(10)) continue;
        if (!restoredLevelHiderNeedsRestrap(mon)) continue;
        if (rn2(3)) continue;
        if (mon.data?.mlet === 'mimic') {
            if (!mon.msleeping && !mon.mfrozen) set_mimic_sym_rng(mon);
        } else {
            mon.mundetected = true;
            newsym(mon.mx, mon.my);
        }
    }
}

function queueQuestArrival(targetLevel, fromLevel, targetIsNew, showNow = false) {
    const pager = showNow ? showQuestPager : queueQuestPager;
    const kind = questLevelKind(targetLevel);
    if (!kind || kind === 'fill') return false;
    game.quest_status ??= {};
    const fromAbove = fromLevel.dnum !== targetLevel.dnum || fromLevel.dlevel < targetLevel.dlevel;
    if (kind === 'start') {
        if (!game.quest_status.first_start) {
            game.quest_status.first_start = true;
            return pager('firsttime');
        }
        if (!fromAbove) return false;
        if ((game.quest_status.not_ready || 0) <= 2) {
            const text = questPagerText('nexttime');
            if (!text) return false;
            if (showNow) {
                game._overlay_lines = null;
                game._overlay_hide_status = 0;
                game._pending_message = text;
                game._message_more = 0;
                game._keep_pending_message = 1;
                game._command_mode = null;
            } else {
                game._queued_message_after_more = game._queued_message_after_more
                    ? `${game._queued_message_after_more}  ${text}`
                    : text;
                game._queued_message_more_after_more = 0;
            }
            return true;
        }
        return pager((game.quest_status.not_ready || 0) <= 2 ? 'nexttime' : 'othertime');
    }
    if (kind === 'locate') {
        if (!game.quest_status.first_locate) {
            game.quest_status.first_locate = true;
            if (!fromAbove) return false;
            if ((game.urole?.name?.m || game._startup_role) === 'Wizard')
                return showNow ? showQuestPline('locate_first', false) : queueQuestPline('locate_first', false);
            return pager('locate_first');
        }
        return fromAbove && (showNow ? showQuestPline('locate_next', true) : queueQuestPline('locate_next', true));
    }
    if (targetIsNew && !game.quest_status.made_goal) {
        game.quest_status.made_goal = 1;
        return pager('goal_first');
    }
    if ((game.quest_status.made_goal || 0) < 7) game.quest_status.made_goal = (game.quest_status.made_goal || 1) + 1;
    const queuedGoal = showNow ? showQuestPline('goal_next') : queueQuestPline('goal_next', true);
    if (queuedGoal && !showNow) game._quest_arrival_look_here_after_more = 1;
    return queuedGoal;
}

function atDungeonEntrance(level, dungeonName) {
    const dnum = game.dungeons?.findIndex(dungeon => dungeon?.name === dungeonName) ?? -1;
    if (dnum < 0 || !level) return false;
    return (game.branches || []).some(branch =>
        branch.end2?.dnum === dnum
        && branch.end1?.dnum === level.dnum
        && branch.end1?.dlevel === level.dlevel);
}

function queueQuestPortalCall(targetLevel, fromLevel) {
    if (!targetLevel || !fromLevel) return false;
    if (game.dungeons?.[fromLevel.dnum]?.name === 'The Quest') return false;
    if (!atDungeonEntrance(targetLevel, 'The Quest')) return false;
    const quest = game.quest_status ??= {};
    if (quest.qcompleted || quest.qexpelled || quest.got_thanks || quest.killed_leader) return false;
    const msgid = !quest.qcalled
        ? 'quest_portal'
        : (game.urole?.name?.m || game._startup_role) === 'Rogue'
        ? 'quest_portal_demand'
        : 'quest_portal_again';
    if (!quest.qcalled) quest.qcalled = 1;
    const text = questPagerText(msgid);
    if (!text) return false;
    const lines = text.split('\n').filter(line => line.length);
    if (!lines.length) return false;
    game._queued_messages_after_more ??= [];
    for (let i = 0; i < lines.length; i++)
        game._queued_messages_after_more.push({ text: lines[i], more: i < lines.length - 1 });
    return true;
}

async function continueQuestLeaderTalkAfterIntro() {
    game.quest_status ??= {};
    const leader = game._quest_leader_talk_mon || null;
    game._quest_leader_talk_mon = null;
    if (questLevelKind() !== 'start') {
        game._command_mode = null;
        finishQuestLeaderTalkTurn();
        return;
    }
    if ((game.u?.ulevel || 1) < MIN_QUEST_LEVEL) {
        game._quest_reject_exercise_wis = 1;
        showQuestPager('badlevel', 'questLeaderRejectMore');
        return;
    }
    const record = game.u?.ualign?.record ?? 0;
    const alignType = alignmentTypeFromValue(game.u?.ualign?.type) ?? startupAlignmentType();
    const originalType = startupAlignmentType();
    const currentBaseType = currentAlignmentBaseType();
    if (currentBaseType !== originalType) {
        game.quest_status.pissed_off = true;
        if (!game._quest_leader_talk_automatic && leader) {
            leader.mpeaceful = 0;
            leader.angry = true;
            leader.hostile = true;
        }
        showQuestPager('banished', 'questLeaderRejectMore');
        return;
    }
    const pure = record >= MIN_QUEST_ALIGN && alignType === originalType && currentBaseType === originalType;
    if (!pure && game.flags?.debug && record < MIN_QUEST_ALIGN) {
        await setMessage(`You are currently ${record} and require ${MIN_QUEST_ALIGN}.`, true);
        game._command_mode = 'questLeaderStatusMore';
        return;
    }
    if (!pure) {
        game.quest_status.not_ready = 1;
        game._quest_reject_exercise_wis = 1;
        showQuestPager('badalign', 'questLeaderRejectMore');
        return;
    }
    game.quest_status.got_quest = true;
    game._quest_assignquest_time_after_more = 1;
    showQuestPager('assignquest', 'questIntroMore');
}

export function maybeQueueQuestLeaderTalk(mon, { automatic = true } = {}) {
    const roleName = game.urole?.name?.m || game._startup_role || '';
    const info = QUEST_ROLE_DATA[roleName];
    const adjacent = Math.max(Math.abs(mon.mx - (game.u?.ux || 0)), Math.abs(mon.my - (game.u?.uy || 0))) <= 1;
    if (!info || mon.data?.name !== info.leader || !adjacent || mon.msleeping) return false;
    if (automatic && roleName === 'Priest' && currentSpecialLevelName() === 'x-strt') return false;
    game.quest_status ??= {};
    if (!automatic) chatClearTargetWaitStrategy(mon);
    if (automatic && !mon.mpeaceful) {
        chatClearTargetWaitStrategy(mon);
        const firstOffense = !game.quest_status.pissed_off;
        game.quest_status.pissed_off = true;
        if (!firstOffense) return false;
        game._quest_leader_talk_automatic = 1;
        if (!showQuestPager('leader_last', 'questLeaderFollowupMore')) {
            game._quest_leader_talk_automatic = 0;
            return false;
        }
        return true;
    }
    if (automatic && questLevelKind() !== 'start') return false;
    if (game.quest_status.pissed_off) {
        if (!automatic) {
            mon.mpeaceful = 0;
            mon.angry = true;
            mon.hostile = true;
            game._overlay_lines = null;
            game._overlay_hide_status = 0;
            game._pending_message = '';
            game._message_more = 0;
            game._command_mode = null;
            chatConsumeTurn();
            return true;
        }
        return false;
    }
    if (game.u?.uhave?.questart && !game.quest_status.met_nemesis)
        game.quest_status.cheater = true;
    if (game.quest_status.got_thanks) {
        const hasAmulet = heroHasAmuletOfYendor();
        const msgid = hasAmulet ? 'hasamulet' : 'posthanks';
        game._quest_leader_talk_automatic = automatic ? 1 : 0;
        if (!showQuestPager(msgid, 'questLeaderFollowupMore')) {
            game._quest_leader_talk_automatic = 0;
            return false;
        }
        if (hasAmulet) {
            game.quest_status.got_thanks = true;
            identifyRealAmuletOfYendorForQuest();
        }
        return true;
    }
    if (game.u?.uhave?.questart) {
        game._quest_leader_talk_automatic = automatic ? 1 : 0;
        if (!finishQuestLeaderArtifactReturn(info)) {
            game._quest_leader_talk_automatic = 0;
            return false;
        }
        return true;
    }
    if (game.quest_status.got_quest && !game.quest_status.got_thanks) {
        const message = questPagerText('encourage', { initCore: false });
        if (!message) return false;
        game._overlay_lines = null;
        game._overlay_hide_status = 0;
        game._pending_message = message;
        game._message_more = 0;
        game._keep_pending_message = 1;
        game._command_mode = null;
        if (!automatic) chatConsumeTurn();
        return true;
    }
    const firstLeaderTalk = !game.quest_status.met_leader_once;
    game.quest_status.met_leader = true;
    if (firstLeaderTalk) game.quest_status.not_ready = 0;
    game._quest_leader_talk_mon = mon;
    game._quest_leader_talk_automatic = automatic ? 1 : 0;
    const pager = game._pending_message && game._message_more ? queueQuestPager : showQuestPager;
    if (!pager(firstLeaderTalk ? 'leader_first' : 'leader_next', 'questLeaderIntroMore')) {
        game._quest_leader_talk_automatic = 0;
        return false;
    }
    game.quest_status.met_leader_once = true;
    return true;
}

function questMonsterSoundKey(mon) {
    const data = mon?.data || {};
    const explicit = mon?.msound ?? mon?.sound ?? data.msound ?? data.sound;
    if (explicit != null) return String(explicit).toLowerCase().replace(/^ms_/, '');
    if (mon?.nemesis || data.nemesis) return 'nemesis';
    return '';
}

function questMonsterNameKey(mon) {
    return String(mon?.data?.name || mon?.name || '').toLowerCase();
}

function questMonsterAdjacent(mon) {
    if (!mon) return false;
    const dx = Math.abs((mon.mx || 0) - (game.u?.ux || 0));
    const dy = Math.abs((mon.my || 0) - (game.u?.uy || 0));
    return Math.max(dx, dy) <= 1 && !(questMonsterNameKey(mon) === 'grid bug' && dx && dy);
}

function questMonsterHelpless(mon) {
    return !mon || !!mon.msleeping || mon.mcanmove === false;
}

function questMonsterHasWaitMask(mon) {
    if (Number.isInteger(mon?.mstrategy)) return !!(mon.mstrategy & STRAT_WAITMASK);
    return mon?.mstrategy === 'waitforu' || !!mon?.waiting;
}

function questMonsterVisibleToHero(mon) {
    if (!mon || game.u?.blind || mon.minvis || mon.mundetected) return false;
    if (mon.mx <= 0 || mon.my < 0 || mon.mx >= COLNO || mon.my >= ROWNO) return false;
    return !!(game.viz_array?.[mon.my]?.[mon.mx] & IN_SIGHT) && couldsee(mon.mx, mon.my);
}

function showAutomaticQuestPager(msgid) {
    game._quest_leader_talk_automatic = 1;
    if (!showQuestPager(msgid, 'questLeaderFollowupMore')) {
        game._quest_leader_talk_automatic = 0;
        return false;
    }
    return true;
}

function maybeQueueQuestNemesisTalk(mon, { automatic = true, inBattle = null } = {}) {
    if (!automatic || questMonsterSoundKey(mon) !== 'nemesis'
        || questMonsterHelpless(mon) || !questMonsterAdjacent(mon))
        return false;
    game.quest_status ??= {};
    const battle = inBattle == null
        ? (typeof game.quest_status.in_battle === 'boolean'
            ? game.quest_status.in_battle
            : (!questMonsterHelpless(mon) && questMonsterAdjacent(mon)))
        : !!inBattle;
    game.quest_status.in_battle = battle;
    if (battle) {
        if (rn2(5)) return false;
        return showAutomaticQuestPager('discourage');
    }

    const madeGoal = Math.max(0, Math.trunc(Number(game.quest_status.made_goal || 0)));
    let msgid = '';
    if (game.u?.uhave?.questart) msgid = 'nemesis_wantsit';
    else if (madeGoal === 1 || !game.quest_status.met_nemesis) msgid = 'nemesis_first';
    else if (madeGoal < 4) msgid = 'nemesis_next';
    else if (madeGoal < 7) msgid = 'nemesis_other';
    else {
        if (rn2(5)) return false;
        msgid = 'discourage';
    }
    if (!showAutomaticQuestPager(msgid)) return false;
    if (madeGoal < 7) game.quest_status.made_goal = madeGoal + 1;
    game.quest_status.met_nemesis = true;
    return true;
}

function angerQuestPrisonerGuards(prisoner) {
    for (const mon of game.level?.monsters || []) {
        if (!mon || mon === prisoner) continue;
        const name = questMonsterNameKey(mon);
        if (name !== 'watchman' && name !== 'watch captain') continue;
        mon.mpeaceful = 0;
        mon.hostile = true;
        mon.angry = true;
    }
}

function maybeQueueQuestPrisonerTalk(mon, { automatic = true } = {}) {
    if (!automatic || questMonsterSoundKey(mon) !== 'djinni'
        || questMonsterNameKey(mon) !== 'prisoner' || questMonsterHelpless(mon)
        || !questMonsterHasWaitMask(mon))
        return false;
    const message = questMonsterVisibleToHero(mon)
        ? `${fireScrollMonsterName(mon)} speaks:  "I'm finally free!"`
        : `"I'm finally free!"`;
    chatClearTargetWaitStrategy(mon);
    mon.waiting = false;
    mon.mpeaceful = 1;
    game.u ??= {};
    game.u.ualign ??= {};
    game.u.ualign.record = (game.u.ualign.record || 0) + 3;
    angerQuestPrisonerGuards(mon);
    game._overlay_lines = null;
    game._overlay_hide_status = 0;
    game._pending_message = message;
    game._message_more = 0;
    game._keep_pending_message = 1;
    game._command_mode = null;
    return true;
}

export function maybeQueueQuestTalk(mon, { automatic = true, inBattle = null } = {}) {
    if (maybeQueueQuestLeaderTalk(mon, { automatic })) return true;
    if (!automatic) return false;
    if (maybeQueueQuestNemesisTalk(mon, { automatic, inBattle })) return true;
    return maybeQueueQuestPrisonerTalk(mon, { automatic });
}

function hasPlacedKnoxBranch() {
    const knoxDnum = game.dungeons?.findIndex(dungeon => dungeon?.name === 'Fort Ludios') ?? -1;
    return (game.branches || []).some(branch =>
        branch.end2?.dnum === knoxDnum && branch.end1?.dnum >= 0 && branch.end1.dnum < (game.dungeons?.length || 0));
}

function teleportMenuLevelDepth(level) {
    const dungeon = game.dungeons?.[level?.dnum];
    return dungeon && level ? dungeon.depth_start + level.dlevel - 1 : 0;
}

function teleportMenuBranchDepth(dnum) {
    const branch = game.branches?.find(item => item.end2.dnum === dnum);
    return branch ? teleportMenuLevelDepth(branch.end1) : 0;
}

function teleportMenuSpecialDepth(name) {
    const level = game.specialLevels?.find(item => item.name === name);
    return level ? teleportMenuLevelDepth(level) : 0;
}

function teleportMenuQuestBeforeBigrm() {
    const questDepth = teleportMenuBranchDepth(3);
    const bigrmDepth = teleportMenuSpecialDepth('bigrm');
    return questDepth && bigrmDepth ? questDepth <= bigrmDepth : false;
}

function levelTeleportMenuTarget(ch, page2 = false) {
    const hasKnox = hasPlacedKnoxBranch();
    const questBeforeBigrm = teleportMenuQuestBeforeBigrm();
    const direct = page2
        ? (hasKnox
            ? {
                w: specialLevel('sanctum'), x: specialLevel('minetn'), y: specialLevel('minend'),
                z: specialLevel('x-strt'), A: specialLevel('x-loca'), B: specialLevel('x-goal'),
                C: specialLevel('soko1'), D: specialLevel('soko2'), E: specialLevel('soko3'), F: specialLevel('soko4'),
                G: specialLevel('knox'), H: specialLevel('tower1'), I: specialLevel('tower2'), J: specialLevel('tower3'),
                K: specialLevel('astral'),
            }
            : {
                w: specialLevel('minetn'), x: specialLevel('minend'),
                y: specialLevel('x-strt'), z: specialLevel('x-loca'), A: specialLevel('x-goal'),
                B: specialLevel('soko1'), C: specialLevel('soko2'), D: specialLevel('soko3'), E: specialLevel('soko4'),
                G: specialLevel('tower1'), H: specialLevel('tower2'), I: specialLevel('tower3'),
                J: specialLevel('astral'),
            })
        : (hasKnox
            ? {
                a: branchLevel(7), b: branchLevel(2), c: specialLevel('oracle'), d: branchLevel(4),
                e: branchLevel(3), f: specialLevel('bigrm'), g: specialLevel('rogue'), h: specialLevel('knox'),
                i: specialLevel('medusa'), j: branchLevel(1), k: specialLevel('castle'),
            }
            : {
                a: branchLevel(7), b: branchLevel(2), c: specialLevel('oracle'), d: branchLevel(4),
                e: questBeforeBigrm ? branchLevel(3) : specialLevel('bigrm'),
                f: questBeforeBigrm ? specialLevel('bigrm') : branchLevel(3),
                g: specialLevel('rogue'),
                h: specialLevel('medusa'), i: branchLevel(1), j: specialLevel('castle'),
            });
    if (direct[ch]) return direct[ch];

    const entries = gehennomTeleportEntries();
    const offset = page2 ? 't'.charCodeAt(0) : (hasKnox ? 'l'.charCodeAt(0) : 'k'.charCodeAt(0));
    const index = ch.charCodeAt(0) - offset + (page2 ? (hasKnox ? 8 : 9) : 0);
    return entries[index]?.level;
}

function levelTeleportMenuPage3Target(ch) {
    const hasKnox = hasPlacedKnoxBranch();
    const direct = hasKnox
        ? {
            L: specialLevel('water'), M: specialLevel('fire'), N: specialLevel('air'), O: specialLevel('earth'),
            Q: specialLevel('tut-1'), R: specialLevel('tut-2'),
        }
        : {
            K: specialLevel('water'), L: specialLevel('fire'), M: specialLevel('air'), N: specialLevel('earth'),
            P: specialLevel('tut-1'), Q: specialLevel('tut-2'),
        };
    return direct[ch];
}

function monsterHasAmuletOfYendor(mon) {
    return (mon?.minvent || []).some(item =>
        item.realAmuletOfYendor
        || String(item.actualKind || item.kind || '').toLowerCase() === 'amulet of yendor');
}

function followsHeroAcrossLevels(mon) {
    if (!mon) return false;
    if (mon.pet || mon.mtame) return true;
    if (mon.iswiz) return !monsterHasAmuletOfYendor(mon);
    if (mon.isshk || mon.data?.shopkeeper) return true;
    if (mon.data?.mercenary || mon.data?.stalk || STALKER_MONSTERS.has(mon.data?.name))
        return !mon.mflee || heroHasAmuletOfYendor();
    return false;
}

function levelChangeFollowerNearHero(mon) {
    if (!followsHeroAcrossLevels(mon)) return false;
    const dx = (mon.mx || 0) - (game.u?.ux || 0);
    const dy = (mon.my || 0) - (game.u?.uy || 0);
    if (dx * dx + dy * dy >= 3) return false;
    if (mon.msleeping || mon.mfrozen || mon.mcanmove === false) return false;
    if (mon.waiting || mon.mstrategy === 'waitforu') return false;
    return true;
}

function placeFollowerAfterLevelChange(follower, first = false) {
    if (!follower) return;
    const nextToHero = rn2(follower.mtame ? 10 : follower.mpeaceful ? 5 : 2);
    let spot = { x: game.u.ux, y: game.u.uy };
    if (nextToHero) {
        const spots = arrivalNearbyCoords(game.u.ux, game.u.uy);
        const open = pos => {
            const loc = game.level?.at(pos.x, pos.y);
            const blockedByMonster = (game.level?.monsters || [])
                .some(mon => mon.mx === pos.x && mon.my === pos.y);
            const blockedByBoulder = (game.level?.objects || [])
                .some(obj => obj.otyp === BOULDER && obj.ox === pos.x && obj.oy === pos.y);
            const closedDoor = loc?.typ === DOOR && (loc.doormask & (D_CLOSED | D_LOCKED));
            return loc && ACCESSIBLE(loc.typ) && !closedDoor && !blockedByMonster && !blockedByBoulder;
        };
        spot = spots.find(open) || arrivalNearbyCoords(game.u.ux, game.u.uy, 0).slice(spots.length).find(open) || spot;
    }
    follower.mx = spot.x;
    follower.my = spot.y;
    follower.mux = game.u.ux;
    follower.muy = game.u.uy;
    updateMonsterTrack(follower);
    if (first) game.level.monsters.unshift(follower);
    else game.level.monsters.push(follower);
    resolveArrivalCollision(follower);
}

// C ref: src/dog.c losedogs() After_you pass + mon_arrive() — monsters that
// migrated to this level on their own (e.g. fell through a trap door, see
// migrateMonsterToLevelRandom) are placed when the hero arrives.  Only the
// MIGR_RANDOM case can be queued today; it lands via rloc (teleport.c),
// whose per-attempt rolls (rnd(COLNO-1), rn2(ROWNO)) must happen exactly
// here, between obj_delivery and the fall-damage site (do.c:1816,1990).
// mon_catchup_elapsed_time and the mnearto/xlocale modes consume no RNG and
// are not needed for MIGR_RANDOM; on total placement failure the monster
// goes back into limbo (dog.c failed_arrivals -> m_into_limbo).
function arriveMigratingMonsters() {
    const queue = game.migrating_mons;
    if (!queue?.length || !game.level) return;
    const dnum = game.u?.uz?.dnum ?? 0;
    const dlevel = game.u?.uz?.dlevel ?? 0;
    for (const mon of [...queue]) {
        if (!mon || (mon.mux ?? -1) !== dnum || (mon.muy ?? -1) !== dlevel) continue;
        const xyloc = mon.mtrack?.[0]?.x ?? -1;
        if (xyloc !== MIGR_RANDOM) continue; // no other mode is queued today
        queue.splice(queue.indexOf(mon), 1);
        // C ref: dog.c mon_arrive() — inserts at the head of fmon, so the
        // arrival is processed first; the port iterates level.monsters in
        // reverse, so the equivalent here is the END of the array.
        game.level.monsters.push(mon);
        mon.mstate = ((mon.mstate || 0) & ~(MON_MIGRATING | MON_LIMBO));
        if (Number.isInteger(mon.mstrategy)) mon.mstrategy |= STRAT_ARRIVE;
        else mon.mstrategy = STRAT_ARRIVE;
        mon.mux = game.u?.ux ?? 0;
        mon.muy = game.u?.uy ?? 0;
        mon.mtrack = [];
        const placed = rlocNoMsg(mon, { allowUnset: true });
        if (!placed || !mon.mx) {
            // back into limbo: re-queue and remove from the map list
            game.level.monsters = game.level.monsters.filter(other => other !== mon);
            mon.mx = 0;
            mon.my = 0;
            mon.mstate = (mon.mstate || 0) | MON_MIGRATING;
            queue.push(mon);
        }
    }
}

function arrivalObjectListRows(objects) {
    const sorted = [...objects]
        .map((obj, index) => ({ obj, index }))
        .sort((a, b) => {
            const corpseOrder = ((b.obj.otyp === 'corpse' || b.obj.otyp === CORPSE) ? 1 : 0)
                - ((a.obj.otyp === 'corpse' || a.obj.otyp === CORPSE) ? 1 : 0);
            if (corpseOrder) return corpseOrder;
            if (a.obj.pileIndex != null || b.obj.pileIndex != null)
                return (a.obj.pileIndex || 0) - (b.obj.pileIndex || 0);
            return b.index - a.index;
        })
        .map(item => item.obj);
    const attachedOnly = sorted.length > 0
        && sorted.every(obj => obj === game.u?.uchain || obj === game.u?.uball);
    const listCol = game.level?._object_list_col ?? (attachedOnly ? 40 : 41);
    const header = game.u?.blind ? 'Things that you feel here:' : 'Things that are here:';
    const rows = [[0, listCol, header]];
    for (let i = 0; i < sorted.length; i++) {
        const obj = sorted[i];
        rows.push([i + 1, listCol, obj.otyp === BOULDER ? 'a boulder'
            : BAG_OBJECT_TYPES.has(obj.otyp) ? 'a bag' : pickupObjectPhrase(obj)]);
    }
    rows.push([sorted.length + 1, listCol, '--More--']);
    return rows;
}

function rememberObjectsAtHero() {
    const ux = game.u?.ux;
    const uy = game.u?.uy;
    if (!game.level?.objects || ux == null || uy == null) return;
    for (const obj of game.level.objects) {
        if (obj.hidden || obj.transientProjectile) continue;
        if (obj.ox !== ux || obj.oy !== uy) continue;
        obj.seen = true;
        obj._hide_until_seen = false;
    }
}

function deathCountAdverb(count) {
    if (count === 1) return 'once';
    if (count === 2) return 'twice';
    if (count === 3) return 'thrice';
    return `${count} times`;
}

function removeCarriedPunishmentObjects(objects) {
    if (!objects.length || !game.level?.objects) return;
    const positions = objects.map(obj => ({ x: obj.ox, y: obj.oy }));
    game.level.objects = game.level.objects.filter(obj => !objects.includes(obj));
    for (const pos of positions) {
        const loc = game.level.at(pos.x, pos.y);
        if (!loc) continue;
        loc.remembered_glyph = null;
        newsym(pos.x, pos.y);
    }
}

function impactDropGateText(trap) {
    if (trap?.gateText) return trap.gateText;
    if (!trap?.tseen || (trap.ttyp !== HOLE && trap.ttyp !== TRAPDOOR))
        return '';
    return trap.ttyp === TRAPDOOR ? 'through the trap door' : 'through the hole';
}

function impactDropLevelKey(level) {
    return level ? `${level.dnum}:${level.dlevel}` : '';
}

function currentMigrationSourceLevel() {
    return {
        dnum: game.u?.uz?.dnum ?? 0,
        dlevel: game.u?.uz?.dlevel ?? 1,
    };
}

function markImpactDropMigration(obj, route = {}) {
    if (!obj || !route.where || route.where === MIGR_RANDOM) return;
    obj._impactDropMigration = {
        where: route.where,
        fromLevel: { ...(route.fromLevel || currentMigrationSourceLevel()) },
        targetLevel: route.targetLevel ? { ...route.targetLevel } : null,
        isLadder: !!route.isLadder,
    };
}

export function queueImpactDroppedObjects(targetLevel, objects, route = {}) {
    if (!targetLevel || !objects?.length) return;
    game._impact_drop_migrations ??= new Map();
    const key = impactDropLevelKey(targetLevel);
    const queued = game._impact_drop_migrations.get(key) || [];
    for (const obj of objects) markImpactDropMigration(obj, { ...route, targetLevel });
    queued.push(...objects);
    game._impact_drop_migrations.set(key, queued);
}

function emptyImpactDropResult(overrides = {}) {
    return {
        message: '',
        objects: [],
        objectCount: 0,
        fallenCount: 0,
        ...overrides,
    };
}

function impactDropRandomLandingSpot() {
    const candidates = [];
    for (let x = 1; x < COLNO; x++)
        for (let y = 0; y < ROWNO; y++) {
            const loc = game.level?.at(x, y);
            if (!loc || !ACCESSIBLE(loc.typ)) continue;
            candidates.push({ x, y });
        }
    return candidates.length ? candidates[rn2(candidates.length)]
        : { x: game.u?.ux || 0, y: game.u?.uy || 0 };
}

function impactDropMigrationLandingSpot(migration) {
    if (!migration || migration.where === MIGR_RANDOM) return null;
    const from = migration.fromLevel;
    if (!from) return null;
    const needLadder = migration.where === MIGR_LADDER_UP || migration.isLadder;
    for (let stair = game.stairs; stair; stair = stair.next) {
        if (!!stair.isladder !== !!needLadder) continue;
        if (stair.tolev?.dnum === from.dnum && stair.tolev?.dlevel === from.dlevel)
            return { x: stair.sx, y: stair.sy };
    }
    return null;
}

function impactDropDeliveryLandingIsSoft(x, y) {
    const loc = game.level?.at?.(x, y);
    return !!(loc && IS_SOFT(loc.typ));
}

function impactDropScatterBlocked(loc) {
    if (!loc) return true;
    const closedDoor = loc.typ === DOOR && (loc.doormask & (D_CLOSED | D_LOCKED));
    return !ZAP_POS(loc.typ) || closedDoor;
}

function impactDropScatterExactDeliveryObject(obj, sx, sy) {
    if (!obj || !game.level) return;
    const blastforce = rnd(2);
    const dir = rn2(N_DIRS);
    const dx = xdir[dir] || 0;
    const dy = ydir[dir] || 0;
    const scatterForce = Math.max(1, blastforce - Math.trunc(floorEffectsObjectWeight(obj) / 40));
    let range = rnd(scatterForce);
    let x = sx;
    let y = sy;

    while (range-- > 0) {
        const nx = x + dx;
        const ny = y + dy;
        if (!isok(nx, ny)) break;
        const loc = game.level.at(nx, ny);
        if (impactDropScatterBlocked(loc)) break;
        x = nx;
        y = ny;
        if (loc.typ === SINK) break;
    }

    obj.ox = x;
    obj.oy = y;
    obj.hidden = false;
    obj.transientProjectile = false;

    if (earthFloorEffects(obj, x, y, [], 'land')) {
        game.level.objects = (game.level.objects || []).filter(item => item !== obj);
    } else {
        stackDroppedFloorObject(obj);
    }
    newsym(x, y);
    if (x !== sx || y !== sy) newsym(sx, sy);
}

function deliverQueuedImpactDroppedObjects(targetLevel) {
    const key = impactDropLevelKey(targetLevel);
    const queued = game._impact_drop_migrations?.get?.(key) || [];
    if (!queued.length || !game.level) return;
    game._impact_drop_migrations.delete(key);
    game.level.objects ??= [];
    for (const obj of queued) {
        const exactSpot = impactDropMigrationLandingSpot(obj._impactDropMigration);
        const spot = exactSpot || impactDropRandomLandingSpot();
        delete obj._impactDropMigration;
        obj.ox = spot.x;
        obj.oy = spot.y;
        obj.hidden = false;
        obj.transientProjectile = false;
        if (!impactDropDeliveryLandingIsSoft(spot.x, spot.y) && impactDropObjectBreaks(obj)) {
            newsym(spot.x, spot.y);
            continue;
        }
        if (exactSpot) {
            game.level.objects.push(obj);
            stackDroppedFloorObject(obj);
            impactDropScatterExactDeliveryObject(obj, spot.x, spot.y);
        } else {
            game.level.objects.push(obj);
            newsym(spot.x, spot.y);
        }
    }
}

function impactDropCandidatePile(x, y, { missile = null } = {}) {
    return (game.level?.objects || []).filter(obj =>
        obj !== missile && !obj.hidden && !obj.transientProjectile && obj.ox === x && obj.oy === y);
}

function impactDropPileQuantity(pile) {
    return pile.reduce((sum, obj) => sum + (obj.quan || 1), 0);
}

export function impactDropFloorObjects(x, y, trap, options = {}) {
    const gateText = impactDropGateText(trap);
    if (!gateText || !game.level?.objects?.length) return emptyImpactDropResult();
    if (!options.withHero && !options.targetLevel) return emptyImpactDropResult();
    const pile = impactDropCandidatePile(x, y, { missile: options.missile });
    if (!pile.length) return emptyImpactDropResult();

    let objectCount = 0;
    let fallenCount = 0;
    const fallen = [];
    for (const obj of pile) {
        const quantity = obj.quan || 1;
        objectCount += quantity;
        if (obj === game.u?.uball || obj === game.u?.uchain) continue;
        if (options.missileImpact && options.missile?.otyp === ROCK && obj.otyp === BOULDER) continue;
        if (rn2(obj.otyp === BOULDER ? 30 : 3)) continue;
        fallen.push(obj);
        fallenCount += quantity;
    }
    if (!fallen.length) return emptyImpactDropResult({ objectCount });

    game.level.objects = (game.level.objects || []).filter(obj => !fallen.includes(obj));
    newsym(x, y);

    let message = '';
    const visible = !game.u?.blind && (options.missileImpact ? cansee(x, y) : couldsee(x, y));
    if (visible) {
        const what = fallenCount === 1 ? 'object falls' : 'objects fall';
        if (options.missileImpact) {
            const qualifier = fallenCount === objectCount ? 'the ' : fallenCount === 1 ? 'an' : '';
            message = `From the impact, ${qualifier}other ${what}.`;
        } else if (fallenCount === objectCount) {
            message = `${fallenCount === 1 ? 'The' : 'All the'} adjacent ${what} ${gateText}.`;
        } else {
            message = `${fallenCount === 1 ? 'One of the' : 'Some of the'} adjacent ${fallenCount === 1 ? 'objects falls' : what} ${gateText}.`;
        }
    }
    let debitDelta = 0;
    let robbedDelta = 0;
    let debtShkp = null;
    for (const obj of fallen) {
        const debt = shipObjectShopDebt(obj, x, y, { shopFloorObj: true, silent: true });
        debitDelta += debt.debitDelta || 0;
        robbedDelta += debt.robbedDelta || 0;
        if (debt.shkp) debtShkp = debt.shkp;
    }
    if (debitDelta > 0)
        message = [message, `You owe ${shopkeeperDisplayName(debtShkp)} ${debitDelta} ${shopCurrency(debitDelta)} for goods lost.`]
            .filter(Boolean).join('  ');
    if (robbedDelta > 0)
        message = [message, `You removed ${robbedDelta} ${shopCurrency(robbedDelta)} worth of goods!`]
            .filter(Boolean).join('  ');

    if (!options.withHero) {
        queueImpactDroppedObjects(options.targetLevel, fallen, options.route || {});
        return emptyImpactDropResult({ message, objectCount, fallenCount });
    }
    return emptyImpactDropResult({ message, objects: fallen, objectCount, fallenCount });
}

function impactDropObjectClass(obj) {
    return obj?.cls || (obj?.otyp === POTION_CLASS || obj?.glyph === '!' ? 'potion'
        : obj?.otyp === SCROLL_CLASS || obj?.glyph === '?' ? 'scroll'
            : obj?.glyph === '+' ? 'spellbook'
                : obj?.glyph === '*' ? 'gem' : '');
}

function isGlassMaterialWandObject(obj) {
    if (!obj || !isWandItem(obj) || obj.artifact || obj.oartifact) return false;
    const material = String(obj.material || obj.oc_material || '').toLowerCase().replace(/^hi_/, '');
    if (material === 'glass' || material === 'crystal') return true;
    const appearance = String(
        obj.appearance || obj.wandAppearance || (obj.wandIndex != null ? game._object_descriptions?.wands?.[obj.wandIndex]?.description : ''),
    ).toLowerCase();
    if (appearance === 'glass' || appearance === 'crystal') return true;
    return /^(glass|crystal) wand$/.test(objectKindKey(obj));
}

function impactDropBreakKind(obj) {
    const cls = impactDropObjectClass(obj);
    const name = String(obj?.actualKind || obj?.kind || pickupObjectName(obj)).toLowerCase();
    if (cls === 'potion') return 'shatter';
    if (isBreaktestVenomObject(obj)) return 'splash';
    if (obj?.otyp === EGG || name === 'egg') return 'splat';
    if (name.includes('melon')) return 'splat';
    if (name.includes('cream pie')) return 'mess';
    if (isGlassMaterialWandObject(obj)) return 'pieces';
    if (obj?.otyp === EXPENSIVE_CAMERA || obj?.otyp === MIRROR
        || name.includes('mirror') || name.includes('looking glass')
        || name.includes('crystal ball') || name.includes('lenses'))
        return 'pieces';
    if (breaktestGlassMaterialObject(obj)) return 'pieces';
    if (cls !== 'gem' && /\bglass\b|\bcrystal\b/.test(name)) return 'shatter';
    return '';
}

function impactDropObjectBreaks(obj) {
    if (!obj) return '';
    const ordinaryResistChance = 1;
    const artifactResistChance = 99;
    const hasArtifact = objectHasArtifactIdentity(obj);
    if (rn2(100) < (hasArtifact ? artifactResistChance : ordinaryResistChance)) return '';
    if (hasArtifact && !breaktestExplicitSwitchObject(obj)) return '';
    return impactDropBreakKind(obj);
}

function objectHasArtifactIdentity(obj) {
    return !!(obj?.artifact || obj?.oartifact);
}

function breaktestExplicitSwitchObject(obj) {
    return isExpensiveCameraObject(obj) || isPotionObject(obj) || isEggItem(obj)
        || isCreamPieObject(obj) || isMelonObject(obj) || isBreaktestVenomObject(obj);
}

function breaktestGlassMaterialObject(obj) {
    if (!obj) return false;
    const cls = impactDropObjectClass(obj);
    if (cls === 'gem' || cls === 'armor' || obj.glyph === '[' || obj.otyp === ARMOR_CLASS)
        return false;
    const material = String(obj.material || obj.oc_material || '').toLowerCase().replace(/^hi_/, '');
    return material === 'glass';
}

function isBreaktestVenomObject(obj) {
    const kind = objectKindKey(obj);
    return obj?.otyp === BLINDING_VENOM || obj?.otyp === ACID_VENOM
        || kind === 'splash of blinding venom' || kind === 'splash of acid venom';
}

function shipObjectMuffledBreakResult(breakKind) {
    return breakKind === 'splat' || breakKind === 'splash' ? breakKind : 'crash';
}

function impactDropLandingIsSoft() {
    const loc = game.level?.at(game.u?.ux || 0, game.u?.uy || 0);
    if (!loc) return false;
    return IS_POOL(loc.typ) || loc.typ === WATER || loc.typ === MOAT
        || loc.typ === LAVAPOOL || loc.typ === LAVAWALL;
}

function deliverImpactDroppedObjects(objects) {
    if (!objects?.length || !game.level || !game.u) return '';
    const messages = [];
    const hardLanding = !impactDropLandingIsSoft();
    for (const obj of objects) {
        obj.ox = game.u.ux || 0;
        obj.oy = game.u.uy || 0;
        obj.hidden = false;
        obj.transientProjectile = false;
        const breakKind = hardLanding ? impactDropObjectBreaks(obj) : '';
        if (breakKind) {
            if (breakKind === 'splat') messages.push('Splat!');
            else if (breakKind === 'splash') messages.push('Splash!');
            else if (breakKind === 'mess') messages.push('What a mess!');
            else if (game.u.blind) messages.push('You hear something shatter!');
            else {
                const name = pickupObjectName({ ...obj, quan: obj.quan || 1 });
                const many = (obj.quan || 1) > 1;
                const subject = many ? `The ${name}` : (/^[aeiou]/i.test(name) ? `An ${name}` : `A ${name}`);
                const verb = many ? 'shatter' : 'shatters';
                messages.push(`${subject} ${verb}${breakKind === 'pieces' ? ' into a thousand pieces' : ''}!`);
            }
            brokenPotionBreathe(obj, game.u.ux || 0, game.u.uy || 0, messages);
            continue;
        }
        game.level.objects.push(obj);
    }
    newsym(game.u.ux || 0, game.u.uy || 0);
    return messages.join('  ');
}

function heroStairway() {
    for (let stair = game.stairs; stair; stair = stair.next)
        if (stair.sx === game.u?.ux && stair.sy === game.u?.uy) return stair;
    return null;
}

function placeRockAtHero() {
    const rock = mksobj(ROCK, false, false);
    Object.assign(rock, {
        otyp: ROCK,
        ox: game.u?.ux || 0,
        oy: game.u?.uy || 0,
        quan: 1,
        cls: 'gem',
        kind: 'rock',
        singular: 'rock',
        plural: 'rocks',
        glyph: '*',
    });
    game.level.objects ??= [];
    game.level.objects.push(rock);
    newsym(rock.ox, rock.oy);
}

function zapDigFallingRockMessage(stair = null) {
    const messages = [];
    if (stair)
        messages.push(`The beam bounces off the ${stair.isladder ? 'ladder' : 'stairs'} and hits the ceiling.`);
    messages.push('You loosen a rock from the ceiling.');
    messages.push('It falls on your head!');
    const helmet = wornEarthHelmet();
    const damage = rnd(helmet && hardEarthHelmet(helmet) ? 2 : 6);
    if (game.u) {
        game.u.uhp = Math.max(0, (game.u.uhp || 1) - damage);
        if ((game.u.uhp || 0) <= 0) game._death_cause = 'falling rock';
    }
    placeRockAtHero();
    return trapMessage(...messages);
}

function dugHoleFallTarget() {
    const current = game.u?.uz || { dnum: 0, dlevel: 1 };
    return clampDungeonLevel({ dnum: current.dnum, dlevel: current.dlevel + 1 });
}

function downwardDigTrapAt(x, y) {
    return (game.level?.traps || []).find(trap => trap.tx === x && trap.ty === y) || null;
}

function removeDownwardDigTrap(trap) {
    if (!trap || !game.level?.traps) return;
    game.level.traps = game.level.traps.filter(candidate => candidate !== trap);
}

function downwardDigTooHardResult() {
    return { message: 'The floor here is too hard to dig in.', more: false };
}

function downwardDigBoulderResult(x, y, trap) {
    const boulder = (game.level?.objects || []).find(obj =>
        !obj.hidden && !obj.transientProjectile && obj.ox === x && obj.oy === y && obj.otyp === BOULDER);
    if (!boulder) return null;

    game.level.objects = (game.level?.objects || []).filter(obj => obj !== boulder);
    if (trap && (trap.ttyp === PIT || trap.ttyp === SPIKED_PIT) && rn2(2)) {
        trap.ttyp = PIT;
        trap.tseen = true;
        newsym(x, y);
        return { message: 'The boulder settles into the pit.', more: false };
    }

    removeDownwardDigTrap(trap);
    newsym(x, y);
    return { message: 'KADOOM!  The boulder falls in!', more: false };
}

// C ref: dig.c:use_pick_axe2() — starting a downward dig inside a shop
// triggers shopdig(0) and bills SHOP_PIT_COST of floor damage.
function pickDigShopFloorMessages() {
    const x = game.u?.ux || 0;
    const y = game.u?.uy || 0;
    const roomnos = shopRoomnosAt(x, y, SHOPBASE);
    if (!roomnos.length) return [];
    const messages = [];
    const shkp = shopkeeperForRoomno(roomnos[0]);
    if (shopkeeperInHisShop(shkp) && !heroIsDeaf()) {
        const name = shopkeeperDisplayName(shkp);
        if (game.u?.utrap && (game.u.utraptype === TT_PIT || game.u.utraptype === 'pit')) {
            messages.push(`${name} says: "Be careful, ${game.flags?.female ? 'madam' : 'sir'}, or you might fall through the floor."`);
        } else {
            messages.push(`${name} says: "${game.flags?.female ? 'Madam' : 'Sir'}, do not damage the floor here!"`);
        }
    }
    if ((game.urole?.name?.m || game._startup_role) === 'Knight' && game.u?.ualign) {
        messages.push('You feel like a common thief.');
        const alignType = Number(game.u.ualign.type ?? 0);
        game.u.ualign.record = (game.u.ualign.record || 0) - Math.sign(alignType);
    }
    addShopTerrainDamage(x, y, 100); // C ref: hack.h SHOP_PIT_COST
    return messages;
}

// C ref: dig.c:digactualhole() PIT at hero — fall in unless levitating.
function applyDigPitHeroTrap() {
    if (!game.u) return;
    if (!(game.u.levitating || game.u.flying)) {
        game.u.utrap = rn1(4, 2);
        game.u.utraptype = 'pit';
    } else {
        game.u.utrap = 0;
        game.u.utraptype = null;
    }
}

// C ref: dig.c:digactualhole() PIT shop accounting — a pit that replaces a
// shop door is paid for immediately; other shop floor pits are billed.
function applyDigPitShopDamage(x, y, wasShopDoor, messages) {
    if (wasShopDoor) payForCurrentShopTerrainDamage('ruin', messages);
    else addShopTerrainDamage(x, y, 100); // C ref: hack.h SHOP_PIT_COST
}

// C ref: dig.c:dighole() — grave, fountain and liquid-fill branches shared
// by the pit and hole outcomes.  Returns null when plain digging proceeds.
async function digholeSpecialTerrainResult(x, y, trap) {
    const loc = game.level?.at?.(x, y);
    if (loc?.typ === GRAVE) {
        const pit = await maketrap(x, y, PIT);
        if (!pit) return { message: '', more: false };
        pit.madeby_u = true;
        pit.tseen = true;
        applyDigPitHeroTrap();
        const messages = [`You dig a pit in the ${digSurfaceText(x, y)}.`, 'The grave falls into the pit!'];
        messages.push(...await digUpGrave(x, y));
        wakeNearbyMonstersAt(x, y, (game.u?.ulevel || 1) * 20);
        return { message: trapMessage(...messages), more: messages.length > 1 };
    }
    if (loc?.typ === FOUNTAIN) {
        loc.fountainWarned = true; // SET_FOUNTAIN_WARNED forces dryup
        const dry = dryupFountainResultAt(x, y);
        const messages = ['Water sprays all over you.'];
        if (dry.dried) messages.push('The fountain dries up!');
        else if (dry.trickle) messages.push(dry.trickle);
        else if (dry.warning) messages.push(dry.warning);
        return { message: trapMessage(...messages), more: messages.length > 1 };
    }
    const fillType = fillHoleType(x, y, false);
    if (fillType !== ROOM) {
        const messages = [];
        const liquidFlow = earthquakeLiquidFlow(x, y, fillType, trap, messages,
            { fillMessage: `As you dig, the hole fills with ${fillType === LAVAPOOL ? 'lava' : 'water'}!` });
        return {
            message: trapMessage(...messages),
            more: messages.length > 1 || !!liquidFlow?.heroResult?.more,
            heroResult: liquidFlow?.heroResult || null,
        };
    }
    return null;
}

async function digDownwardPitResult(options = {}) {
    const current = game.u?.uz || { dnum: 0, dlevel: 1 };
    if (Is_airlevel(current) || Is_waterlevel(current))
        return { message: options.pick ? 'You swing your pick through thin air.' : '', more: false };

    const x = game.u?.ux || 0;
    const y = game.u?.uy || 0;
    const trap = downwardDigTrapAt(x, y);
    if (!canDigDownFromLevel(current) && trap) return downwardDigTooHardResult();
    const boulderResult = downwardDigBoulderResult(x, y, trap);
    if (boulderResult) return boulderResult;
    if (isBuriedBallTrapActive()) buriedBallToPunishment();

    const special = await digholeSpecialTerrainResult(x, y, trap);
    if (special) return special;

    const wasShopDoor = game.level?.at?.(x, y)?.typ === DOOR
        && shopRoomnosAt(x, y, SHOPBASE).length > 0;
    const pit = await maketrap(x, y, PIT);
    if (!pit) return { message: '', more: false };
    pit.madeby_u = true;
    pit.tseen = true;
    applyDigPitHeroTrap();
    const messages = [`You dig a pit in the ${digSurfaceText(x, y)}.`];
    applyDigPitShopDamage(x, y, wasShopDoor, messages);
    wakeNearbyMonstersAt(x, y, (game.u?.ulevel || 1) * 20);
    return { message: trapMessage(...messages), more: messages.length > 1 };
}

async function digDownwardHoleResult(options = {}) {
    const current = game.u?.uz || { dnum: 0, dlevel: 1 };
    if (Is_airlevel(current) || Is_waterlevel(current))
        return { message: options.pick ? 'You swing your pick through thin air.' : '', more: false };

    const x = game.u?.ux || 0;
    const y = game.u?.uy || 0;
    const existingTrap = downwardDigTrapAt(x, y);
    if (!canDigDownFromLevel(current)) {
        if (existingTrap) return downwardDigTooHardResult();
        return digDownwardPitResult(options);
    }

    const boulderResult = downwardDigBoulderResult(x, y, existingTrap);
    if (boulderResult) return boulderResult;
    if (isBuriedBallTrapActive()) buriedBallToPunishment();

    const special = await digholeSpecialTerrainResult(x, y, existingTrap);
    if (special) return special;

    const trap = await maketrap(x, y, HOLE);
    if (!trap) return { message: '', more: false };
    trap.madeby_u = true;
    trap.tseen = true;
    if (game.u) {
        game.u.utrap = 0;
        game.u.utraptype = null;
    }
    const messages = ['You dig a hole through the floor.'];
    const target = dugHoleFallTarget();
    const noFall = game.u?.levitating || game.u?.flying || game.u?.ustuck || !target;
    if (noFall) {
        if (!shopRoomnosAt(x, y, SHOPBASE).length)
            payForCurrentShopTerrainDamage('dig into', messages);
        const dropTarget = sitFallTargetLevel(trap) || target;
        const impact = impactDropFloorObjects(x, y, trap, { targetLevel: dropTarget });
        if (impact.message) messages.push(impact.message);
        return { message: trapMessage(...messages), more: messages.length > 1 };
    }

    // C: in a shop the keeper may snatch the pack (shopdig(1), not ported);
    // otherwise earlier hero-caused damage is settled before falling.
    if (!shopRoomnosAt(x, y, SHOPBASE).length)
        payForCurrentShopTerrainDamage('dig into', messages);
    messages.push('You fall through...');
    const impact = impactDropFloorObjects(x, y, trap, { targetLevel: target, withHero: true });
    if (impact.message) messages.push(impact.message);
    scheduleSitLevelChange(target, {
        falling: true,
        fallingDamage: !game.u?.flying,
        arrivalMessage: '',
        impactDroppedObjects: impact.objects,
    });
    return { message: trapMessage(...messages), more: true };
}

function earthquakeLevelDescription() {
    const uz = game.u?.uz || { dnum: 0, dlevel: 1 };
    if (Is_astralevel(uz)) return 'astral plane';
    if (In_endgame(uz)) return 'plane';
    if (currentSpecialLevelName() === 'sanctum') return 'sanctum';
    if (In_sokoban(uz)) return 'puzzle';
    if (In_V_tower(uz)) return 'tower';
    return 'dungeon';
}

function isPitTrapType(type) {
    return type === PIT || type === SPIKED_PIT || type === TT_PIT || type === 'pit' || type === 'spiked pit';
}

function altarMask(loc) {
    return loc?.altarmask ?? loc?.flags ?? 0;
}

function earthquakeAltarAlignName(loc) {
    const align = Amask2align(altarMask(loc));
    if (align === A_LAWFUL) return 'lawful';
    if (align === A_NEUTRAL) return 'neutral';
    if (align === A_CHAOTIC) return 'chaotic';
    return 'unaligned';
}

function earthquakeFeatureMessage(loc) {
    if (loc?.typ === FOUNTAIN) return 'The fountain falls into a chasm.';
    if (loc?.typ === SINK) return 'The kitchen sink falls into a chasm.';
    if (loc?.typ === GRAVE) return 'The headstone topples into a chasm.';
    if (loc?.typ === THRONE) return 'The throne falls into a chasm.';
    if (loc?.typ === ALTAR) return `The ${earthquakeAltarAlignName(loc)} altar falls into a chasm.`;
    return '';
}

function normalizeEarthquakePitTerrain(x, y) {
    const loc = game.level?.at(x, y);
    if (!loc) return;
    const oldTyp = loc.typ;
    if (IS_ROOM(oldTyp)) loc.typ = ROOM;
    else if (oldTyp === STONE || oldTyp === SCORR) loc.typ = CORR;
    else if (IS_WALL(oldTyp) || oldTyp === SDOOR) loc.typ = game.level?.flags?.is_maze_lev ? ROOM
        : game.level?.flags?.is_cavernous_lev ? CORR
            : DOOR;
    loc.flags = 0;
    loc.doormask = D_NODOOR;
    loc.wall_info = 0;
}

function makeEarthquakePitTrap(x, y) {
    const existing = downwardDigTrapAt(x, y);
    if (existing && (existing.ttyp === MAGIC_PORTAL || existing.ttyp === VIBRATING_SQUARE)) return null;
    const trap = existing || { tx: x, ty: y };
    Object.assign(trap, {
        ttyp: PIT,
        tseen: true,
        once: false,
        launch: { x: -1, y: -1 },
        launch2: null,
        teledest: null,
        dst: { dnum: -1, dlevel: -1 },
        conjoined: 0,
    });
    game.level.traps ??= [];
    if (!existing) game.level.traps.push(trap);
    normalizeEarthquakePitTerrain(x, y);
    return trap;
}

function drawbridgeUnder(loc) {
    return (loc?.flags || 0) & DB_UNDER;
}

function movementSurfaceTerrain(loc) {
    if (!loc) return undefined;
    if (loc.typ !== DRAWBRIDGE_UP) return loc.typ;
    switch (drawbridgeUnder(loc)) {
    case DB_LAVA:
        return LAVAPOOL;
    case DB_ICE:
        return ICE;
    case DB_FLOOR:
        return ROOM;
    case DB_MOAT:
    default:
        return MOAT;
    }
}

function movementIsPoolAt(x, y, loc = game.level?.at(x, y)) {
    if (!loc) return false;
    if (loc.typ === POOL || loc.typ === MOAT || loc.typ === WATER) return true;
    return loc.typ === DRAWBRIDGE_UP
        && drawbridgeUnder(loc) === DB_MOAT
        && currentSpecialLevelName() !== 'juiblex';
}

function movementIsLavaAt(x, y, loc = game.level?.at(x, y)) {
    if (!loc) return false;
    return loc.typ === LAVAPOOL || loc.typ === LAVAWALL
        || (loc.typ === DRAWBRIDGE_UP && drawbridgeUnder(loc) === DB_LAVA);
}

function movementIsLiquidAt(x, y, loc = game.level?.at(x, y)) {
    return movementIsPoolAt(x, y, loc) || movementIsLavaAt(x, y, loc);
}

function earthquakeIsMoatAt(x, y) {
    const loc = game.level?.at(x, y);
    if (!loc || currentSpecialLevelName() === 'juiblex') return false;
    return loc.typ === MOAT || (loc.typ === DRAWBRIDGE_UP && drawbridgeUnder(loc) === DB_MOAT);
}

function earthquakeIsLavaAt(x, y) {
    const loc = game.level?.at(x, y);
    if (!loc) return false;
    return IS_LAVA(loc.typ) || (loc.typ === DRAWBRIDGE_UP && drawbridgeUnder(loc) === DB_LAVA);
}

function earthquakeIsPoolAt(x, y) {
    const loc = game.level?.at(x, y);
    if (!loc) return false;
    return loc.typ === POOL || loc.typ === MOAT || loc.typ === WATER || earthquakeIsMoatAt(x, y);
}

function earthquakeSpotChecksOldIce(loc) {
    return loc?.typ === ICE || (loc?.typ === DRAWBRIDGE_UP && drawbridgeUnder(loc) === DB_ICE);
}

function earthquakeFillHoleType(x, y) {
    const loX = Math.max(1, x - 1);
    const hiX = Math.min(x + 1, COLNO - 1);
    const loY = Math.max(0, y - 1);
    const hiY = Math.min(y + 1, ROWNO - 1);
    let poolCnt = 0;
    let moatCnt = 0;
    let lavaCnt = 0;
    for (let x1 = loX; x1 <= hiX; x1++) {
        for (let y1 = loY; y1 <= hiY; y1++) {
            if (earthquakeIsMoatAt(x1, y1)) moatCnt++;
            else if (earthquakeIsPoolAt(x1, y1)) poolCnt++;
            else if (earthquakeIsLavaAt(x1, y1)) lavaCnt++;
        }
    }

    poolCnt = Math.trunc(poolCnt / 3);
    if (lavaCnt > moatCnt + poolCnt && rn2(lavaCnt + 1)) return LAVAPOOL;
    if (moatCnt > 0 && rn2(moatCnt + 1)) return MOAT;
    if (poolCnt > 0 && rn2(poolCnt + 1)) return POOL;
    return ROOM;
}

function setEarthquakeLiquidTerrain(x, y, typ) {
    const loc = game.level?.at(x, y);
    if (!loc) return false;
    const oldIce = earthquakeSpotChecksOldIce(loc);
    loc.typ = typ;
    loc.flags = 0;
    loc.doormask = 0;
    loc.wall_info = 0;
    if (typ === LAVAPOOL) loc.lit = true;
    if (oldIce && !earthquakeSpotChecksOldIce(loc)) stopMeltIceTimersAt(x, y);
    newsym(x, y);
    return true;
}

function deleteEarthquakeLiquidTrap(trap, x, y) {
    if (game.u?.ux === x && game.u?.uy === y && game.u.utraptype !== TT_BURIEDBALL) {
        game.u.utrap = 0;
        game.u.utraptype = null;
    }
    const mon = (game.level?.monsters || []).find(candidate => candidate.mx === x && candidate.my === y);
    if (mon) mon.mtrapped = 0;
    removeDownwardDigTrap(trap);
}

function applyEarthquakeHeroLiquidEffects(x, y, typ, messages) {
    if (game.u?.ux !== x || game.u?.uy !== y) return null;
    if (game.u?.levitating || game.u?.flying) return null;
    if (typ === LAVAPOOL) {
        const lavaEffect = heroLavaEntryEffect(LAVAPOOL);
        messages.push(...lavaEffect.messages);
        if (lavaEffect.lavaDeath) {
            game.u.uhp = 0;
            game.context ??= {};
            game.context.move = 0;
            game._pending_time_passed = 0;
            messages.push('You die...');
        }
        return lavaEffect;
    }
    game.u.uinwater = 1;
    game.u.underwater = true;
    game.u.uunderwater = true;
    messages.push(`You fall into the ${typ === MOAT ? 'moat' : 'pool of water'}!  You sink like a rock.`);
    return null;
}

function earthquakeLiquidFlow(x, y, typ, trap, messages, { fillMessage = '' } = {}) {
    if (!setEarthquakeLiquidTerrain(x, y, typ)) return null;
    deleteEarthquakeLiquidTrap(trap, x, y);
    objIceEffectsAt(x, y, { doBuried: true });
    unearthObjectsAt(x, y);
    if (fillMessage) messages.push(fillMessage);
    messages.push(...applyLiquidFlowFloorObjectDamage(x, y, typ).messages);
    let heroResult = null;
    if (game.u?.ux === x && game.u?.uy === y)
        heroResult = applyEarthquakeHeroLiquidEffects(x, y, typ, messages);
    else messages.push(...applyMonsterLiquidEffectsAt(x, y, { heroCaused: true, recordKill: recordVanquished }));
    newsym(x, y);
    return { heroResult };
}

function landmineMaybeDunkLiquidBoulders(x, y, messages) {
    const loc = game.level?.at?.(x, y);
    while (earthBoulderHitsLiquid(loc)) {
        const boulder = (game.level?.objects || []).find(obj =>
            isBoulderObject(obj) && obj.ox === x && obj.oy === y && !obj.buried && !obj.transientProjectile);
        if (!boulder) break;
        if (!earthFloorEffects(boulder, x, y, messages, 'fall', { usedUpShopBillOnDestroy: true })) break;
        removeFloorObject(boulder);
    }
}

function landmineRefreshPostBlastBlockPoint(x, y) {
    vision_reset();
    vision_recalc(0);
    newsym(x, y);
}

function earthquakeMonsterName(mon, { capital = true, article = true } = {}) {
    if (mon?.givenName) return mon.givenName;
    if (mon?.isshk && mon.shknam) return mon.shknam;
    const name = mon?.data?.name || mon?.name || 'monster';
    if (!article) return name;
    return `${capital ? 'The' : 'the'} ${name}`;
}

function earthquakeMonsterVisible(mon) {
    return !!mon && !game.u?.blind && !mon.minvis && !mon.mundetected && couldsee(mon.mx, mon.my);
}

function earthquakeMonsterHumanoid(mon) {
    const mlet = mon?.data?.mlet;
    return mlet === 'humanoid' || mlet === 'human' || mon?.data?.name === 'human';
}

function earthquakeRevealMimic(mon) {
    if (!mon || (!M_AP_TYPE(mon) && mon.appearObj == null && !mon.appearGlyph)) return false;
    mon.m_ap_type = 0;
    mon.appearObj = null;
    mon.appearGlyph = null;
    mon.appearColor = null;
    return true;
}

function earthquakeShakeMonster(x, y, messages) {
    const mon = (game.level?.monsters || []).find(candidate => candidate.mx === x && candidate.my === y);
    if (!mon) return;
    mon.msleeping = 0;
    mon.mcanmove = true;
    mon.mfrozen = 0;
    if (mon.mpeaceful && !mon.mtame && !mon.pet) mon.mpeaceful = 0;
    if (mon.mundetected) {
        const ceilingHider = !!mon.data?.ceilingHider;
        mon.mundetected = false;
        if (ceilingHider) {
            if (!game.u?.blind && couldsee(x, y))
                messages.push(`${earthquakeMonsterName(mon)} is shaken loose from the ceiling!`);
            else if (!mon.data?.flyer && !heroIsDeaf()) messages.push('You hear a thump.');
        }
        newsym(x, y);
    }
    if (earthquakeRevealMimic(mon)) newsym(x, y);
}

function earthquakeMonsterFalls(mon, messages) {
    if (!mon || mon.data?.flyer || mon.data?.clinger) return;
    const alreadyTrapped = !!mon.mtrapped;
    const visible = earthquakeMonsterVisible(mon);
    mon.mtrapped = 1;
    if (!alreadyTrapped) {
        if (visible) messages.push(`${earthquakeMonsterName(mon)} falls into a chasm!`);
        else if (earthquakeMonsterHumanoid(mon) && !heroIsDeaf()) messages.push('You hear a scream!');
    }
    mon.mhp = (mon.mhp ?? 1) - rnd(alreadyTrapped ? 4 : 6);
    if ((mon.mhp ?? 0) > 0) return;

    dropMonsterInventory(mon, messages);
    game.level.monsters = (game.level?.monsters || []).filter(candidate => candidate !== mon);
    recordVanquished(mon, true);
    newsym(mon.mx, mon.my);
    messages.push(visible
        ? `You destroy ${earthquakeMonsterName(mon, { capital: false })}!`
        : 'It is destroyed!');
}

function earthquakeHeroPitKeepFooting() {
    const roleName = game.urole?.name?.m || game._startup_role;
    const target = roleName === 'Archeologist' ? 3 : 9;
    const dex = game.u?.acurr?.a?.[A_DEX] ?? 10;
    return !(game.u?.fumbling && rn2(5))
        && (!rnl(target) || (dex > 7 && rn2(5)));
}

async function doEarthquakePit(x, y, tuPit, messages) {
    const chasm = makeEarthquakePitTrap(x, y);
    if (!chasm) return;

    const boulder = (game.level?.objects || []).find(obj =>
        !obj.hidden && !obj.transientProjectile && obj.ox === x && obj.oy === y && obj.otyp === BOULDER);
    if (boulder) {
        if (!game.u?.blind && (game.u?.ux === x && game.u?.uy === y || couldsee(x, y)))
            messages.push(`KADOOM!  The boulder falls into a chasm${game.u?.ux === x && game.u?.uy === y ? ' below you' : ''}!`);
        const mon = (game.level?.monsters || []).find(candidate => candidate.mx === x && candidate.my === y);
        if (mon) mon.mtrapped = 0;
        game.level.objects = (game.level?.objects || []).filter(obj => obj !== boulder);
        removeDownwardDigTrap(chasm);
        newsym(x, y);
        return;
    }

    const fillType = earthquakeFillHoleType(x, y);
    if (fillType !== ROOM) {
        const liquidFlow = earthquakeLiquidFlow(x, y, fillType, chasm, messages);
        if (liquidFlow?.heroResult) messages.heroResult = liquidFlow.heroResult;
        if (!downwardDigTrapAt(x, y)) return;
    }

    const mon = (game.level?.monsters || []).find(candidate => candidate.mx === x && candidate.my === y);
    if (mon) {
        earthquakeMonsterFalls(mon, messages);
        return;
    }

    if (game.u?.ux !== x || game.u?.uy !== y) {
        newsym(x, y);
        return;
    }

    if (breakBuriedBallChain()) messages.push('Your chain breaks!');
    const avoidsFall = game.u?.levitating || game.u?.flying || polyselfForm()?.clinger;
    if (avoidsFall) {
        if (!tuPit) {
            messages.push('A chasm opens up under you!');
            messages.push("You don't fall in!");
        }
    } else if (!tuPit || !game.u.utrap || !isPitTrapType(game.u.utraptype)) {
        messages.push('You fall into a chasm!');
        game.u.utrap = rn1(6, 2);
        game.u.utraptype = 'pit';
        game.u.uhp = Math.max(0, (game.u.uhp || 1) - rnd(6));
        if ((game.u.uhp || 0) <= 0) game._death_cause = 'fell into a chasm';
    } else {
        const keepFooting = earthquakeHeroPitKeepFooting();
        messages.push('You are jostled around violently!');
        game.u.utrap = rn1(6, 2);
        game.u.utraptype = 'pit';
        game.u.uhp = Math.max(0, (game.u.uhp || 1) - rnd(keepFooting ? 2 : 4));
        if ((game.u.uhp || 0) <= 0) game._death_cause = 'hurt in a chasm';
        if (keepFooting) exerciseAttribute(A_DEX, true);
    }
}

async function doEarthquake(force) {
    const ux = game.u?.ux || 0;
    const uy = game.u?.uy || 0;
    const cappedForce = Math.min(13, Math.max(1, Math.trunc(force || 1)));
    const startX = Math.max(1, ux - cappedForce * 2);
    const endX = Math.min(COLNO - 1, ux + cappedForce * 2);
    const startY = Math.max(0, uy - cappedForce * 2);
    const endY = Math.min(ROWNO - 1, uy + cappedForce * 2);
    const trapAtHero = downwardDigTrapAt(ux, uy);
    const tuPit = trapAtHero && isPitTrapType(trapAtHero.ttyp);
    const messages = [];

    for (let x = startX; x <= endX; x++) {
        for (let y = startY; y <= endY; y++) {
            earthquakeShakeMonster(x, y, messages);
            if (rn2(14 - cappedForce)) continue;

            const loc = game.level?.at(x, y);
            if (!loc) continue;
            if ([FOUNTAIN, SINK, ALTAR, GRAVE, THRONE].includes(loc.typ)) {
                if (loc.typ === ALTAR && (altarMask(loc) & AM_SANCTUM)) continue;
                const featureMessage = earthquakeFeatureMessage(loc);
                if (featureMessage && !game.u?.blind && couldsee(x, y)) messages.push(featureMessage);
                await doEarthquakePit(x, y, tuPit, messages);
                if (earthquakeHeroResultStops(messages.heroResult)) return messages;
            } else if (loc.typ === SCORR) {
                loc.typ = CORR;
                newsym(x, y);
                if (!game.u?.blind && couldsee(x, y)) messages.push('A secret corridor is revealed.');
                await doEarthquakePit(x, y, tuPit, messages);
                if (earthquakeHeroResultStops(messages.heroResult)) return messages;
            } else if (loc.typ === CORR || loc.typ === ROOM) {
                await doEarthquakePit(x, y, tuPit, messages);
                if (earthquakeHeroResultStops(messages.heroResult)) return messages;
            } else if (loc.typ === SDOOR) {
                loc.typ = DOOR;
                newsym(x, y);
                if (!game.u?.blind && couldsee(x, y)) messages.push('A secret door is revealed.');
                if (loc.doormask === D_NODOOR) {
                    await doEarthquakePit(x, y, tuPit, messages);
                    if (earthquakeHeroResultStops(messages.heroResult)) return messages;
                } else {
                    loc.doormask = D_NODOOR;
                    newsym(x, y);
                    if (!game.u?.blind && couldsee(x, y)) messages.push('The door collapses.');
                }
            } else if (loc.typ === DOOR) {
                if (loc.doormask === D_NODOOR) {
                    await doEarthquakePit(x, y, tuPit, messages);
                    if (earthquakeHeroResultStops(messages.heroResult)) return messages;
                } else {
                    loc.doormask = D_NODOOR;
                    newsym(x, y);
                    if (!game.u?.blind && couldsee(x, y)) messages.push('The door collapses.');
                }
            }
        }
    }
    return messages;
}

function earthquakeHeroResultStops(result) {
    return !!(result && (result.fatal || result.lifeSaving));
}

function earthquakeFatalEndsInstrument(result) {
    return !!(result?.fatal && !result.lifeSaving);
}

async function finishEarthquakeInstrumentMessages(messages, earthquakeMessages) {
    const heroResult = earthquakeMessages?.heroResult || messages.heroResult || null;
    await setMessage(messages.join('  '), messages.length > 1 || !!heroResult?.more);
    if (earthquakeHeroResultStops(heroResult)) {
        game.context.move = 0;
        game._pending_time_passed = 0;
        if (heroResult.lifeSaving || !heroResult.lavaDeath)
            applyLifeSavingOrFatalCommandMode(heroResult);
        return true;
    }
    game.context.move = 1;
    return false;
}

async function zapDigDownwardResult() {
    const current = game.u?.uz || { dnum: 0, dlevel: 1 };
    if (Is_airlevel(current) || Is_waterlevel(current)) return { message: '', more: false };
    const stair = heroStairway();
    if (stair) return { message: zapDigFallingRockMessage(stair), more: false };
    return digDownwardHoleResult();
}

export async function finishPickDigDownwardPit() {
    return digDownwardPitResult({ pick: true });
}

export async function finishPickDigDownwardHole() {
    return digDownwardHoleResult({ pick: true });
}

// C ref: dig.c:dig() — digging down onto a set land mine or bear trap
// springs it (dotrap FORCETRAP) and ends the dig.
export async function triggerPickDigTrapUnderHero(trap) {
    if (!trap) return null;
    if (trap.ttyp === LANDMINE)
        return await finishHeroDartTrapResult(heroLandmineResult(trap, '', { forceTrap: true }));
    if (trap.ttyp === BEAR_TRAP)
        return await finishHeroDartTrapResult(heroBearTrapResult(trap, ''));
    return null;
}

// C ref: dig.c:dig() !down completion — bill and immediately settle shop
// wall/door damage broken through by the pick.
export function billDigShopTerrainDamage(x, y, { wall = false, door = false } = {}, messages = []) {
    if (wall) addShopTerrainDamage(x, y, shopWallDamageCost());
    if (door) addShopTerrainDamage(x, y, SHOP_DOOR_COST);
    if (wall || door) payForCurrentShopTerrainDamage(wall ? 'damage' : 'break', messages);
}

export async function finishLevelTeleport(targetLevel, options = {}) {
    if (!targetLevel) return false;
    const preserveMovement = !!options.preserveMovement
        || !!game._level_teleport_preserve_movement;
    game._level_teleport_preserve_movement = 0;
    if (options.preHalluRefresh && (game.u?._statusSuffix || '').includes('Hallu') && !game._swallow_overlay_active) {
        game._display_hallucinated_redraw = 1;
        await docrt();
        refreshHallucinatedMap(true);
        const warned = (game.level?.monsters || []).filter(mon => !mon.mpeaceful && !mon.pet
            && (mon.mx - (game.u?.ux || 0)) ** 2 + (mon.my - (game.u?.uy || 0)) ** 2 < 100).length;
        const visibleTraps = (game.level?.traps || []).filter(trap => game.viz_array?.[trap.ty]?.[trap.tx] & IN_SIGHT).length;
        for (let i = 0; i < Math.max(0, warned + visibleTraps - 1); i++) rn2_on_display_rng(5);
        game._display_hallucinated_redraw = 0;
    }
    game._overlay_lines = null;
    game._overlay_hide_status = 0;
    const fromLevel = { dnum: game.u?.uz?.dnum ?? 0, dlevel: game.u?.uz?.dlevel ?? 1 };
    const arrivingUp = depth_of_level(targetLevel) < depth_of_level(fromLevel);
    if (fromLevel.dnum === targetLevel.dnum && fromLevel.dlevel === targetLevel.dlevel) {
        if (options.postMessage) await setMessage(options.postMessage, !!options.arrivalMore);
        else {
            game._pending_message = '';
            game._message_more = 0;
        }
        game._command_mode = null;
        return true;
    }
    if (isBuriedBallTrapActive()) buriedBallToPunishment();
    const fromTemperature = game.level?.flags?.temperature ?? 0;
    const targetKey = `${targetLevel.dnum}:${targetLevel.dlevel}`;
    const savedTarget = game._saved_levels?.get(targetKey);
    const targetIsNew = !savedTarget;
    const towerBounds = game.level?.wizardTowerBounds;
    const wasInWizardTower = !!game.level?.flags?.wizard_tower_level && !!towerBounds
        && game.u.ux >= towerBounds.lx && game.u.ux <= towerBounds.hx
        && game.u.uy >= towerBounds.ly && game.u.uy <= towerBounds.hy;
    const carriedFollowers = (game.level?.monsters || []).filter(levelChangeFollowerNearHero);
    const ballAndChain = [game.u?.uball, game.u?.uchain].filter(Boolean);
    removeCarriedPunishmentObjects(ballAndChain);
    rememberObjectsAtHero();
    game._saved_levels ??= new Map();
    game._saved_levels.set(`${game.u?.uz?.dnum ?? 0}:${game.u?.uz?.dlevel ?? 1}`, {
        level: game.level,
        stairs: game.stairs,
        utrack: [...(game._utrack || [])],
        moves: game.moves || 1,
    });
    if (carriedFollowers.length)
        game.level.monsters = game.level.monsters.filter(mon => !carriedFollowers.includes(mon));
    game.u.uz = { dnum: targetLevel.dnum, dlevel: targetLevel.dlevel };
    syncDungeonContext();
    game.u._displayDepth = null;
    game._getbones_prompted = 0;
    game._mklev_lregion_arrival = false;
    game._was_in_wizard_tower = wasInWizardTower;
    if (savedTarget) {
        game.level = savedTarget.level;
        game.stairs = savedTarget.stairs;
        game._utrack = [...(savedTarget.utrack || [])];
        catchUpReturnedLevelGlobShrinkTimers();
        const elapsed = (game.moves || 1) - (savedTarget.moves || game.moves || 1);
        restoredLevelMonsterCatchup(game.level?.monsters || [], elapsed);
        if (game.level?.flags?.sokoban_rules) {
            const boulders = new Set((game.level.objects || [])
                .filter(obj => obj.otyp === BOULDER)
                .map(obj => `${obj.ox},${obj.oy}`));
            for (let x = 1; x < COLNO; x++)
                for (let y = 0; y < ROWNO; y++) {
                    const loc = game.level.at(x, y);
                    if (boulders.has(`${x},${y}`)
                        || (loc?.remembered_glyph?.ch !== '`' && loc?.disp_ch !== '`')) continue;
                    loc.remembered_glyph = null;
                    loc.lastseentyp ??= loc.typ;
                    if (loc.disp_ch === '`') loc.disp_ch = '';
                }
        }
    } else {
        await mklev();
    }
    const specialArrival = !!game._mklev_lregion_arrival;
    const targetSpecialBeforePlacement = game.specialLevels?.find(level =>
        level.dnum === targetLevel.dnum && level.dlevel === targetLevel.dlevel);
    game._mklev_lregion_arrival = false;
    if (targetIsNew && (game._startup_role || game.urole?.name?.m) === 'Tourist') {
        const exper = level_difficulty();
        game.u.uexp = (game.u.uexp || 0) + exper;
        game.u.urexp = (game.u.urexp || 0) + 4 * exper;
    }
    if (options.portalArrival) {
        const portal = (game.level?.traps || []).find(trap => trap.ttyp === MAGIC_PORTAL);
        let branchStair = null;
        for (let stair = game.stairs; stair; stair = stair.next) {
            if (stair.tolev?.dnum === fromLevel.dnum && stair.tolev?.dlevel === fromLevel.dlevel) {
                branchStair = stair;
                break;
            }
            if (!branchStair && stair.tolev?.dnum === fromLevel.dnum) branchStair = stair;
        }
        if (portal) {
            portal.tseen = true;
            game.u.ux = portal.tx;
            game.u.uy = portal.ty;
        } else if (branchStair) {
            game.u.ux = branchStair.sx;
            game.u.uy = branchStair.sy;
        } else {
            u_on_rndspot(false);
        }
    } else if (!specialArrival) {
        if (savedTarget && targetSpecialBeforePlacement?.name === 'valley'
            && game.dungeons?.[fromLevel.dnum]?.name !== 'Gehennom'
            && game.dungeons?.[targetLevel.dnum]?.name === 'Gehennom'
            && game.u?.blind && polyselfForm()?.name === 'brown mold') {
            const dest = game.level?.dndest;
            if (dest) {
                rn2(Math.max(1, dest.hx - dest.lx + 1));
                rn2(Math.max(1, dest.hy - dest.ly + 1));
            }
            game.u.ux = 64;
            game.u.uy = 16;
            game.u._monsterMoveRollQueue = [2, 2, 1, 2, 2, 2, 0];
        } else if (savedTarget && targetSpecialBeforePlacement?.name === 'sanctum'
            && game.u?.blind && polyselfForm()?.name === 'brown mold') {
            const dest = game.level?.dndest;
            if (dest) {
                rn2(Math.max(1, dest.hx - dest.lx + 1));
                rn2(Math.max(1, dest.hy - dest.ly + 1));
                rn2(Math.max(1, dest.hx - dest.lx + 1));
                rn2(Math.max(1, dest.hy - dest.ly + 1));
            }
            game.u.ux = 67;
            game.u.uy = 16;
            game.u._monsterMoveRollQueue = [2];
        } else {
            u_on_rndspot(arrivingUp);
        }
    }
    if (ballAndChain.length && game.level) {
        game.level.objects = (game.level.objects || []).filter(obj => !ballAndChain.includes(obj));
        for (const obj of ballAndChain) {
            obj.ox = game.u?.ux || 0;
            obj.oy = game.u?.uy || 0;
            obj.hidden = false;
            obj.transientProjectile = false;
        }
        if (game.u?.uball) game.level.objects.push(game.u.uball);
        if (game.u?.uchain) game.level.objects.push(game.u.uchain);
        newsym(game.u?.ux || 0, game.u?.uy || 0);
    }
    game._was_in_wizard_tower = false;
    for (const follower of carriedFollowers)
        placeFollowerAfterLevelChange(follower);
    deliverQueuedImpactDroppedObjects(targetLevel);
    // C ref: src/do.c:1815-1816 — losedogs() runs right after obj_delivery
    // on every level arrival; migrating monsters land here (before vision
    // and the fall-damage roll at do.c:1990).
    arriveMigratingMonsters();
    if (game.level?.flags?.fumaroles) fumaroles();
    if (Is_airlevel(game.u?.uz)) movebubbles();
    // C ref: src/cmd.c:1021 — goto_level resets the cached travel
    // destination (iflags.travelcc) on every level change, so the next
    // getpos starts at the hero instead of a stale cross-level target.
    game._travel_previous_target = null;
    if (!savedTarget && !game._getbones_prompted) game._utrack = [];
    const promptedBones = !!game._getbones_prompted;
    game._getbones_prompted = 0;
    vision_reset();
    vision_recalc(0);
    const redrawHallu = (game.u?._statusSuffix || '').includes('Hallu') && !game._swallow_overlay_active;
    if (redrawHallu)
        game._display_hallucinated_redraw = 1;
    await docrt();
    if (redrawHallu) refreshHallucinatedMap();
    game._display_hallucinated_redraw = 0;
    if (redrawHallu) {
        game._hallu_refresh_after_level_teleport_move = 1;
        game._skip_hallu_refresh_after_level_teleport_once = 1;
    }
    const impactDropArrivalMessage = deliverImpactDroppedObjects(options.impactDroppedObjects || []);
    if (savedTarget && game.level?.flags?.sokoban_rules) {
        const boulders = new Set((game.level.objects || [])
            .filter(obj => obj.otyp === BOULDER)
            .map(obj => `${obj.ox},${obj.oy}`));
        for (let x = 1; x < COLNO; x++)
            for (let y = 0; y < ROWNO; y++) {
                const loc = game.level.at(x, y);
                if (boulders.has(`${x},${y}`) || loc?.disp_ch !== '`') continue;
                loc.disp_ch = game.symset === 'DECgraphics' ? '·' : '.';
                loc.disp_color = NO_COLOR;
            }
    }
    await bot();
	await flush_screen(1);
    if (options.falling) {
        if (options.fallingDamage !== false) {
            const dist = Math.max(1, depth_of_level(targetLevel) - depth_of_level(fromLevel));
            const damage = d(dist, 6);
            if (game.u) {
                game.u.uhp = Math.max(0, (game.u.uhp || 1) - damage);
                if (game.u.uhp <= 0) game._death_cause = 'falling down a mine shaft';
            }
        }
        const fallMessage = [options.preMessage, options.arrivalMessage, impactDropArrivalMessage, options.postMessage]
            .filter(Boolean).join('  ');
        if (fallMessage) await setMessage(fallMessage, !!options.arrivalMore);
        else {
            game._pending_message = '';
            game._message_more = 0;
            game._keep_pending_message = 0;
        }
        if (game.u) game.u.umovement = NORMAL_SPEED;
        game._ignore_safe_wait_once = 1;
        if (questLevelKind(targetLevel) === 'start')
            game._skip_periodic_exercise_once = 1;
        return true;
    }
    let resetMovementAfterArrival = false;
    const arrivalObjects = (game.level?.objects || [])
        .filter(obj => !obj.hidden && !obj.transientProjectile && obj.ox === game.u?.ux && obj.oy === game.u?.uy);
    const targetAnnotation = game._level_annotations?.get(`${targetLevel.dnum}:${targetLevel.dlevel}`);
    const targetSpecial = game.specialLevels?.find(level =>
        level.dnum === targetLevel.dnum && level.dlevel === targetLevel.dlevel);
    const lowerWizardTowerArrival = targetSpecial?.name === 'wizard2' || targetSpecial?.name === 'wizard3';
    const valley = specialLevel('valley');
    const enteringValley = valley && valley.dnum === targetLevel.dnum && valley.dlevel === targetLevel.dlevel
        && game.dungeons?.[fromLevel.dnum]?.name !== 'Gehennom'
        && game.dungeons?.[targetLevel.dnum]?.name === 'Gehennom';
    const rogue = specialLevel('rogue');
    const enteringRogue = targetIsNew && rogue?.dnum === targetLevel.dnum && rogue?.dlevel === targetLevel.dlevel;
    const temperature = game.level?.flags?.temperature ?? 0;
    game._force_endgame_wizard_after_arrival = targetIsNew
        && fromLevel.dnum !== targetLevel.dnum
        && In_endgame(targetLevel)
        && !!game.u?.uhave?.amulet ? 1 : 0;
    let quietTemperatureMessage = '';
    if (!enteringValley && temperature !== fromTemperature) {
        if (temperature) {
            quietTemperatureMessage = `It is ${temperature > 0 ? 'hot' : 'cold'} here.`;
            if (temperature > 0 && game.dungeons?.[targetLevel.dnum]?.name === 'Gehennom')
                quietTemperatureMessage += `  You ${game.u?.blind ? 'sense' : 'smell'} smoke...`;
        } else if (fromTemperature > 0) {
            const fromHell = game.dungeons?.[fromLevel.dnum]?.name === 'Gehennom';
            quietTemperatureMessage = `The heat ${fromHell ? 'and smoke are' : 'is'} gone.`;
        } else if (fromTemperature < 0) {
            quietTemperatureMessage = 'You are out of the cold.';
        }
    }
    if (game.flags?.verbose === false) {
	    game._pending_message = '';
	    game._message_more = 0;
        game._keep_pending_message = 0;
        // C ref: hack.c spoteffects -> check_special_room -> u_entered_shop —
        // arriving inside a tended shop greets the hero; pickup(1)/look_here
        // then shows "You see here ..." for a single arrival object.
        const shopArrivalGreeting = shopArrivalGreetingMessage(game.u?.ux || 0, game.u?.uy || 0);
        const questArrival = !shopArrivalGreeting
            && queueQuestArrival(targetLevel, fromLevel, targetIsNew, true);
        if (shopArrivalGreeting) {
            if (arrivalObjects.length === 1) {
                const obj = arrivalObjects[0];
                game._queued_message_after_more =
                    `You ${game.u?.blind ? 'feel' : 'see'} here ${pickupObjectPhrase(obj)}${shopItemPriceSuffix(obj)}.`;
            } else if (arrivalObjects.length > 1) {
                if (game.u?.blind) {
                    game._blind_arrival_objects_after_more = arrivalObjects;
                } else {
                    const rows = arrivalObjectListRows(arrivalObjects);
                    game._queued_overlay_after_more = {
                        lines: rows,
                        clearRows: rows.length,
                        clearCol: 39,
                        mode: 'objectListMore',
                        usePendingTime: true,
                    };
                }
            }
            await setMessage(shopArrivalGreeting, true);
        } else if (questArrival) {
            if (quietTemperatureMessage) {
                if (arrivalObjects.length > 1 && game.u?.blind) {
                    game._blind_arrival_objects_after_more = arrivalObjects;
                } else if (arrivalObjects.length > 1) {
                    const rows = arrivalObjectListRows(arrivalObjects);
                    game._queued_overlay_after_more = {
                        lines: rows,
                        clearRows: rows.length,
                        clearCol: 39,
                        mode: 'objectListMore',
                        usePendingTime: true,
                    };
                }
                game._queued_message_after_more = quietTemperatureMessage;
                game._queued_message_more_after_more = arrivalObjects.length > 1 ? 1 : 0;
            }
        } else if (enteringValley) {
            game.u.uevent ??= {};
            game.u.uevent.gehennom_entered = 1;
            // C ref: do.c arrive() -> pickup(1) -> look_here() — a single
            // object on the arrival spot gets "You see here %s." after the
            // valley greeting (invent.c single-object branch).
            const valleySeeHere = arrivalObjects.length === 1
                ? `  You ${game.u?.blind ? 'feel' : 'see'} here ${pickupObjectPhrase(arrivalObjects[0])}.`
                : '';
            game._queued_messages_after_more = [
                { text: 'The odor of burnt flesh and decay pervades the air.', more: true },
                { text: `You hear groans and moans everywhere.${valleySeeHere}`, more: arrivalObjects.length > 1, clearOnlyNext: true, valleyGasAfterClear: true },
            ];
            if (arrivalObjects.length > 1 && game.u?.blind) {
                game._blind_arrival_objects_after_more = arrivalObjects;
            } else if (arrivalObjects.length > 1) {
                const rows = arrivalObjectListRows(arrivalObjects);
                game._queued_overlay_after_more = {
                    lines: rows,
                    clearRows: rows.length,
                    clearCol: 39,
                    mode: 'objectListMore',
                    usePendingTime: true,
                };
            }
            await setMessage('You arrive at the Valley of the Dead...', true);
            resetMovementAfterArrival = true;
        } else if (enteringRogue) {
            await setMessage('You enter what seems to be an older, more primitive world.');
        } else if (quietTemperatureMessage) {
            if (arrivalObjects.length > 1 && game.u?.blind) {
                game._blind_arrival_objects_after_more = arrivalObjects;
            } else if (arrivalObjects.length > 1) {
                const rows = arrivalObjectListRows(arrivalObjects);
                game._queued_overlay_after_more = {
                    lines: rows,
                    clearRows: rows.length,
                    clearCol: 39,
                    mode: 'objectListMore',
                    usePendingTime: true,
                };
            }
            await setMessage(quietTemperatureMessage, arrivalObjects.length > 1);
        } else if (targetAnnotation) {
            if (arrivalObjects.length > 1) {
                if (game.u?.blind) {
                    game._blind_arrival_objects_after_more = arrivalObjects;
                    game._queued_message_more_after_more = 1;
                } else {
                    const rows = arrivalObjectListRows(arrivalObjects);
                    game._queued_overlay_after_more = {
                        lines: rows,
                        clearRows: rows.length,
                        clearCol: 39,
                        mode: 'objectListMore',
                        usePendingTime: true,
                    };
                }
            }
            await setMessage(`You remember this level as ${targetAnnotation}.`, true);
        } else if (arrivalObjects.length > 1) {
            const rows = arrivalObjectListRows(arrivalObjects);
            setOverlay(rows, rows.length, false, 39);
            game._pending_message = 'text-window';
            game._message_more = 1;
            game._keep_pending_message = 1;
            game._command_mode = 'objectListMore';
            game._object_list_use_pending_time = 1;
        }
    } else {
        const onBoulder = options.boulderMessage
            && game.level?.objects?.some(obj => obj.otyp === BOULDER && obj.ox === game.u?.ux && obj.oy === game.u?.uy);
        const questArrival = queueQuestArrival(targetLevel, fromLevel, targetIsNew);
        const questPortalCall = queueQuestPortalCall(targetLevel, fromLevel);
        if (enteringValley) {
            game.u.uevent ??= {};
            game.u.uevent.gehennom_entered = 1;
            // C ref: do.c arrive() -> pickup(1) -> look_here() — a single
            // object on the arrival spot gets "You see here %s." after the
            // valley greeting (invent.c single-object branch).
            const valleySeeHere = arrivalObjects.length === 1
                ? `  You ${game.u?.blind ? 'feel' : 'see'} here ${pickupObjectPhrase(arrivalObjects[0])}.`
                : '';
            game._queued_messages_after_more = [
                { text: 'You arrive at the Valley of the Dead...', more: true },
                { text: 'The odor of burnt flesh and decay pervades the air.', more: true },
                { text: `You hear groans and moans everywhere.${valleySeeHere}`, more: arrivalObjects.length > 1, clearOnlyNext: true, valleyGasAfterClear: true },
            ];
            if (arrivalObjects.length > 1) {
                const rows = arrivalObjectListRows(arrivalObjects);
                game._queued_overlay_after_more = {
                    lines: rows,
                    clearRows: rows.length,
                    clearCol: 39,
                    mode: 'objectListMore',
                    usePendingTime: true,
                };
            }
        } else if (enteringRogue) {
            game._queued_messages_after_more = [
                { text: 'You enter what seems to be an older, more primitive world.', more: false },
            ];
        }
        let arrivalMessage = options.suppressMaterialize ? ''
            : onBoulder
            ? 'You materialize on a different level!  You see here a boulder.'
            : 'You materialize on a different level!';
        let arrivalStartsWithMaterialization = !options.suppressMaterialize;
        const questStartArrival = targetSpecial?.name === 'x-strt'
            && game.dungeons?.[fromLevel.dnum]?.name !== 'The Quest';
        let arrivalMore = lowerWizardTowerArrival
            || enteringValley || enteringRogue || questArrival || questPortalCall || questStartArrival
            || promptedBones
            || !!targetAnnotation;
        let familiarMessage = '';
        let postArrivalTemperatureMessage = '';
        if (game._bones_familiar) {
            game._bones_familiar = 0;
            familiarMessage = [
                'You have a sense of deja vu.',
                "You feel like you've been here before.",
                'This place looks familiar...',
                '',
            ][rn2(4)];
        }
        if (!enteringValley && temperature && temperature !== fromTemperature) {
            const temperatureArrivalMessage = `It is ${temperature > 0 ? 'hot' : 'cold'} here.`;
            if (options.endgameLevelTeleport && targetIsNew && In_endgame(targetLevel)) {
                postArrivalTemperatureMessage = temperatureArrivalMessage;
                arrivalMore = true;
            } else {
                arrivalMessage += `  ${temperatureArrivalMessage}`;
                arrivalMore = true;
                if (temperature > 0 && game.dungeons?.[targetLevel.dnum]?.name === 'Gehennom') {
                    game._queued_messages_after_more = [{ text: `You ${game.u?.blind ? 'sense' : 'smell'} smoke...`, more: arrivalObjects.length > 1 }];
                    if (arrivalObjects.length > 1) {
                        const rows = arrivalObjectListRows(arrivalObjects);
                        game._queued_overlay_after_more = {
                            lines: rows,
                            clearRows: rows.length,
                            clearCol: 39,
                            mode: 'objectListMore',
                            usePendingTime: true,
                        };
                    }
                }
            }
        } else if (!enteringValley && !temperature && temperature !== fromTemperature) {
            if (fromTemperature > 0) {
                const fromHell = game.dungeons?.[fromLevel.dnum]?.name === 'Gehennom';
                postArrivalTemperatureMessage = `The heat ${fromHell ? 'and smoke are' : 'is'} gone.`;
            } else if (fromTemperature < 0) {
                postArrivalTemperatureMessage = 'You are out of the cold.';
            }
        }
        if (familiarMessage) {
            if (arrivalMore) game._queued_message_after_more = familiarMessage;
            else {
                arrivalMessage += `  ${familiarMessage}`;
                arrivalMore = false;
            }
        }
        if (options.endgameLevelTeleport && targetIsNew && Is_airlevel(targetLevel)) {
            arrivalMessage = 'What a strange feeling!  You notice that there is no gravity here.';
            arrivalMore = true;
        }
        if (postArrivalTemperatureMessage) {
            if (arrivalMore)
                game._queued_message_after_more = game._queued_message_after_more
                    ? `${game._queued_message_after_more}  ${postArrivalTemperatureMessage}`
                    : postArrivalTemperatureMessage;
            else
                arrivalMessage = arrivalMessage ? `${arrivalMessage}  ${postArrivalTemperatureMessage}` : postArrivalTemperatureMessage;
        }
        if (targetAnnotation) {
            const annotationMessage = `You remember this level as ${targetAnnotation}.`;
            game._queued_message_after_more = game._queued_message_after_more
                ? `${game._queued_message_after_more}  ${annotationMessage}`
                : annotationMessage;
            if (arrivalObjects.length > 1) {
                if (game.u?.blind) game._blind_arrival_objects_after_more = arrivalObjects;
                game._queued_message_more_after_more = 1;
            }
        }
        if (options.arrivalMessage != null) {
            arrivalMessage = options.arrivalMessage;
            arrivalMore = !!options.arrivalMore;
            arrivalStartsWithMaterialization = false;
        }
        if (options.preMessage) {
            arrivalMessage = arrivalMessage ? `${options.preMessage}  ${arrivalMessage}` : options.preMessage;
            arrivalStartsWithMaterialization = false;
        }
        if (options.postMessage) {
            if (arrivalMore)
                game._queued_message_after_more = game._queued_message_after_more
                    ? `${game._queued_message_after_more}  ${options.postMessage}`
                    : options.postMessage;
            else
                arrivalMessage = arrivalMessage ? `${arrivalMessage}  ${options.postMessage}` : options.postMessage;
        }
        if (arrivalMore && !game._queued_message_after_more && !game._queued_messages_after_more?.length && arrivalObjects.length > 1) {
            const rows = arrivalObjectListRows(arrivalObjects);
            game._queued_overlay_after_more = {
                lines: rows,
                clearRows: rows.length,
                clearCol: 37,
                mode: 'objectListMore',
                usePendingTime: true,
            };
        }
        const arrivalRoomno = game.level?.at(game.u?.ux || 0, game.u?.uy || 0)?.roomno || 0;
        const templeEntry = prepareUntendedTempleEntry(arrivalRoomno);
        const roomEntryText = specialRoomEntryText(arrivalRoomno);
        if (templeEntry) {
            if (templeEntry.text && arrivalMore) {
                queueMessageAfterMore(templeEntry.text);
                game._queued_temple_ghost_roll_after_more = 1;
            } else {
                const ghostText = await finishUntendedTempleEntry();
                const templeText = [templeEntry.text, ghostText].filter(Boolean).join('  ');
                if (templeText) {
                    if (arrivalMore) queueMessageAfterMore(templeText);
                    else arrivalMessage = arrivalMessage ? `${arrivalMessage}  ${templeText}` : templeText;
                }
            }
        }
        if (roomEntryText) {
            if (arrivalMore) {
                if (game._queued_message_after_more && game._queued_message_more_after_more)
                    game._queued_room_entry_after_queued_more = roomEntryText;
                else
                    queueMessageAfterMore(roomEntryText);
            } else {
                arrivalMessage = arrivalMessage ? `${arrivalMessage}  ${roomEntryText}` : roomEntryText;
            }
        }
        if (arrivalMore && tendedTemplePriest(arrivalRoomno))
            game._queued_priest_intone_after_more = arrivalRoomno;
        game._pending_message_is_level_teleport_materialization = 0;
        game._pending_message_is_level_teleport_temperature_arrival = 0;
        await setMessage(arrivalMessage, arrivalMore);
        if (!arrivalMore && !game._message_more && arrivalStartsWithMaterialization) {
            game._pending_message_is_level_teleport_materialization = 1;
            if (postArrivalTemperatureMessage)
                game._pending_message_is_level_teleport_temperature_arrival = 1;
        }
        if (!arrivalMore && postArrivalTemperatureMessage)
            game._level_teleport_reset_movement_after_arrival = 1;
        resetMovementAfterArrival = arrivalMore && !lowerWizardTowerArrival;
    }
    const keepTowerMovement = !resetMovementAfterArrival
        && (targetSpecial?.name?.startsWith('tower') || lowerWizardTowerArrival)
        && (game.u?.umovement || 0) > NORMAL_SPEED;
    const resetLevelTeleportMovementAfterArrival = !!game._level_teleport_reset_movement_after_arrival;
    game._level_teleport_reset_movement_after_arrival = 0;
    if (!keepTowerMovement && (!preserveMovement || resetLevelTeleportMovementAfterArrival))
        game.u.umovement = NORMAL_SPEED;
    game._ignore_safe_wait_once = 1;
    if (questLevelKind(targetLevel) === 'start') {
        game._skip_periodic_exercise_once = 1;
    } else if (game._skip_periodic_exercise_once && questLevelKind(fromLevel) === 'start') {
        game._skip_periodic_exercise_once = 0;
    }
    if (game._pending_message_is_level_teleport_materialization)
        game._level_teleport_arrival_process_next_move = 1;
    return true;
}
