function armorDisplayColor(item) {
    const kind = String(item?.actualKind || item?.kind || '').toLowerCase();
    const armorAppearance = ARMOR_WISH_APPEARANCES[kind];
    if (armorAppearance) {
        const [group, index] = armorAppearance;
        const colorGroup = ARMOR_APPEARANCE_COLOR_GROUPS[group];
        const shuffledColor = colorGroup ? game._object_descriptions?.[colorGroup]?.[index] : undefined;
        if (shuffledColor != null) return shuffledColor;
    }
    return ARMOR_KIND_DISPLAY_COLORS[kind] ?? NO_COLOR;
}
function pairArmorDiscoveryName(name) {
    return /(?:boots|shoes|gloves)$/.test(name) || name.startsWith('gauntlets')
        ? `pair of ${name}` : name;
}
function recordKnownArmorDiscovery(kind, starred = false) {
    const name = String(kind || '').toLowerCase();
    const armorAppearance = ARMOR_WISH_APPEARANCES[name];
    if (!armorAppearance) return;
    const [group, index, fallback] = armorAppearance;
    const appearance = group ? game._object_descriptions?.[group]?.[index] || fallback : fallback;
    const discoveryName = pairArmorDiscoveryName(name);
    const text = appearance ? `${discoveryName} (${appearance})` : discoveryName;
    game._discoveries ??= [];
    const existing = game._discoveries.find(entry => entry.section === 'Armor' && entry.name === discoveryName);
    if (existing) {
        existing.text = text;
        if (!starred) existing.starred = false;
        return;
    }
    game._discoveries.push({ section: 'Armor', name: discoveryName, text, starred });
}

function recordKnownAmuletDiscovery(kind, item = null) {
    const name = String(kind || '').toLowerCase();
    const amuletIndex = item?.amuletIndex ?? IDENTIFIED_AMULET_NAMES.indexOf(name);
    const appearance = item?.appearance || game._object_descriptions?.amulets?.[amuletIndex] || '';
    const text = appearance ? `${name} (${appearance})` : name;
    game._discoveries ??= [];
    const existing = game._discoveries.find(entry => entry.section === 'Amulets' && entry.name === name);
    if (existing) {
        existing.text = text;
        existing.starred = false;
        existing.known = true;
        return;
    }
    game._discoveries.push({ section: 'Amulets', name, text, starred: false, known: true });
}

function recordKnownRingDiscovery(kind, item = null) {
    const raw = String(kind || '').toLowerCase().replace(/^ring of /, '');
    if (!raw) return;
    const ringIndex = item?.ringRoll != null ? item.ringRoll - 1 : IDENTIFIED_RING_NAMES.indexOf(raw);
    const appearance = item?.appearance || game._object_descriptions?.rings?.[ringIndex] || '';
    const name = `ring of ${raw}`;
    const text = appearance ? `${name} (${appearance})` : name;
    game._discoveries ??= [];
    const existing = game._discoveries.find(entry => entry.section === 'Rings' && entry.name === name);
    if (existing) {
        existing.text = text;
        existing.starred = false;
        existing.known = true;
        return;
    }
    game._discoveries.push({ section: 'Rings', name, text, starred: false, known: true });
}
