function setFullOptionsPage(page) {
    game._options_full_page = page;
    setOverlay(fullOptionsPageLines(page), 24, true);
    game._command_mode = 'optionsFull';
}

function applyFullOptionChanges(changes) {
    game.flags = game.flags || {};
    const applied = new Set(game._options_full_applied_ids || []);
    for (const change of changes || []) {
        if (applied.has(change.id)) continue;
        if (change.id === 'autopickup') {
            game._autopickup = change.after;
            game.flags.pickup = change.after;
        } else if (change.id === 'hilite_pet') {
            game._hilite_pet = change.after;
        } else if (change.id === 'hilite_pile') {
            game._hilite_pile = change.after;
        } else {
            game.flags[change.id] = change.after;
        }
        applied.add(change.id);
    }
    game._options_full_applied_ids = [...applied];
}

function autopickupTypesLines(picks = game._autopickup_type_picks || []) {
    const selected = new Set(picks);
    const col = game._autopickup ? 25 : 17;
    const pick = key => selected.has(key) ? '+' : '-';
    const toggleLine = game._autopickup
        ? "Toggle off 'autopickup' to not pick up anything."
        : "Toggle on 'autopickup' to automatically pick these things up.";
    return [
        [0, col, 'Autopickup what?', 1],
        [2, col, `a ${pick('$')} $  pile of coins`],
        [3, col, `b ${pick('"')} "  amulet`],
        [4, col, 'c - )  weapon'],
        [5, col, 'd - [  suit or piece of armor'],
        [6, col, 'e - %  piece of food'],
        [7, col, `f ${pick('?')} ?  scroll`],
        [8, col, `g ${pick('+')} +  spellbook`],
        [9, col, `h ${pick('!')} !  potion`],
        [10, col, `i ${pick('=')} =  ring`],
        [11, col, `j ${pick('/')} /  wand`],
        [12, col, 'k - (  useful item (pick-axe, key, lamp...)'],
        [13, col, 'l - *  gem or rock'],
        [14, col, 'm - `  boulder or statue'],
        [15, col, 'n - 0  iron ball'],
        [16, col, 'o - _  iron chain'],
        [18, col, 'A -    All classes of objects'],
        [19, col, 'Note: when no choices are selected, "all" is implied.'],
        [20, col, toggleLine],
        [21, col, '(end)'],
    ];
}
