function eatingPrompt() {
    const letters = inventoryLetters(heroInventoryEatCandidate);
    const contiguous = [...letters].every((ch, i) => !i || ch.charCodeAt(0) === letters.charCodeAt(i - 1) + 1);
    const display = contiguous && letters.length > 5 ? `${letters[0]}-${letters[letters.length - 1]}` : letters;
    return `What do you want to eat? [${display || '-'} or ?*]`;
}

function wizardRandomSpellProfile() {
    const spell = (game.inventory || [])
        .find(item => item.cls === 'spellbook' && item.spell)
        ?.spell;
    if (spell?.skill === 'divination' && spell?.level === 3) return 'clairvoyance';
    if (spell?.skill === 'enchantment' && spell?.level === 2) return 'slowMonster';
    if (spell?.skill === 'cleric' && spell?.level === 2) return 'createMonster';
    return 'default';
}

function inventoryLetters(match) {
    return (game.inventory || [])
        .filter(match)
        .map(item => item.letter)
        .filter(Boolean)
        .join('');
}

function inventoryLetterMenu(letters) {
    const runs = [];
    let i = 0;
    while (i < letters.length) {
        let j = i;
        while (j + 1 < letters.length && letters.charCodeAt(j + 1) === letters.charCodeAt(j) + 1) j++;
        runs.push(j - i >= 2 ? `${letters[i]}-${letters[j]}` : letters.slice(i, j + 1));
        i = j + 1;
    }
    return runs.join('');
}

function erosionPrefix(item) {
    const profile = wishedDamageProfile(item);
    const pieces = [];
    if (item.greased) pieces.push('greased');
    const primary = Math.min(3, item.oeroded || 0);
    const secondary = Math.min(3, item.oeroded2 || 0);
    if (primary && profile.primaryWord)
        pieces.push(`${primary === 2 ? 'very ' : primary === 3 ? 'thoroughly ' : ''}${profile.primaryWord}`);
    if (secondary && profile.secondaryWord)
        pieces.push(`${secondary === 2 ? 'very ' : secondary === 3 ? 'thoroughly ' : ''}${profile.secondaryWord}`);
    if (item.oerodeproof && profile.proofWord) pieces.push(profile.proofWord);
    return pieces.length ? `${pieces.join(' ')} ` : '';
}

function weaponLineEnchantmentPrefix(item) {
    const match = String(item?.line || '').match(/(?:^| )([+-]\d+) /);
    return match ? `${match[1]} ` : '';
}

function weaponEnchantmentPrefix(item) {
    if (item?.spe != null) {
        const spe = item.spe;
        return `${spe >= 0 ? '+' : ''}${spe} `;
    }
    return weaponLineEnchantmentPrefix(item);
}

function isWeaponDisplayObject(item) {
    const cls = itemClassKey(item);
    return cls === 'weapon' || item?.otyp === DART || item?.glyph === ')' || item?.wielded || item?.alternate;
}

function poisonedWeaponDisplayParts(item, rawName = pickupObjectName(item)) {
    if (item?.opoisoned && isPoisonableWeaponObject(item) && /^poisoned\s+/.test(rawName))
        return { poisonPrefix: 'poisoned ', name: rawName.replace(/^poisoned\s+/, '') };
    return { poisonPrefix: '', name: rawName };
}

function dipItemDescription(item, shortened = false) {
    const quan = item.quan || 1;
    let baseName = pickupObjectName(item);
    const rust = shortened ? '' : erosionPrefix(item);
    const showBuc = !shortened && item.bknown === true && !/holy water|unholy water/.test(baseName);
    const buc = showBuc
        ? item.cursed ? 'cursed ' : item.blessed ? 'blessed ' : ''
        : '';
    const worn = item.worn || item.line?.includes('being worn') ? ' (being worn)' : '';
    if (isWeaponDisplayObject(item)) {
        const parts = poisonedWeaponDisplayParts(item, baseName);
        const quantity = quan > 1 ? `${quan} ` : '';
        return `${quantity}${buc}${parts.poisonPrefix}${rust}${weaponEnchantmentPrefix(item)}${parts.name}${worn}`;
    }
    if (quan > 1)
        baseName = `${quan} ${item.plural || (baseName.endsWith('s') ? baseName : `${baseName}s`)}`;
    // C ref: doname() shows enchantment ("+0") for weapons and armor but
    // never for potions (objnam.c doname POTION_CLASS, objnam.c:832-848).
    const spe = item.spe == null || quan > 1 || isPotionObject(item) ? '' : `${item.spe >= 0 ? '+' : ''}${item.spe} `;
    return `${buc}${rust}${spe}${baseName}${worn}`;
}

function dipItemPromptParts(item) {
    let description = dipItemDescription(item);
    let article = (item.quan || 1) > 1 ? '' : `${/^[aeiou]/i.test(description) ? 'an' : 'a'} `;
    if (`${article}${description}`.length > 49) {
        description = dipItemDescription(item, true);
        article = (item.quan || 1) > 1 ? '' : `${/^[aeiou]/i.test(description) ? 'an' : 'a'} `;
    }
    return { article, description };
}

function nextToDoor(x, y) {
    for (let dy = -1; dy <= 1; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
            if (!dx && !dy) continue;
            const typ = game.level?.at(x + dx, y + dy)?.typ;
            if (typ === DOOR || typ === SDOOR) return true;
        }
    }
    return false;
}

function dogushforth() {
    const limits = [7, 7, 7, 6, 6, 5, 4, 2];
    const ux = game.u?.ux || 0;
    const uy = game.u?.uy || 0;
    let madepool = 0;
    for (let y = Math.max(0, uy - 7); y <= Math.min(ROWNO - 1, uy + 7); y++) {
        const offset = limits[Math.abs(y - uy)];
        for (let x = Math.max(1, ux - offset); x <= Math.min(COLNO - 1, ux + offset); x++) {
            if (!couldsee(x, y) || ((x + y) % 2) || (x === ux && y === uy)) continue;
            if (rn2(1 + distmin(ux, uy, x, y))) continue;
            const loc = game.level?.at(x, y);
            if (!loc || loc.typ !== ROOM) continue;
            if ((game.level?.objects || []).some(obj => obj.otyp === BOULDER && obj.ox === x && obj.oy === y)) continue;
            if (nextToDoor(x, y)) continue;
            loc.typ = POOL;
            loc.flags = 0;
            madepool++;
            newsym(x, y);
        }
    }
    return madepool;
}

function nextInventoryLetter() {
    const used = new Set((game.inventory || []).map(item => item.letter).filter(Boolean));
    let index = game._nextInventoryLetterIndex ?? Math.max(-1,
        ...(game.inventory || []).map(item => INVENTORY_LETTERS.indexOf(item.letter)).filter(i => i >= 0)) + 1;
    while (used.has(INVENTORY_LETTERS[index]) && index < INVENTORY_LETTERS.length - 1) index++;
    game._nextInventoryLetterIndex = Math.min(INVENTORY_LETTERS.length, index + 1);
    return INVENTORY_LETTERS[index] || INVENTORY_LETTERS[INVENTORY_LETTERS.length - 1];
}

function simulatedNextInventoryLetters(count) {
    const used = new Set((game.inventory || []).map(item => item.letter).filter(Boolean));
    let index = game._nextInventoryLetterIndex ?? Math.max(-1,
        ...(game.inventory || []).map(item => INVENTORY_LETTERS.indexOf(item.letter)).filter(i => i >= 0)) + 1;
    const letters = [];
    for (let i = 0; i < count; i++) {
        while (used.has(INVENTORY_LETTERS[index]) && index < INVENTORY_LETTERS.length - 1) index++;
        const letter = INVENTORY_LETTERS[index];
        if (!letter || used.has(letter)) return null;
        letters.push(letter);
        used.add(letter);
        index = Math.min(INVENTORY_LETTERS.length, index + 1);
    }
    return letters;
}

function updateMoneyLine(money) {
    if (money) money.line = `$ - ${money.quan || 0} gold piece${(money.quan || 0) === 1 ? '' : 's'}`;
}

function compactInventoryLetters(letters) {
    let range = '';
    let runStart = '';
    let previous = '';
    for (const letter of String(letters || '')) {
        if (!runStart) {
            runStart = letter;
        } else if (letter.charCodeAt(0) !== previous.charCodeAt(0) + 1) {
            const length = previous.charCodeAt(0) - runStart.charCodeAt(0) + 1;
            range += length > 2 ? `${runStart}-${previous}` : `${runStart}${length === 2 ? previous : ''}`;
            runStart = letter;
        }
        previous = letter;
    }
    if (!runStart) return range;
    const length = previous.charCodeAt(0) - runStart.charCodeAt(0) + 1;
    return range + (length > 2 ? `${runStart}-${previous}` : `${runStart}${length === 2 ? previous : ''}`);
}

function getobjPromptLetters(letters) {
    const text = String(letters || '');
    return text.length > 5 ? compactInventoryLetters(text) : text;
}

function isApplyCoinObject(item) {
    return shopBillableGold(item);
}

function applyInventoryItems() {
    const items = [...(game.inventory || [])];
    const goldCount = Math.max(0, Math.trunc(Number(game._goldCount || 0)));
    if (goldCount > 0 && !items.some(isApplyCoinObject)) {
        items.unshift({
            letter: '$',
            cls: 'coin',
            otyp: GOLD_PIECE,
            glyph: '$',
            quan: goldCount,
        });
    }
    return items;
}

function potionIdentityKnownForApply(item, identity) {
    const name = inventoryItemName(item).toLowerCase();
    const visibleKind = String(item?.kind || '').toLowerCase().replace(/^potion of /, '');
    return item?.known === true
        || potionDiscoveryKnown(identity)
        || name.includes(`potion of ${identity}`)
        || (item?.known !== false && visibleKind === identity);
}

const GRAY_STONE_APPLY_NAMES = new Set(['luckstone', 'loadstone', 'touchstone', 'flint', 'flint stone']);

function grayStoneNameForApply(item) {
    const values = [
        item?.actualKind,
        item?.kind,
        objectKindKey(item),
        item?.gemDescription,
        item?.displayName,
    ].map(value => String(value || '').toLowerCase().trim()).filter(Boolean);
    if (item?.otyp === LUCKSTONE) return 'luckstone';
    if (item?.otyp === LOADSTONE) return 'loadstone';
    if (item?.otyp === TOUCHSTONE) return 'touchstone';
    if (item?.otyp === FLINT) return 'flint';
    for (const value of values) {
        if (GRAY_STONE_APPLY_NAMES.has(value)) return value === 'flint stone' ? 'flint' : value;
    }
    if (values.some(value => value === 'gray stone' || value === 'grey stone'))
        return String(item?.actualKind || item?.kind || '').toLowerCase().trim();
    return '';
}

function isGrayStoneApplyItem(item) {
    if (!item) return false;
    if ([LUCKSTONE, LOADSTONE, TOUCHSTONE, FLINT].includes(item.otyp)) return true;
    if (GRAY_STONE_APPLY_NAMES.has(grayStoneNameForApply(item))) return true;
    const description = String(item.gemDescription || '').toLowerCase();
    return (itemClassKey(item) === 'gem' || item.glyph === '*')
        && (description === 'gray stone' || description === 'grey stone');
}

function gemStoneDiscoveryKnown(name) {
    const key = String(name || '').toLowerCase().trim();
    if (!key) return false;
    return (game._discoveries || []).some(entry =>
        ['Gems/Stones', 'Gems'].includes(entry.section)
        && String(entry.name || '').toLowerCase() === key
        && entry.known !== false);
}

function isTouchstoneApplyItem(item) {
    return !!item && (item.otyp === TOUCHSTONE || grayStoneNameForApply(item) === 'touchstone');
}

function touchstoneKnownForApply(item) {
    return isTouchstoneApplyItem(item)
        && item?.dknown !== false
        && (item?.known === true
            || gemStoneDiscoveryKnown('touchstone')
            || (String(item?.kind || '').toLowerCase() === 'touchstone' && item?.known !== false));
}

function grayStoneSelectionKind(item) {
    if (!isGrayStoneApplyItem(item)) return '';
    if (item?.dknown === false) return 'suggest';
    if (isTouchstoneApplyItem(item)) return 'suggest';
    const name = grayStoneNameForApply(item);
    if (item?.known === true || gemStoneDiscoveryKnown('touchstone') || gemStoneDiscoveryKnown(name))
        return 'selectableInvalid';
    return 'suggest';
}

function applySelectionKind(item) {
    if (!item) return 'exclude';
    if (isApplyCoinObject(item)) return 'downplay';

    const name = inventoryItemName(item).toLowerCase();
    const cls = itemClassKey(item);
    if (cls === 'tool' || item.section === 'Tools' || isIceBoxObject(item)) return 'suggest';
    if (isWandItem(item) || cls === 'wand' || item.kind === 'wand of sleep' || item.otyp === WAND_CLASS) return 'suggest';
    if (cls === 'spellbook') return 'suggest';
    if (cls === 'weapon' && APPLY_WEAPON_NAME_RE.test(name)) return 'suggest';
    if (/lamp|camera|card|bag|sack|cream pie/.test(name)) return 'suggest';
    if (isRoyalJelly(item)) return 'suggest';
    if (isPotionObject(item)) {
        const identity = potionIdentityName(item) || objectKindKey(item).replace(/^potion of /, '');
        if (isPotionOfOil(item) && potionIdentityKnownForApply(item, 'oil')) return 'suggest';
        if (!identity || !potionIdentityKnownForApply(item, identity)) return 'downplay';
        return 'selectableInvalid';
    }
    const grayStoneKind = grayStoneSelectionKind(item);
    if (grayStoneKind) return grayStoneKind;
    if (heroIsHallucinating() && /banana/.test(name)) return 'downplay';
    return 'selectableInvalid';
}

function applyItemsBySelectionKind(kind) {
    return applyInventoryItems().filter(item => applySelectionKind(item) === kind && item.letter);
}

function applyPromptMessage() {
    const suggested = applyItemsBySelectionKind('suggest').map(item => item.letter).join('');
    if (suggested) return `What do you want to use or apply? [${getobjPromptLetters(suggested)} or ?*]`;
    if (applyItemsBySelectionKind('downplay').length) return 'What do you want to use or apply? [*]';
    return '';
}

function applyMenuItems(ch) {
    if (ch === '*') return applyInventoryItems().filter(item => item.letter);
    const suggested = applyItemsBySelectionKind('suggest');
    return suggested.length ? suggested : applyItemsBySelectionKind('downplay');
}

function applyMenuSection(item) {
    const cls = itemClassKey(item);
    if (isApplyCoinObject(item)) return 'Coins';
    if (cls === 'spellbook') return 'Spellbooks';
    if (isWandItem(item) || cls === 'wand' || item.kind === 'wand of sleep' || item.otyp === WAND_CLASS) return 'Wands';
    if (cls === 'tool' || item.section === 'Tools' || isIceBoxObject(item)) return 'Tools';
    if (cls === 'weapon') return 'Weapons';
    if (isPotionObject(item)) return 'Potions';
    if (cls === 'scroll') return 'Scrolls';
    if (cls === 'armor') return 'Armor';
    if (cls === 'food') return 'Comestibles';
    return 'Other Items';
}

function setApplyObjectMenu(items) {
    const order = ['Spellbooks', 'Wands', 'Tools', 'Weapons', 'Potions', 'Scrolls', 'Armor', 'Comestibles', 'Coins', 'Other Items'];
    const sorted = [...items].sort((a, b) => {
        const sectionDiff = order.indexOf(applyMenuSection(a)) - order.indexOf(applyMenuSection(b));
        return sectionDiff || String(a.letter || '').localeCompare(String(b.letter || ''));
    });
    const rows = [];
    let row = 0, lastSection = '';
    for (const item of sorted) {
        const section = applyMenuSection(item);
        if (section !== lastSection) {
            rows.push([row, 40, ' ']);
            rows.push([row++, 41, section, 1]);
            lastSection = section;
        }
        rows.push([row++, 40, ` ${normalInventoryLine(item)}`.padEnd(40, ' ')]);
    }
    rows.push([row, 40, ' (end)'.padEnd(40, ' ')]);
    setOverlay(rows, 2, false, 0);
}

function findApplyInventoryItem(letter) {
    return applyInventoryItems().find(invItem => invItem.letter === letter);
}

function useStonePromptAction(stone) {
    const count = Math.max(1, Math.trunc(Number(stone?.quan || 1)));
    return `rub on the stone${count > 1 ? 's' : ''}`;
}

function useStoneTargetSelectionKind(item, stone) {
    if (!item) return 'exclude';
    if (!touchstoneKnownForApply(stone)) return 'suggest';
    if (isApplyCoinObject(item)) return 'suggest';
    const cls = itemClassKey(item);
    const gemKnown = item?.dknown !== false
        && (item?.known === true || gemStoneDiscoveryKnown(grayStoneNameForApply(item) || item?.actualKind || item?.kind));
    if ((cls === 'gem' || item.glyph === '*') && !gemKnown) return 'suggest';
    return 'downplay';
}

function useStoneTargetItemsBySelectionKind(kind, stone) {
    return applyInventoryItems().filter(item => useStoneTargetSelectionKind(item, stone) === kind && item.letter);
}

function useStonePromptMessage(stone) {
    const action = useStonePromptAction(stone);
    const suggested = useStoneTargetItemsBySelectionKind('suggest', stone).map(item => item.letter).join('');
    if (suggested) return `What do you want to ${action}? [${getobjPromptLetters(suggested)} or ?*]`;
    if (useStoneTargetItemsBySelectionKind('downplay', stone).length) return `What do you want to ${action}? [*]`;
    return `What do you want to ${action}?`;
}

function useStoneMenuItems(ch, stone) {
    if (ch === '*') return applyInventoryItems().filter(item => item.letter);
    const suggested = useStoneTargetItemsBySelectionKind('suggest', stone);
    return suggested.length ? suggested : useStoneTargetItemsBySelectionKind('downplay', stone);
}

function setUseStoneObjectMenu(items) {
    setApplyObjectMenu(items);
}

function theUseStoneObjectName(item) {
    return `the ${pickupObjectName(item)}`;
}

function observeUseStoneSource(stone) {
    if (!stone || game.u?.blind) return;
    stone.dknown = true;
    const name = grayStoneNameForApply(stone);
    if (stone.known === true || gemStoneDiscoveryKnown(name)) return;
    game._discoveries ??= [];
    if (!(game._discoveries || []).some(entry =>
        entry.section === 'Gems/Stones' && entry.name === 'gray stone')) {
        game._discoveries.push({
            section: 'Gems/Stones',
            name: 'gray stone',
            text: 'gray stone',
            starred: false,
            known: false,
        });
    }
}

